(372236,41360,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devine quoi, il m''a dit : je promets que je ... plus un leg day aussi douloureux.'::text,'ne ferai'::text,'ne serai pas en train de faire'::text,'ne fais'::text,'Devine quoi, il m''a dit : je promets que je ne ferai plus un leg day aussi douloureux.'::text),
(372239,41360,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tahmin et ne oldu, bana dedi ki: Söz veriyorum, ben bu kadar acı veren bir bacak gününü bir daha ...'::text,'yapmayacağım'::text,'yapıyor olmayacağım'::text,'yapmıyorum'::text,'Tahmin et ne oldu, bana dedi ki: Söz veriyorum, ben bu kadar acı veren bir bacak gününü bir daha yapmayacağım.'::text),
(372240,41360,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld, azt mondta nekem: Megígérem, hogy én még egy ilyen fájdalmas lábnapot ...'::text,'nem csinálok'::text,'nem fogok csinálni'::text,'nem csinálok'::text,'Képzeld, azt mondta nekem: Megígérem, hogy én még egy ilyen fájdalmas lábnapot nem csinálok.'::text),
(372279,41365,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Klar, bis Montag werden sie diesen schmerzhaften Leg Day komplett ...'::text,'vergessen haben'::text,'vergessen'::text,'vergessen'::text,'Klar, bis Montag werden sie diesen schmerzhaften Leg Day komplett vergessen haben.'::text),
(372283,41365,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Звісно, до понеділка вони ... все про цей болючий день ніг.'::text,'забудуть'::text,'забудуть'::text,'забувають'::text,'Звісно, до понеділка вони забудуть все про цей болючий день ніг.'::text),
(372282,41365,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Obviamente, para el lunes ellos ... todo sobre este doloroso día de pierna.'::text,'habrán olvidado'::text,'olvidarán'::text,'están olvidando'::text,'Obviamente, para el lunes ellos habrán olvidado todo sobre este doloroso día de pierna.'::text),
(372281,41365,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Évidemment, d''ici lundi, ils ... tout de ce leg day douloureux.'::text,'auront oublié'::text,'oublieront'::text,'sont en train d''oublier'::text,'Évidemment, d''ici lundi, ils auront oublié tout de ce leg day douloureux.'::text),
(372284,41365,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tabii ki pazartesiye kadar onlar bu acı veren bacak gününü tamamen ...'::text,'unutmuş olacaklar'::text,'unutacaklar'::text,'unutuyorlar'::text,'Tabii ki pazartesiye kadar onlar bu acı veren bacak gününü tamamen unutmuş olacaklar.'::text),
(372285,41365,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Persze hétfőre ők teljesen ... ezt a fájdalmas lábnapot.'::text,'elfelejtik'::text,'el fogják felejteni'::text,'felejtik'::text,'Persze hétfőre ők teljesen elfelejtik ezt a fájdalmas lábnapot.'::text),
(387444,43050,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gerade ... der Löwe auf der Klippe, also ist die Savanne alles andere als still.'::text,'brüllt'::text,'brüllt'::text,'hat gebrüllt'::text,'Gerade brüllt der Löwe auf der Klippe, also ist die Savanne alles andere als still.'::text),
(387448,43050,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Просто зараз лев ... на скелі, тож савана аж ніяк не тиха.'::text,'реве'::text,'реве'::text,'заревів'::text,'Просто зараз лев реве на скелі, тож савана аж ніяк не тиха.'::text),
(387447,43050,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahora mismo el león ... en el acantilado, así que la sabana está lejos de estar en silencio.'::text,'está rugiendo'::text,'ruge'::text,'ha rugido'::text,'Ahora mismo el león está rugiendo en el acantilado, así que la sabana está lejos de estar en silencio.'::text),
(387446,43050,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment, le lion ... sur la falaise, donc la savane est loin d''être silencieuse.'::text,'rugit'::text,'rugit'::text,'a rugi'::text,'En ce moment, le lion rugit sur la falaise, donc la savane est loin d''être silencieuse.'::text),
(387449,43050,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda aslan uçurumda ..., yani savana hiç de sessiz değil.'::text,'kükrüyor'::text,'kükrer'::text,'kükredi'::text,'Şu anda aslan uçurumda kükrüyor, yani savana hiç de sessiz değil.'::text),
(387450,43050,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp most az oroszlán ... a sziklán, így a szavanna távolról sem csendes.'::text,'bőg'::text,'bőg'::text,'bőgött'::text,'Épp most az oroszlán bőg a sziklán, így a szavanna távolról sem csendes.'::text),
(386661,42963,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Türen ... mit einer Kette und einem Vorhängeschloss verschlossen gehalten, wie jede Nacht.'::text,'werden'::text,'halten'::text,'wurden'::text,'Die Türen werden mit einer Kette und einem Vorhängeschloss verschlossen gehalten, wie jede Nacht.'::text),
(386665,42963,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Двері ... зачиненими на ланцюг і навісний замок, як і щоночі.'::text,'тримають'::text,'тримають'::text,'тримали'::text,'Двері тримають зачиненими на ланцюг і навісний замок, як і щоночі.'::text),
(386664,42963,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las puertas ... cerradas con una cadena y un candado, como todas las noches.'::text,'se mantienen'::text,'mantienen'::text,'se mantuvieron'::text,'Las puertas se mantienen cerradas con una cadena y un candado, como todas las noches.'::text),
(386663,42963,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les portes ... fermées avec une chaîne et un cadenas, comme chaque nuit.'::text,'sont gardées'::text,'gardent'::text,'étaient gardées'::text,'Les portes sont gardées fermées avec une chaîne et un cadenas, comme chaque nuit.'::text),
(386666,42963,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kapılar, her gece olduğu gibi, zincir ve asma kilitle kapalı ...'::text,'tutulur'::text,'tutar'::text,'tutuldu'::text,'Kapılar, her gece olduğu gibi, zincir ve asma kilitle kapalı tutulur.'::text),
(386667,42963,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az ajtókat lánccal és lakattal zárva ..., mint minden éjjel.'::text,'tartják'::text,'tartják'::text,'tartották'::text,'Az ajtókat lánccal és lakattal zárva tartják, mint minden éjjel.'::text),
(366321,40703,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... gerade ins Mikrofon, als er sah, dass er die Wahl verloren hatte.'::text,'sprach'::text,'sprach'::text,'hat gesprochen'::text,'Er sprach gerade ins Mikrofon, als er sah, dass er die Wahl verloren hatte.'::text),
(366325,40703,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... в мікрофон, коли побачив, що програв вибори.'::text,'говорив'::text,'сказав'::text,'сказав'::text,'Він говорив в мікрофон, коли побачив, що програв вибори.'::text),
(366324,40703,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... por el micrófono cuando vio que había perdido las elecciones.'::text,'estaba hablando'::text,'habló'::text,'ha hablado'::text,'Él estaba hablando por el micrófono cuando vio que había perdido las elecciones.'::text),
(366323,40703,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... au micro quand il a vu qu''il avait perdu l''élection.'::text,'parlait'::text,'a parlé'::text,'a parlé'::text,'Il parlait au micro quand il a vu qu''il avait perdu l''élection.'::text),
(366326,40703,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, seçimi kaybettiğini gördüğünde mikrofona ...'::text,'konuşuyordu'::text,'konuştu'::text,'konuştu'::text,'O, seçimi kaybettiğini gördüğünde mikrofona konuşuyordu.'::text),
(366327,40703,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő éppen ... a mikrofonba, amikor látta, hogy elvesztette a választást.'::text,'beszélt'::text,'szólt'::text,'szólt'::text,'Ő éppen beszélt a mikrofonba, amikor látta, hogy elvesztette a választást.'::text),
(366411,40713,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum Ende des Abends ... jeder Gast den Saal verlassen haben, in dem er verloren hat.'::text,'wird'::text,'wird'::text,'verlässt'::text,'Bis zum Ende des Abends wird jeder Gast den Saal verlassen haben, in dem er verloren hat.'::text),
(366415,40713,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До кінця вечора кожен гість ... залу, де він програв.'::text,'покине'::text,'покине'::text,'покидає'::text,'До кінця вечора кожен гість покине залу, де він програв.'::text),
(366414,40713,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el final de la noche, cada invitado ... el salón donde él perdió.'::text,'habrá dejado'::text,'dejará'::text,'deja'::text,'Para el final de la noche, cada invitado habrá dejado el salón donde él perdió.'::text),
(366413,40713,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici la fin de la soirée, chaque invité ... la salle où il a perdu.'::text,'aura quitté'::text,'quittera'::text,'quitte'::text,'D''ici la fin de la soirée, chaque invité aura quitté la salle où il a perdu.'::text),
(366416,40713,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gecenin sonunda her misafir, onun kaybettiği salondan ...'::text,'ayrılmış olacak'::text,'ayrılacak'::text,'ayrılıyor'::text,'Gecenin sonunda her misafir, onun kaybettiği salondan ayrılmış olacak.'::text),
(366417,40713,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az este végére minden vendég ... a termet, ahol ő veszített.'::text,'elhagyja'::text,'el fogja hagyni'::text,'elhagyja'::text,'Az este végére minden vendég elhagyja a termet, ahol ő veszített.'::text),
(366456,40718,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihr Pass ... vor der Check-out-Frist um 9 Uhr im Hostel verloren.'::text,'ging'::text,'verlor'::text,'verliert'::text,'Ihr Pass ging vor der Check-out-Frist um 9 Uhr im Hostel verloren.'::text),
(366460,40718,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її паспорт ... у хостелі до кінцевого терміну виїзду о 9:00.'::text,'був загублений'::text,'загубив'::text,'губить'::text,'Її паспорт був загублений у хостелі до кінцевого терміну виїзду о 9:00.'::text),
(366459,40718,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su pasaporte ... en el albergue antes del plazo de salida de las 9:00.'::text,'se perdió'::text,'perdió'::text,'está perdiendo'::text,'Su pasaporte se perdió en el albergue antes del plazo de salida de las 9:00.'::text),
(366458,40718,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son passeport ... à l''auberge de jeunesse avant la limite de départ de 9 h.'::text,'a été perdu'::text,'a perdu'::text,'est en train de perdre'::text,'Son passeport a été perdu à l''auberge de jeunesse avant la limite de départ de 9 h.'::text),
(366461,40718,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onun pasaportu, sabah 9''daki çıkış saatinden önce hostelde ...'::text,'kayboldu'::text,'kaybetti'::text,'kaybediyor'::text,'Onun pasaportu, sabah 9''daki çıkış saatinden önce hostelde kayboldu.'::text),
(366462,40718,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az útlevele ... a hosztelben a reggel 9 órás kijelentkezési határidő előtt.'::text,'elveszett'::text,'elvesztette'::text,'elveszít'::text,'Az útlevele elveszett a hosztelben a reggel 9 órás kijelentkezési határidő előtt.'::text),
(366528,40726,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie setzte sich aufs Bett, weil sie ihren Pass ... und ihn nicht finden konnte.'::text,'verloren hatte'::text,'verlor'::text,'verloren hat'::text,'Sie setzte sich aufs Bett, weil sie ihren Pass verloren hatte und ihn nicht finden konnte.'::text),
(366532,40726,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона сіла на ліжко, бо ... паспорт і не могла його знайти.'::text,'загубила'::text,'губила'::text,'загубила'::text,'Вона сіла на ліжко, бо загубила паспорт і не могла його знайти.'::text),
(366531,40726,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella se sentó en la cama porque ... su pasaporte y no podía encontrarlo.'::text,'había perdido'::text,'estaba perdiendo'::text,'ha perdido'::text,'Ella se sentó en la cama porque había perdido su pasaporte y no podía encontrarlo.'::text),
(366530,40726,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle s''est assise sur le lit parce qu''elle ... son passeport et ne le trouvait pas.'::text,'avait perdu'::text,'perdait'::text,'a perdu'::text,'Elle s''est assise sur le lit parce qu''elle avait perdu son passeport et ne le trouvait pas.'::text),
(366533,40726,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O yatağa oturdu çünkü pasaportunu ... ve bulamıyordu.'::text,'kaybetmişti'::text,'kaybediyordu'::text,'kaybetti'::text,'O yatağa oturdu çünkü pasaportunu kaybetmişti ve bulamıyordu.'::text),
(366534,40726,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő leült az ágyra, mert ... az útlevelét, és nem találta.'::text,'elvesztette'::text,'vesztette'::text,'elvesztette'::text,'Ő leült az ágyra, mert elvesztette az útlevelét, és nem találta.'::text),
(363702,40412,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dieses Verhalten wurde beobachtet, während die Reisende ein Etikett am Koffer ...'::text,'befestigte'::text,'befestigte'::text,'hat befestigt'::text,'Dieses Verhalten wurde beobachtet, während die Reisende ein Etikett am Koffer befestigte.'::text),
(363706,40412,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Цю поведінку спостерігали, коли мандрівниця ... бирку до валізи.'::text,'прикріплювала'::text,'прикріпила'::text,'прикріпила'::text,'Цю поведінку спостерігали, коли мандрівниця прикріплювала бирку до валізи.'::text),
(363705,40412,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Este comportamiento se observó mientras la viajera ... una etiqueta a la maleta.'::text,'estaba colocando'::text,'colocó'::text,'ha colocado'::text,'Este comportamiento se observó mientras la viajera estaba colocando una etiqueta a la maleta.'::text),
(363704,40412,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ce comportement a été observé pendant que la voyageuse ... une étiquette à la valise.'::text,'attachait'::text,'a attaché'::text,'a attaché'::text,'Ce comportement a été observé pendant que la voyageuse attachait une étiquette à la valise.'::text),
(363707,40412,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu davranış, yolcu bavula bir etiket ... gözlemlendi.'::text,'takarken'::text,'taktığında'::text,'takmışken'::text,'Bu davranış, yolcu bavula bir etiket takarken gözlemlendi.'::text),
(363708,40412,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ezt a viselkedést akkor figyelték meg, amikor az utazó ... egy címkét a bőröndre.'::text,'éppen rögzített'::text,'rögzített'::text,'rögzítette'::text,'Ezt a viselkedést akkor figyelték meg, amikor az utazó éppen rögzített egy címkét a bőröndre.'::text),
(363792,40422,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Auf dem Gepäckband war ..., das sie an den Griff gebunden hatte, leicht zu erkennen.'::text,'das Etikett'::text,'ein Etikett'::text,'Etikett'::text,'Auf dem Gepäckband war das Etikett, das sie an den Griff gebunden hatte, leicht zu erkennen.'::text),
(363796,40422,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'На стрічці ..., яку вона прив''язала до ручки, було легко помітити.'::text,'бирку'::text,'бирку'::text,'бирку'::text,'На стрічці бирку, яку вона прив''язала до ручки, було легко помітити.'::text),
(363795,40422,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En la cinta, ... que ella había atado al asa era fácil de ver.'::text,'la etiqueta'::text,'una etiqueta'::text,'etiqueta'::text,'En la cinta, la etiqueta que ella había atado al asa era fácil de ver.'::text),
(363794,40422,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sur le tapis, ... qu''elle avait attachée à la poignée était facile à repérer.'::text,'l''étiquette'::text,'une étiquette'::text,'étiquette'::text,'Sur le tapis, l''étiquette qu''elle avait attachée à la poignée était facile à repérer.'::text),
(363797,40422,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bantta, onun sapa bağladığı ... kolayca fark ediliyordu.'::text,'etiket'::text,'bir etiket'::text,'etiket'::text,'Bantta, onun sapa bağladığı etiket kolayca fark ediliyordu.'::text),
(363798,40422,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A futószalagon könnyű volt észrevenni ..., amelyet ő a fogantyúra kötött.'::text,'a címkét'::text,'egy címkét'::text,'címkét'::text,'A futószalagon könnyű volt észrevenni a címkét, amelyet ő a fogantyúra kötött.'::text),
(365556,40618,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du hast jeden einzelnen Koffer in diesen Van gehoben, ...? Dein Rücken ist komplett hinüber!'::text,'oder'::text,'oder'::text,'oder'::text,'Du hast jeden einzelnen Koffer in diesen Van gehoben, oder? Dein Rücken ist komplett hinüber!'::text),
(365560,40618,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти підняв кожну валізу в той фургон, ...? Твоя спина повністю розбита!'::text,'так'::text,'так'::text,'так'::text,'Ти підняв кожну валізу в той фургон, так? Твоя спина повністю розбита!'::text),
(365559,40618,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tú subiste cada maleta a esa furgoneta, ¿...? ¡Tu espalda está completamente destrozada!'::text,'verdad'::text,'verdad'::text,'verdad'::text,'Tú subiste cada maleta a esa furgoneta, ¿verdad? ¡Tu espalda está completamente destrozada!'::text),
(365558,40618,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu as soulevé chaque valise dans ce van, ... ? Ton dos est complètement détruit !'::text,'n''est-ce pas'::text,'n''est-ce pas'::text,'n''est-ce pas'::text,'Tu as soulevé chaque valise dans ce van, n''est-ce pas ? Ton dos est complètement détruit !'::text),
(365561,40618,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sen her bir bavulu o minibüse kaldırdın, ...? Sırtın tamamen mahvoldu!'::text,'değil mi'::text,'değil mi'::text,'değil mi'::text,'Sen her bir bavulu o minibüse kaldırdın, değil mi? Sırtın tamamen mahvoldu!'::text),
(365562,40618,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Te minden egyes bőröndöt beemeltél abba a furgonba, ...? A hátad teljesen tönkrement!'::text,'ugye'::text,'ugye'::text,'ugye'::text,'Te minden egyes bőröndöt beemeltél abba a furgonba, ugye? A hátad teljesen tönkrement!'::text),
(365592,40622,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Mittag wird das Subjekt etwa eine Stunde lang schweres Gepäck ...'::text,'gehoben haben'::text,'heben'::text,'gehoben haben'::text,'Bis Mittag wird das Subjekt etwa eine Stunde lang schweres Gepäck gehoben haben.'::text),
(365596,40622,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До полудня суб''єкт ... важкий багаж приблизно годину.'::text,'підійматиме'::text,'підійматиме'::text,'підніме'::text,'До полудня суб''єкт підійматиме важкий багаж приблизно годину.'::text),
(365595,40622,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el mediodía, el sujeto ... equipaje pesado durante aproximadamente una hora.'::text,'habrá estado levantando'::text,'estará levantando'::text,'habrá levantado'::text,'Para el mediodía, el sujeto habrá estado levantando equipaje pesado durante aproximadamente una hora.'::text),
(365594,40622,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici midi, le sujet ... des bagages lourds depuis environ une heure.'::text,'aura soulevé'::text,'sera en train de soulever'::text,'aura soulevé'::text,'D''ici midi, le sujet aura soulevé des bagages lourds depuis environ une heure.'::text),
(365597,40622,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Öğlene kadar denek yaklaşık bir saattir ağır bagaj ...'::text,'kaldırıyor olacak'::text,'kaldırıyor olacak'::text,'kaldırmış olacak'::text,'Öğlene kadar denek yaklaşık bir saattir ağır bagaj kaldırıyor olacak.'::text),
(365598,40622,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Délre az alany már körülbelül egy órája ... nehéz csomagokat.'::text,'fog emelgetni'::text,'fog emelgetni'::text,'emelt'::text,'Délre az alany már körülbelül egy órája fog emelgetni nehéz csomagokat.'::text),
(367158,40796,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Klar, reiner Zufall: Das Zimmermädchen ... seit März für jeden Gast Handtuchschwäne.'::text,'faltet'::text,'faltet'::text,'faltet'::text,'Klar, reiner Zufall: Das Zimmermädchen faltet seit März für jeden Gast Handtuchschwäne.'::text),
(367162,40796,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Звісно, просто збіг: покоївка ... лебедів із рушників для кожного гостя з березня.'::text,'складає'::text,'складає'::text,'складає'::text,'Звісно, просто збіг: покоївка складає лебедів із рушників для кожного гостя з березня.'::text),
(367161,40796,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Claramente, pura casualidad: la camarera ... cisnes de toalla para cada huésped desde marzo.'::text,'lleva doblando'::text,'está doblando'::text,'dobla'::text,'Claramente, pura casualidad: la camarera lleva doblando cisnes de toalla para cada huésped desde marzo.'::text),
(367160,40796,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Clairement, une pure coïncidence : la femme de chambre ... des cygnes en serviette pour chaque client depuis mars.'::text,'plie'::text,'plie'::text,'plie'::text,'Clairement, une pure coïncidence : la femme de chambre plie des cygnes en serviette pour chaque client depuis mars.'::text),
(367163,40796,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belli ki sadece tesadüf: kat görevlisi marttan beri her misafir için havludan kuğu ...'::text,'katlıyor'::text,'katlıyor'::text,'katlar'::text,'Belli ki sadece tesadüf: kat görevlisi marttan beri her misafir için havludan kuğu katlıyor.'::text),
(367164,40796,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyilván csak véletlen: a szobalány március óta minden vendégnek törölközőhattyút ...'::text,'hajtogat'::text,'hajtogat'::text,'hajtogat'::text,'Nyilván csak véletlen: a szobalány március óta minden vendégnek törölközőhattyút hajtogat.'::text),
(367401,40823,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Spielzeug ... dem kleinsten Kerlchen, das es natürlich wie ein Profi packte.'::text,'wurde hingehalten'::text,'hielt hin'::text,'hält hin'::text,'Das Spielzeug wurde hingehalten dem kleinsten Kerlchen, das es natürlich wie ein Profi packte.'::text),
(367405,40823,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Іграшку ... найменшому хлопчикові, який, звісно, схопив її як професіонал.'::text,'простягнули'::text,'простягнула'::text,'простягає'::text,'Іграшку простягнули найменшому хлопчикові, який, звісно, схопив її як професіонал.'::text),
(367404,40823,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El juguete ... al varón más pequeño, que obviamente lo agarró como un profesional.'::text,'fue ofrecido'::text,'ofreció'::text,'está ofreciendo'::text,'El juguete fue ofrecido al varón más pequeño, que obviamente lo agarró como un profesional.'::text),
(367403,40823,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le jouet ... au plus petit garçon, qui l''a évidemment attrapé comme un pro.'::text,'a été tendu'::text,'a tendu'::text,'est en train de tendre'::text,'Le jouet a été tendu au plus petit garçon, qui l''a évidemment attrapé comme un pro.'::text),
(367406,40823,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oyuncak, onu tabii ki bir profesyonel gibi kapan en küçük erkeğe ...'::text,'uzatıldı'::text,'uzattı'::text,'uzatıyor'::text,'Oyuncak, onu tabii ki bir profesyonel gibi kapan en küçük erkeğe uzatıldı.'::text),
(367407,40823,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A játékot ... a legkisebb fiúnak, aki persze profi módjára elkapta.'::text,'odanyújtották'::text,'odanyújtotta'::text,'odanyújtja'::text,'A játékot odanyújtották a legkisebb fiúnak, aki persze profi módjára elkapta.'::text),
(367428,40826,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zur Deadline wird dieser Mann 500 Klimmzüge an der Stange im Park ...'::text,'gemacht haben'::text,'machen'::text,'macht'::text,'Bis zur Deadline wird dieser Mann 500 Klimmzüge an der Stange im Park gemacht haben.'::text),
(367432,40826,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До дедлайну цей чоловік ... 500 підтягувань на турніку в парку.'::text,'зробить'::text,'зробить'::text,'робить'::text,'До дедлайну цей чоловік зробить 500 підтягувань на турніку в парку.'::text),
(367431,40826,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para la fecha límite, este hombre ... 500 dominadas en la barra del parque.'::text,'habrá hecho'::text,'hará'::text,'hace'::text,'Para la fecha límite, este hombre habrá hecho 500 dominadas en la barra del parque.'::text),
(367430,40826,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici la deadline, cet homme ... 500 tractions à la barre du parc.'::text,'aura fait'::text,'fera'::text,'fait'::text,'D''ici la deadline, cet homme aura fait 500 tractions à la barre du parc.'::text),
(367433,40826,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son tarihe kadar bu erkek parktaki barfiks demirinde 500 barfiks ...'::text,'yapmış olacak'::text,'yapacak'::text,'yapıyor'::text,'Son tarihe kadar bu erkek parktaki barfiks demirinde 500 barfiks yapmış olacak.'::text),
(367434,40826,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A határidőre ez a férfi ... 500 húzódzkodást a parki rúdon.'::text,'megcsinál'::text,'meg fog csinálni'::text,'csinál'::text,'A határidőre ez a férfi megcsinál 500 húzódzkodást a parki rúdon.'::text),
(331131,36793,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er wünscht sich total, seine Wohnung ... ein Aquarium mit Haien!'::text,'hätte'::text,'hat'::text,'wird haben'::text,'Er wünscht sich total, seine Wohnung hätte ein Aquarium mit Haien!'::text),
(331135,36793,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він страшенно хоче, щоб його квартира ... акваріум з акулами!'::text,'мала'::text,'має'::text,'матиме'::text,'Він страшенно хоче, щоб його квартира мала акваріум з акулами!'::text),
(331134,36793,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Él desea con todas sus fuerzas que su piso ... un acuario con tiburones!'::text,'tuviera'::text,'tiene'::text,'tendrá'::text,'¡Él desea con todas sus fuerzas que su piso tuviera un acuario con tiburones!'::text),
(331133,36793,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il souhaite vraiment que son appart ... un aquarium avec des requins !'::text,'ait'::text,'a'::text,'aura'::text,'Il souhaite vraiment que son appart ait un aquarium avec des requins !'::text),
(331136,36793,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, dairesinde köpekbalıklı bir akvaryum ... gerçekten çok istiyor!'::text,'olmasını'::text,'var'::text,'olacak'::text,'O, dairesinde köpekbalıklı bir akvaryum olmasını gerçekten çok istiyor!'::text),
(331137,36793,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő nagyon szeretné, ha a lakásában ... egy cápás akvárium!'::text,'lenne'::text,'van'::text,'lesz'::text,'Ő nagyon szeretné, ha a lakásában lenne egy cápás akvárium!'::text),
(398910,44324,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Kapelle ... den ganzen Vormittag Trompete, also wurden die Trompeten den ganzen Vormittag gespielt.'::text,'spielt'::text,'spielte'::text,'spielt gerade'::text,'Die Kapelle spielt den ganzen Vormittag Trompete, also wurden die Trompeten den ganzen Vormittag gespielt.'::text),
(398914,44324,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Оркестр ... на трубах увесь ранок, тож на трубах грали увесь ранок.'::text,'грає'::text,'грав'::text,'грає'::text,'Оркестр грає на трубах увесь ранок, тож на трубах грали увесь ранок.'::text),
(398913,44324,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La banda ... las trompetas toda la mañana, así que las trompetas se han tocado toda la mañana.'::text,'lleva tocando'::text,'tocó'::text,'está tocando'::text,'La banda lleva tocando las trompetas toda la mañana, así que las trompetas se han tocado toda la mañana.'::text),
(398912,44324,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La fanfare ... de la trompette toute la matinée, donc les trompettes ont été jouées toute la matinée.'::text,'joue'::text,'a joué'::text,'est en train de jouer'::text,'La fanfare joue de la trompette toute la matinée, donc les trompettes ont été jouées toute la matinée.'::text),
(398915,44324,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bando bütün sabah trompet ..., yani trompetler bütün sabah çalındı.'::text,'çalıyor'::text,'çaldı'::text,'çalıyor'::text,'Bando bütün sabah trompet çalıyor, yani trompetler bütün sabah çalındı.'::text),
(398916,44324,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A zenekar egész délelőtt ... a trombitákon, szóval a trombitákon egész délelőtt játszottak.'::text,'játszik'::text,'játszott'::text,'játszik'::text,'A zenekar egész délelőtt játszik a trombitákon, szóval a trombitákon egész délelőtt játszottak.'::text),
(398964,44330,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... der Trompeten erfüllte die ganze Allee.'::text,'Der Klang'::text,'Ein Klang'::text,'Klang'::text,'Der Klang der Trompeten erfüllte die ganze Allee.'::text),
(398968,44330,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... труб заповнив увесь проспект.'::text,'Звук'::text,'Звук'::text,'Звук'::text,'Звук труб заповнив увесь проспект.'::text),
(398967,44330,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... de las trompetas llenó toda la avenida.'::text,'El sonido'::text,'Un sonido'::text,'Sonido'::text,'El sonido de las trompetas llenó toda la avenida.'::text),
(398966,44330,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... des trompettes a rempli toute l''avenue.'::text,'Le son'::text,'Un son'::text,'Son'::text,'Le son des trompettes a rempli toute l''avenue.'::text),
(398969,44330,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Trompetlerin ... bütün caddeyi doldurdu.'::text,'sesi'::text,'bir sesi'::text,'sesi'::text,'Trompetlerin sesi bütün caddeyi doldurdu.'::text),
(398970,44330,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A trombiták ... betöltötte az egész sugárutat.'::text,'hangja'::text,'egy hangja'::text,'hangja'::text,'A trombiták hangja betöltötte az egész sugárutat.'::text),
(329790,36644,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, der Gang, ... er entlangläuft, ist irgendwie ikonisch.'::text,'den'::text,'der'::text,'dessen'::text,'Alter, der Gang, den er entlangläuft, ist irgendwie ikonisch.'::text),
(329794,36644,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, прохід, ... він іде, якийсь культовий.'::text,'яким'::text,'хто'::text,'чий'::text,'Чувак, прохід, яким він іде, якийсь культовий.'::text),
(329793,36644,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, el pasillo por ... camina él es bastante icónico.'::text,'el que'::text,'quien'::text,'cuyo'::text,'Tío, el pasillo por el que camina él es bastante icónico.'::text),
(329792,36644,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, l''allée dans ... il marche est grave iconique.'::text,'laquelle'::text,'qui'::text,'dont'::text,'Mec, l''allée dans laquelle il marche est grave iconique.'::text),
(329795,36644,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, onun ... koridor baya ikonik.'::text,'yürüdüğü'::text,'kim'::text,'kimin'::text,'Kanka, onun yürüdüğü koridor baya ikonik.'::text),
(329796,36644,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a folyosó, ... ő végigsétál, elég ikonikus.'::text,'amelyen'::text,'aki'::text,'akinek a'::text,'Tesó, a folyosó, amelyen ő végigsétál, elég ikonikus.'::text),
(368130,40904,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nachdem sie auf jedem Bett gelegen hat, entscheidet sie: Sie ... die große Matratze kaufen.'::text,'wird'::text,'wird'::text,'kauft'::text,'Nachdem sie auf jedem Bett gelegen hat, entscheidet sie: Sie wird die große Matratze kaufen.'::text),
(368134,40904,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Полежавши на кожному ліжку, вона вирішує: вона ... великий матрац.'::text,'купить'::text,'купуватиме'::text,'купує'::text,'Полежавши на кожному ліжку, вона вирішує: вона купить великий матрац.'::text),
(368133,40904,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Después de tumbarse en todas las camas, ella decide: ... el colchón grande.'::text,'comprará'::text,'estará comprando'::text,'compra'::text,'Después de tumbarse en todas las camas, ella decide: comprará el colchón grande.'::text),
(368132,40904,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Après s''être allongée sur chaque lit, elle décide : elle ... le grand matelas.'::text,'achètera'::text,'sera en train d''acheter'::text,'achète'::text,'Après s''être allongée sur chaque lit, elle décide : elle achètera le grand matelas.'::text),
(368135,40904,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Her yatağa uzandıktan sonra o karar veriyor: büyük yatağı ...'::text,'alacak'::text,'alıyor olacak'::text,'alıyor'::text,'Her yatağa uzandıktan sonra o karar veriyor: büyük yatağı alacak.'::text),
(368136,40904,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Miután minden ágyon feküdt, ő dönt: ... a nagy matracot.'::text,'megveszi'::text,'venni fogja'::text,'veszi'::text,'Miután minden ágyon feküdt, ő dönt: megveszi a nagy matracot.'::text),
(368211,40913,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... eine Minute auf der harten Matratze gesessen, bevor sie schrie, dass das eine Katastrophe sei!'::text,'hatte'::text,'hat'::text,'sitzt'::text,'Sie hatte eine Minute auf der harten Matratze gesessen, bevor sie schrie, dass das eine Katastrophe sei!'::text),
(368215,40913,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... на твердому матраці хвилину, перш ніж закричала, що це катастрофа!'::text,'сиділа'::text,'сидить'::text,'сидить'::text,'Вона сиділа на твердому матраці хвилину, перш ніж закричала, що це катастрофа!'::text),
(368214,40913,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ella ... en el colchón duro un minuto antes de gritar que era un desastre!'::text,'había estado sentada'::text,'ha estado sentada'::text,'se sienta'::text,'¡Ella había estado sentada en el colchón duro un minuto antes de gritar que era un desastre!'::text),
(368213,40913,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... sur le matelas dur pendant une minute avant de crier que c''était une catastrophe !'::text,'était restée assise'::text,'est restée assise'::text,'s''assoit'::text,'Elle était restée assise sur le matelas dur pendant une minute avant de crier que c''était une catastrophe !'::text),
(368216,40913,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, felaket olduğunu bağırmadan önce sert yatakta bir dakika ...!'::text,'oturuyordu'::text,'oturuyor'::text,'oturur'::text,'O, felaket olduğunu bağırmadan önce sert yatakta bir dakika oturuyordu!'::text),
(368217,40913,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő egy percig ... a kemény matracon, mielőtt felsikoltott, hogy ez katasztrófa!'::text,'ült'::text,'ül'::text,'ül'::text,'Ő egy percig ült a kemény matracon, mielőtt felsikoltott, hogy ez katasztrófa!'::text),
(385059,42785,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn du ein Auto regelmäßig wartest, ... es länger.'::text,'hält'::text,'hielt'::text,'würde halten'::text,'Wenn du ein Auto regelmäßig wartest, hält es länger.'::text),
(385063,42785,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо ти регулярно обслуговуєш авто, воно ... довше.'::text,'служить'::text,'служило'::text,'служило б'::text,'Якщо ти регулярно обслуговуєш авто, воно служить довше.'::text),
(385062,42785,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si tú haces el mantenimiento del coche con regularidad, ... más tiempo.'::text,'dura'::text,'duró'::text,'duraría'::text,'Si tú haces el mantenimiento del coche con regularidad, dura más tiempo.'::text),
(385061,42785,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si tu entretiens une voiture régulièrement, elle ... plus longtemps.'::text,'dure'::text,'a duré'::text,'durerait'::text,'Si tu entretiens une voiture régulièrement, elle dure plus longtemps.'::text),
(385064,42785,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sen bir arabanın bakımını düzenli yaparsan, araba daha uzun ...'::text,'dayanır'::text,'dayandı'::text,'dayanırdı'::text,'Sen bir arabanın bakımını düzenli yaparsan, araba daha uzun dayanır.'::text),
(385065,42785,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha te rendszeresen szervizelteted az autót, tovább ...'::text,'bírja'::text,'bírta'::text,'bírná'::text,'Ha te rendszeresen szervizelteted az autót, tovább bírja.'::text),
(365889,40655,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie wartet im Bett, während ... aus der braunen Flasche den Löffel füllt.'::text,'die Flüssigkeit'::text,'eine Flüssigkeit'::text,'Flüssigkeit'::text,'Sie wartet im Bett, während die Flüssigkeit aus der braunen Flasche den Löffel füllt.'::text),
(365893,40655,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона чекає в ліжку, поки ... з коричневої пляшки наповнює ложку.'::text,'рідина'::text,'рідина'::text,'рідина'::text,'Вона чекає в ліжку, поки рідина з коричневої пляшки наповнює ложку.'::text),
(365892,40655,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella espera en la cama mientras ... del frasco marrón llena la cuchara.'::text,'el líquido'::text,'un líquido'::text,'líquido'::text,'Ella espera en la cama mientras el líquido del frasco marrón llena la cuchara.'::text),
(365891,40655,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle attend au lit pendant que ... du flacon brun remplit la cuillère.'::text,'le liquide'::text,'un liquide'::text,'liquide'::text,'Elle attend au lit pendant que le liquide du flacon brun remplit la cuillère.'::text),
(365894,40655,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, kahverengi şişedeki ... kaşığı doldururken yatakta bekliyor.'::text,'sıvı'::text,'bir sıvı'::text,'sıvı'::text,'O, kahverengi şişedeki sıvı kaşığı doldururken yatakta bekliyor.'::text),
(365895,40655,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő az ágyban vár, amíg ... a barna üvegből megtölti a kanalat.'::text,'a folyadék'::text,'egy folyadék'::text,'folyadék'::text,'Ő az ágyban vár, amíg a folyadék a barna üvegből megtölti a kanalat.'::text),
(392412,43602,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Seine Hände sind eine klebrige Katastrophe! Und ...'::text,'seine Arme auch.'::text,'seine Arme auch.'::text,'seine Arme nicht.'::text,'Seine Hände sind eine klebrige Katastrophe! Und seine Arme auch.'::text),
(392416,43602,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Його долоні — липка катастрофа! І ...'::text,'руки теж.'::text,'руки теж.'::text,'руки теж ні.'::text,'Його долоні — липка катастрофа! І руки теж.'::text),
(392415,43602,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Sus manos son un desastre pegajoso! Y ...'::text,'sus brazos también.'::text,'sus brazos también.'::text,'sus brazos tampoco.'::text,'¡Sus manos son un desastre pegajoso! Y sus brazos también.'::text),
(392414,43602,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ses mains sont une catastrophe collante ! Et ...'::text,'ses bras aussi.'::text,'ses bras aussi.'::text,'ses bras non plus.'::text,'Ses mains sont une catastrophe collante ! Et ses bras aussi.'::text),
(392417,43602,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elleri yapış yapış bir felaket! Ve ...'::text,'kolları da.'::text,'kolları da.'::text,'kolları da değil.'::text,'Elleri yapış yapış bir felaket! Ve kolları da.'::text),
(392418,43602,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A keze egy ragacsos katasztrófa! És ...'::text,'a karja is.'::text,'a karja is.'::text,'a karja sem.'::text,'A keze egy ragacsos katasztrófa! És a karja is.'::text),
(392421,43603,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, ich hab gehört, er ... zehn Minuten in der Sonne gestanden, bevor seine Hände klebrig wurden.'::text,'hatte'::text,'hat'::text,'war'::text,'Bestie, ich hab gehört, er hatte zehn Minuten in der Sonne gestanden, bevor seine Hände klebrig wurden.'::text),
(392425,43603,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, я чула, що він ... на сонці десять хвилин, перш ніж його руки стали липкими.'::text,'стояв'::text,'стоїть'::text,'стояв'::text,'Подруго, я чула, що він стояв на сонці десять хвилин, перш ніж його руки стали липкими.'::text),
(392424,43603,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, oí que él ... de pie al sol diez minutos antes de que se le pusieran pegajosas las manos.'::text,'había estado'::text,'ha estado'::text,'estaba'::text,'Amiga, oí que él había estado de pie al sol diez minutos antes de que se le pusieran pegajosas las manos.'::text),
(392423,43603,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, j''ai entendu qu''il ... au soleil dix minutes avant que ses mains deviennent collantes.'::text,'était resté'::text,'est resté'::text,'était'::text,'Bestie, j''ai entendu qu''il était resté au soleil dix minutes avant que ses mains deviennent collantes.'::text),
(392426,43603,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, duydum ki o, elleri yapış yapış olmadan önce güneşte on dakika ...'::text,'durmuştu'::text,'duruyor'::text,'duruyordu'::text,'Kanka, duydum ki o, elleri yapış yapış olmadan önce güneşte on dakika durmuştu.'::text),
(392427,43603,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, úgy hallottam, hogy ő ... tíz percig a napon, mielőtt ragacsos lett a keze.'::text,'állt'::text,'áll'::text,'állt'::text,'Csajszi, úgy hallottam, hogy ő állt tíz percig a napon, mielőtt ragacsos lett a keze.'::text),
(379326,42148,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, er ... seit so zwei Stunden Karteikarten um und versucht, sich an jede Antwort zu erinnern.'::text,'dreht'::text,'dreht'::text,'dreht'::text,'Alter, er dreht seit so zwei Stunden Karteikarten um und versucht, sich an jede Antwort zu erinnern.'::text),
(379330,42148,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, він ... картки вже десь дві години, намагаючись згадати кожну відповідь.'::text,'гортає'::text,'гортає'::text,'гортає'::text,'Чувак, він гортає картки вже десь дві години, намагаючись згадати кожну відповідь.'::text),
(379329,42148,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, él ... tarjetas como dos horas, intentando recordar cada respuesta.'::text,'lleva pasando'::text,'está pasando'::text,'pasa'::text,'Tío, él lleva pasando tarjetas como dos horas, intentando recordar cada respuesta.'::text),
(379328,42148,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, il ... des flashcards depuis genre deux heures pour essayer de se rappeler chaque réponse.'::text,'retourne'::text,'retourne'::text,'retourne'::text,'Mec, il retourne des flashcards depuis genre deux heures pour essayer de se rappeler chaque réponse.'::text),
(379331,42148,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o yaklaşık iki saattir kartları ..., her cevabı hatırlamaya çalışıyor.'::text,'çeviriyor'::text,'çeviriyor'::text,'çevirir'::text,'Kanka, o yaklaşık iki saattir kartları çeviriyor, her cevabı hatırlamaya çalışıyor.'::text),
(379332,42148,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ő már vagy két órája ... a kártyákat, hogy minden választ felidézzen.'::text,'forgatja'::text,'forgatja'::text,'forgatja'::text,'Tesó, ő már vagy két órája forgatja a kártyákat, hogy minden választ felidézzen.'::text),
(379398,42156,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, angeblich ... er sich an jede Karte erinnert, bevor er die Faust in die Luft stieß.'::text,'hatte'::text,'erinnerte'::text,'hat'::text,'Hör zu, angeblich hatte er sich an jede Karte erinnert, bevor er die Faust in die Luft stieß.'::text),
(379402,42156,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, він ... кожну картку, перш ніж вдарив кулаком у повітря.'::text,'згадав'::text,'згадував'::text,'згадав'::text,'Слухай, кажуть, він згадав кожну картку, перш ніж вдарив кулаком у повітря.'::text),
(379401,42156,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Escucha, al parecer él ... cada tarjeta antes de dar un puñetazo al aire.'::text,'había recordado'::text,'estaba recordando'::text,'ha recordado'::text,'Escucha, al parecer él había recordado cada tarjeta antes de dar un puñetazo al aire.'::text),
(379400,42156,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, apparemment il ... chaque carte avant de donner un coup de poing en l''air.'::text,'s''était rappelé'::text,'se rappelait'::text,'s''est rappelé'::text,'Écoute, apparemment il s''était rappelé chaque carte avant de donner un coup de poing en l''air.'::text),
(379403,42156,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, anlaşılan o, havaya yumruk atmadan önce her kartı ...'::text,'hatırlamıştı'::text,'hatırlıyordu'::text,'hatırladı'::text,'Dinle, anlaşılan o, havaya yumruk atmadan önce her kartı hatırlamıştı.'::text),
(379404,42156,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, állítólag ő ... minden kártyát, mielőtt a levegőbe bokszolt.'::text,'felidézte'::text,'idézte fel éppen'::text,'felidézte'::text,'Figyelj, állítólag ő felidézte minden kártyát, mielőtt a levegőbe bokszolt.'::text),
(375420,41714,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Vorgang wurde beobachtet, während der Koch dünne Schweinefleischscheiben auf die Grillplatte ...'::text,'hobelte'::text,'hobelte'::text,'hat gehobelt'::text,'Der Vorgang wurde beobachtet, während der Koch dünne Schweinefleischscheiben auf die Grillplatte hobelte.'::text),
(375424,41714,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Процес спостерігали, коли кухар ... тонкі скибочки свинини на плиту.'::text,'зрізав'::text,'зрізав'::text,'зрізав'::text,'Процес спостерігали, коли кухар зрізав тонкі скибочки свинини на плиту.'::text),
(375423,41714,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El proceso se observó mientras el cocinero ... finas lonchas de cerdo sobre la plancha.'::text,'estaba cortando'::text,'cortó'::text,'ha cortado'::text,'El proceso se observó mientras el cocinero estaba cortando finas lonchas de cerdo sobre la plancha.'::text),
(375422,41714,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le processus a été observé pendant que le cuisinier ... de fines tranches de porc sur la plaque.'::text,'découpait'::text,'a découpé'::text,'a découpé'::text,'Le processus a été observé pendant que le cuisinier découpait de fines tranches de porc sur la plaque.'::text),
(375425,41714,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Süreç, aşçı ızgaraya ince domuz eti dilimleri ... gözlemlendi.'::text,'keserken'::text,'kestiğinde'::text,'kesmişken'::text,'Süreç, aşçı ızgaraya ince domuz eti dilimleri keserken gözlemlendi.'::text),
(375426,41714,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A folyamatot akkor figyelték meg, amikor a szakács vékony sertéshússzeleteket ... a sütőlapra.'::text,'vágott'::text,'vágott'::text,'vágott'::text,'A folyamatot akkor figyelték meg, amikor a szakács vékony sertéshússzeleteket vágott a sütőlapra.'::text),
(375438,41716,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hätte der Koch keine Salsa dazugegeben, ... die Schweinefleisch-Tacos nicht so gut ausgesehen.'::text,'hätten'::text,'werden'::text,'sahen'::text,'Hätte der Koch keine Salsa dazugegeben, hätten die Schweinefleisch-Tacos nicht so gut ausgesehen.'::text),
(375442,41716,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби кухар не додав сальсу, тако зі свининою ... так добре.'::text,'не виглядали б'::text,'не виглядатимуть'::text,'не виглядали'::text,'Якби кухар не додав сальсу, тако зі свининою не виглядали б так добре.'::text),
(375441,41716,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el cocinero no hubiera añadido salsa, los tacos de cerdo ... tan buenos.'::text,'no habrían parecido'::text,'no parecerán'::text,'no parecieron'::text,'Si el cocinero no hubiera añadido salsa, los tacos de cerdo no habrían parecido tan buenos.'::text),
(375440,41716,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le cuisinier n''avait pas ajouté de salsa, les tacos au porc ... aussi bons.'::text,'n''auraient pas eu l''air'::text,'n''auront pas l''air'::text,'n''avaient pas l''air'::text,'Si le cuisinier n''avait pas ajouté de salsa, les tacos au porc n''auraient pas eu l''air aussi bons.'::text),
(375443,41716,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aşçı salsa eklemeseydi, domuz etli takolar bu kadar iyi ...'::text,'görünmezdi'::text,'görünmeyecek'::text,'görünmedi'::text,'Aşçı salsa eklemeseydi, domuz etli takolar bu kadar iyi görünmezdi.'::text),
(375444,41716,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a szakács nem tett volna hozzá salsát, a sertéshúsos tacók ... ilyen jól.'::text,'nem néztek volna ki'::text,'nem fognak kinézni'::text,'nem néztek ki'::text,'Ha a szakács nem tett volna hozzá salsát, a sertéshúsos tacók nem néztek volna ki ilyen jól.'::text),
(377850,41984,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Diese Pyramide ... das Zentrum einer Stadt für Tausende Menschen, heißt es im Tourismusbericht.'::text,'war früher'::text,'würde sein'::text,'war gewohnt'::text,'Diese Pyramide war früher das Zentrum einer Stadt für Tausende Menschen, heißt es im Tourismusbericht.'::text),
(377854,41984,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ця піраміда ... центром міста для тисяч людей, йдеться у туристичному звіті.'::text,'колись була'::text,'бувала'::text,'звикла бути'::text,'Ця піраміда колись була центром міста для тисяч людей, йдеться у туристичному звіті.'::text),
(377853,41984,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Esta pirámide ... ser el centro de una ciudad para miles de personas, según el informe turístico.'::text,'solía'::text,'solía'::text,'estaba acostumbrada a'::text,'Esta pirámide solía ser el centro de una ciudad para miles de personas, según el informe turístico.'::text),
(377852,41984,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cette pyramide ... le centre d''une ville pour des milliers de personnes, selon le rapport touristique.'::text,'était autrefois'::text,'était'::text,'avait l''habitude d''être'::text,'Cette pyramide était autrefois le centre d''une ville pour des milliers de personnes, selon le rapport touristique.'::text),
(377855,41984,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Turizm raporuna göre bu piramit ... binlerce kişilik bir şehrin merkeziydi.'::text,'eskiden'::text,'eskiden'::text,'alışkındı'::text,'Turizm raporuna göre bu piramit eskiden binlerce kişilik bir şehrin merkeziydi.'::text),
(377856,41984,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ez a piramis ... egy több ezer fős város központja volt, áll a turisztikai jelentésben.'::text,'régen'::text,'régen'::text,'hozzá volt szokva'::text,'Ez a piramis régen egy több ezer fős város központja volt, áll a turisztikai jelentésben.'::text),
(334407,37157,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Damals ... Oma nie einen Kuchen mit so vielen Beeren ruiniert!'::text,'hätte'::text,'pflegte'::text,'war gewohnt'::text,'Damals hätte Oma nie einen Kuchen mit so vielen Beeren ruiniert!'::text),
(334411,37157,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Тоді бабуся ніколи ... торт такою кількістю ягід!'::text,'не зіпсувала б'::text,'не псувала'::text,'не звикла псувати'::text,'Тоді бабуся ніколи не зіпсувала б торт такою кількістю ягід!'::text),
(334410,37157,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡En aquella época, la abuela nunca ... un pastel con tantas bayas!'::text,'arruinaría'::text,'solía arruinar'::text,'estaba acostumbrada a arruinar'::text,'¡En aquella época, la abuela nunca arruinaría un pastel con tantas bayas!'::text),
(334409,37157,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'À l''époque, mamie ne ... jamais un gâteau avec autant de baies !'::text,'gâchait'::text,'gâchait'::text,'avait l''habitude de gâcher'::text,'À l''époque, mamie ne gâchait jamais un gâteau avec autant de baies !'::text),
(334412,37157,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O zamanlar büyükannem bu kadar çok meyveyle bir pastayı asla ...!'::text,'mahvetmezdi'::text,'mahvetmezdi'::text,'mahvetmeye alışkın değildi'::text,'O zamanlar büyükannem bu kadar çok meyveyle bir pastayı asla mahvetmezdi!'::text),
(334413,37157,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Akkoriban a nagyi soha nem ... el egy tortát ennyi bogyóval!'::text,'rontott volna'::text,'rontotta'::text,'szokta volna'::text,'Akkoriban a nagyi soha nem rontott volna el egy tortát ennyi bogyóval!'::text),
(334452,37162,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay also, angeblich ... sie die ganze Woche Beeren in alles, was sie backen.'::text,'tun'::text,'tun'::text,'tun'::text,'Okay also, angeblich tun sie die ganze Woche Beeren in alles, was sie backen.'::text),
(334456,37162,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Отже, кажуть, вони ... ягоди до всього, що печуть, увесь тиждень.'::text,'додають'::text,'додають'::text,'додають'::text,'Отже, кажуть, вони додають ягоди до всього, що печуть, увесь тиждень.'::text),
(334455,37162,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, pues al parecer ellas ... bayas a todo lo que hornean toda la semana.'::text,'llevan añadiendo'::text,'están añadiendo'::text,'añaden'::text,'Vale, pues al parecer ellas llevan añadiendo bayas a todo lo que hornean toda la semana.'::text),
(334454,37162,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon alors, apparemment elles ... des baies à tout ce qu''elles font cuire depuis toute la semaine.'::text,'ajoutent'::text,'ajoutent'::text,'ajoutent'::text,'Bon alors, apparemment elles ajoutent des baies à tout ce qu''elles font cuire depuis toute la semaine.'::text),
(334457,37162,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam yani, anlaşılan onlar bütün hafta pişirdikleri her şeye meyve ...'::text,'ekliyorlar'::text,'ekliyorlar'::text,'eklerler'::text,'Tamam yani, anlaşılan onlar bütün hafta pişirdikleri her şeye meyve ekliyorlar.'::text),
(334458,37162,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oké, szóval állítólag ők egész héten ... a bogyókat mindenhez, amit sütnek.'::text,'teszik'::text,'teszik'::text,'teszik'::text,'Oké, szóval állítólag ők egész héten teszik a bogyókat mindenhez, amit sütnek.'::text),
(386085,42899,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Boden ... matt, bevor sie anfing; jetzt glänzt er.'::text,'war früher'::text,'würde sein'::text,'war gewohnt'::text,'Der Boden war früher matt, bevor sie anfing; jetzt glänzt er.'::text),
(386089,42899,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Підлога ... тьмяною, поки вона не почала; тепер вона блискуча.'::text,'колись була'::text,'бувала'::text,'звикла бути'::text,'Підлога колись була тьмяною, поки вона не почала; тепер вона блискуча.'::text),
(386088,42899,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El suelo ... estar apagado antes de que ella empezara; ahora brilla.'::text,'solía'::text,'solía'::text,'estaba acostumbrado a'::text,'El suelo solía estar apagado antes de que ella empezara; ahora brilla.'::text),
(386087,42899,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le sol ... terne avant qu''elle commence ; maintenant, il brille.'::text,'était'::text,'serait'::text,'avait l''habitude d''être'::text,'Le sol était terne avant qu''elle commence ; maintenant, il brille.'::text),
(386090,42899,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O başlamadan önce zemin ... donuktu; şimdi parlıyor.'::text,'eskiden'::text,'eskiden'::text,'alışkındı'::text,'O başlamadan önce zemin eskiden donuktu; şimdi parlıyor.'::text),
(386091,42899,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A padló ... fénytelen volt, mielőtt ő elkezdte; most fényes.'::text,'régen'::text,'régen'::text,'hozzá volt szokva'::text,'A padló régen fénytelen volt, mielőtt ő elkezdte; most fényes.'::text),
(386103,42901,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... diesen Boden seit Stunden, und niemand merkt, wie glänzend er ist! Unglaublich!'::text,'wischt'::text,'wischt'::text,'wischt'::text,'Sie wischt diesen Boden seit Stunden, und niemand merkt, wie glänzend er ist! Unglaublich!'::text),
(386107,42901,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... цю підлогу вже кілька годин, і ніхто не помічає, яка вона блискуча! Неймовірно!'::text,'миє'::text,'миє'::text,'миє'::text,'Вона миє цю підлогу вже кілька годин, і ніхто не помічає, яка вона блискуча! Неймовірно!'::text),
(386106,42901,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ella ... este suelo durante horas y nadie nota lo brillante que está! ¡Increíble!'::text,'lleva fregando'::text,'está fregando'::text,'friega'::text,'¡Ella lleva fregando este suelo durante horas y nadie nota lo brillante que está! ¡Increíble!'::text),
(386105,42901,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... ce sol depuis des heures, et personne ne remarque à quel point il brille ! Incroyable !'::text,'lave'::text,'lave'::text,'lave'::text,'Elle lave ce sol depuis des heures, et personne ne remarque à quel point il brille ! Incroyable !'::text),
(386108,42901,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O saatlerdir bu zemini ... ve kimse ne kadar parlak olduğunu fark etmiyor! İnanılmaz!'::text,'siliyor'::text,'siliyor'::text,'siler'::text,'O saatlerdir bu zemini siliyor ve kimse ne kadar parlak olduğunu fark etmiyor! İnanılmaz!'::text),
(386109,42901,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő órák óta ... ezt a padlót, és senki sem veszi észre, milyen fényes! Hihetetlen!'::text,'felmossa'::text,'felmossa'::text,'felmossa'::text,'Ő órák óta felmossa ezt a padlót, és senki sem veszi észre, milyen fényes! Hihetetlen!'::text),
(371325,41259,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... des kalten Wetters draußen ist das Kinderzimmer voller warmem Licht und Lachen.'::text,'Trotz'::text,'Obwohl'::text,'Wegen'::text,'Trotz des kalten Wetters draußen ist das Kinderzimmer voller warmem Licht und Lachen.'::text),
(371329,41259,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... холодну погоду надворі, дитяча кімната сповнена теплого світла й сміху.'::text,'Попри'::text,'Хоча'::text,'Завдяки'::text,'Попри холодну погоду надворі, дитяча кімната сповнена теплого світла й сміху.'::text),
(371328,41259,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... el frío que hace fuera, la habitación del bebé está llena de luz cálida y risas.'::text,'A pesar de'::text,'Aunque'::text,'Debido a'::text,'A pesar de el frío que hace fuera, la habitación del bebé está llena de luz cálida y risas.'::text),
(371327,41259,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... le froid dehors, la chambre du bébé est pleine de lumière chaude et de rires.'::text,'Malgré'::text,'Bien que'::text,'En raison de'::text,'Malgré le froid dehors, la chambre du bébé est pleine de lumière chaude et de rires.'::text),
(371330,41259,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dışarıdaki soğuk havaya ..., bebek odası sıcak ışık ve kahkahalarla dolu.'::text,'rağmen'::text,'olsa da'::text,'nedeniyle'::text,'Dışarıdaki soğuk havaya rağmen, bebek odası sıcak ışık ve kahkahalarla dolu.'::text),
(371331,41259,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kinti hideg idő ... a babaszoba tele van meleg fénnyel és nevetéssel.'::text,'ellenére'::text,'bár'::text,'miatt'::text,'A kinti hideg idő ellenére a babaszoba tele van meleg fénnyel és nevetéssel.'::text),
(371730,41304,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... durch das zugewachsene Gras, als der Mäher plötzlich stehen blieb.'::text,'schob'::text,'schob'::text,'hat geschoben'::text,'Er schob durch das zugewachsene Gras, als der Mäher plötzlich stehen blieb.'::text),
(371734,41304,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... крізь зарослу траву, коли косарка раптом зупинилася.'::text,'пробирався'::text,'пробрався'::text,'пробрався'::text,'Він пробирався крізь зарослу траву, коли косарка раптом зупинилася.'::text),
(371733,41304,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... por la hierba crecida cuando el cortacésped se paró de repente.'::text,'estaba empujando'::text,'empujó'::text,'ha empujado'::text,'Él estaba empujando por la hierba crecida cuando el cortacésped se paró de repente.'::text),
(371732,41304,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... à travers l''herbe envahissante quand la tondeuse s''est soudain arrêtée.'::text,'poussait'::text,'a poussé'::text,'a poussé'::text,'Il poussait à travers l''herbe envahissante quand la tondeuse s''est soudain arrêtée.'::text),
(371735,41304,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, çim biçme makinesi aniden durduğunda uzamış çimlerin arasından ...'::text,'itiyordu'::text,'itti'::text,'itti'::text,'O, çim biçme makinesi aniden durduğunda uzamış çimlerin arasından itiyordu.'::text),
(371736,41304,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő éppen ... a benőtt füvön át, amikor a fűnyíró hirtelen leállt.'::text,'tolta'::text,'tolta'::text,'tolta'::text,'Ő éppen tolta a benőtt füvön át, amikor a fűnyíró hirtelen leállt.'::text),
(371820,41314,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... den verwilderten Garten eine Stunde lang gemäht, bevor wir diesen sauberen Streifen sahen. Respekt.'::text,'hattest'::text,'hast'::text,'mähst'::text,'Du hattest den verwilderten Garten eine Stunde lang gemäht, bevor wir diesen sauberen Streifen sahen. Respekt.'::text),
(371824,41314,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ... зарослий сад годину, перш ніж ми побачили ту чисту смугу. Респект.'::text,'косив'::text,'косиш'::text,'косиш'::text,'Ти косив зарослий сад годину, перш ніж ми побачили ту чисту смугу. Респект.'::text),
(371823,41314,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tú ... el jardín descuidado durante una hora antes de que viéramos esa franja limpia. Respeto.'::text,'habías estado cortando'::text,'has estado cortando'::text,'cortas'::text,'Tú habías estado cortando el jardín descuidado durante una hora antes de que viéramos esa franja limpia. Respeto.'::text),
(371822,41314,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ... le jardin envahi pendant une heure avant qu''on voie cette bande nette. Respect.'::text,'avais tondu'::text,'as tondu'::text,'tonds'::text,'Tu avais tondu le jardin envahi pendant une heure avant qu''on voie cette bande nette. Respect.'::text),
(371825,41314,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sen, biz o temiz şeridi görene kadar bakımsız bahçeyi bir saat ..., saygı.'::text,'biçiyordun'::text,'biçiyorsun'::text,'biçersin'::text,'Sen, biz o temiz şeridi görene kadar bakımsız bahçeyi bir saat biçiyordun, saygı.'::text),
(371826,41314,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Te egy órán át ... a benőtt kertet, mielőtt megláttuk azt a tiszta csíkot. Respekt.'::text,'nyírtad'::text,'nyírod'::text,'nyírod'::text,'Te egy órán át nyírtad a benőtt kertet, mielőtt megláttuk azt a tiszta csíkot. Respekt.'::text),
(387498,43056,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, der dünne Typ gibt echt alles, ...?'::text,'oder'::text,'nicht wahr'::text,'oder'::text,'Bro, der dünne Typ gibt echt alles, oder?'::text),
(387502,43056,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, той худий чувак викладається на всі сто, ...?'::text,'так'::text,'правда'::text,'так'::text,'Бро, той худий чувак викладається на всі сто, так?'::text),
(387501,43056,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ese flaco lo está dando todo, ¿...?'::text,'verdad'::text,'no'::text,'verdad'::text,'Bro, ese flaco lo está dando todo, ¿verdad?'::text),
(387500,43056,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, ce mec tout maigre donne tout, ... ?'::text,'hein'::text,'non'::text,'hein'::text,'Frérot, ce mec tout maigre donne tout, hein ?'::text),
(387503,43056,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o sıska adam her şeyini veriyor, ...?'::text,'değil mi'::text,'değil mi'::text,'değil mi'::text,'Kanka, o sıska adam her şeyini veriyor, değil mi?'::text),
(387504,43056,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, az a vékony srác mindent belead, ...?'::text,'ugye'::text,'nem'::text,'ugye'::text,'Tesó, az a vékony srác mindent belead, ugye?'::text),
(387561,43063,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der dünne Mann ... monatelang trainiert, bevor er die Pose im Gym ausprobierte.'::text,'hatte'::text,'war'::text,'hat'::text,'Der dünne Mann hatte monatelang trainiert, bevor er die Pose im Gym ausprobierte.'::text),
(387565,43063,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Худий чоловік ... місяцями, перш ніж спробував цю позу в спортзалі.'::text,'тренувався'::text,'тренувався'::text,'тренується'::text,'Худий чоловік тренувався місяцями, перш ніж спробував цю позу в спортзалі.'::text),
(387564,43063,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre flaco ... durante meses antes de probar la pose en el gimnasio.'::text,'había estado entrenando'::text,'estaba entrenando'::text,'ha estado entrenando'::text,'El hombre flaco había estado entrenando durante meses antes de probar la pose en el gimnasio.'::text),
(387563,43063,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme maigre ... depuis des mois avant d''essayer la pose à la salle.'::text,'s''entraînait'::text,'s''entraînait'::text,'s''entraîne'::text,'L''homme maigre s''entraînait depuis des mois avant d''essayer la pose à la salle.'::text),
(387566,43063,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sıska adam, spor salonunda o pozu denemeden önce aylarca ...'::text,'antrenman yapmıştı'::text,'antrenman yapıyordu'::text,'antrenman yapıyor'::text,'Sıska adam, spor salonunda o pozu denemeden önce aylarca antrenman yapmıştı.'::text),
(387567,43063,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A sovány férfi hónapokig ..., mielőtt kipróbálta a pózt az edzőteremben.'::text,'edzett'::text,'edzett'::text,'edz'::text,'A sovány férfi hónapokig edzett, mielőtt kipróbálta a pózt az edzőteremben.'::text),
(332535,36949,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während er durch die Galerie ..., fiel ihm vor Ehrfurcht die Kinnlade herunter.'::text,'ging'::text,'ging'::text,'ist gegangen'::text,'Während er durch die Galerie ging, fiel ihm vor Ehrfurcht die Kinnlade herunter.'::text),
(332539,36949,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки він ... галереєю, його щелепа відвисла від захвату.'::text,'ішов'::text,'пройшов'::text,'пройшов'::text,'Поки він ішов галереєю, його щелепа відвисла від захвату.'::text),
(332538,36949,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mientras él ... por la galería, se le cayó la mandíbula de asombro.'::text,'caminaba'::text,'caminó'::text,'ha caminado'::text,'Mientras él caminaba por la galería, se le cayó la mandíbula de asombro.'::text),
(332537,36949,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant qu''il ... dans la galerie, sa mâchoire s''est décrochée d''émerveillement.'::text,'marchait'::text,'a marché'::text,'a marché'::text,'Pendant qu''il marchait dans la galerie, sa mâchoire s''est décrochée d''émerveillement.'::text),
(332540,36949,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O galeride ..., hayranlıktan ağzı açık kaldı.'::text,'yürürken'::text,'yürüdüğünde'::text,'yürümüşken'::text,'O galeride yürürken, hayranlıktan ağzı açık kaldı.'::text),
(332541,36949,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Miközben ő ... a galérián, a csodálattól leesett az álla.'::text,'sétált'::text,'végigsétált'::text,'végigsétált'::text,'Miközben ő sétált a galérián, a csodálattól leesett az álla.'::text),
(332580,36954,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Museum lässt das Skelett, das Besucher in Ehrfurcht versetzt, typischerweise von Fachleuten ...'::text,'reinigen'::text,'reinigen'::text,'reinigen'::text,'Das Museum lässt das Skelett, das Besucher in Ehrfurcht versetzt, typischerweise von Fachleuten reinigen.'::text),
(332584,36954,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Музей зазвичай доручає фахівцям ... скелет, що викликає у відвідувачів благоговіння.'::text,'чистити'::text,'чистити'::text,'чищення'::text,'Музей зазвичай доручає фахівцям чистити скелет, що викликає у відвідувачів благоговіння.'::text),
(332583,36954,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El museo normalmente hace que los especialistas ... el esqueleto que llena de asombro a los visitantes.'::text,'limpien'::text,'limpien'::text,'limpiando'::text,'El museo normalmente hace que los especialistas limpien el esqueleto que llena de asombro a los visitantes.'::text),
(332582,36954,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le musée fait généralement ... par des spécialistes le squelette qui remplit les visiteurs d''émerveillement.'::text,'nettoyer'::text,'nettoyer'::text,'nettoyant'::text,'Le musée fait généralement nettoyer par des spécialistes le squelette qui remplit les visiteurs d''émerveillement.'::text),
(332585,36954,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Müze, ziyaretçileri hayranlıkla dolduran iskeleti genellikle uzmanlara ...'::text,'temizletir'::text,'temizletir'::text,'temizletir'::text,'Müze, ziyaretçileri hayranlıkla dolduran iskeleti genellikle uzmanlara temizletir.'::text),
(332586,36954,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A múzeum a látogatókat ámulatba ejtő csontvázat általában szakemberekkel ...'::text,'tisztíttatja'::text,'tisztíttatja'::text,'tisztíttatja'::text,'A múzeum a látogatókat ámulatba ejtő csontvázat általában szakemberekkel tisztíttatja.'::text),
(392313,43591,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich gesagt, du ... schon drei Flaggen auf die Karte geklebt. Ikonischer Reisegeschmack.'::text,'hast'::text,'hast'::text,'klebtest'::text,'Ehrlich gesagt, du hast schon drei Flaggen auf die Karte geklebt. Ikonischer Reisegeschmack.'::text),
(392317,43591,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не брехатиму, ти вже ... три прапорці на ту мапу. Культовий смак до подорожей.'::text,'приклеїв'::text,'приклеюєш'::text,'приклеїв'::text,'Не брехатиму, ти вже приклеїв три прапорці на ту мапу. Культовий смак до подорожей.'::text),
(392316,43591,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No voy a mentir, tú ya ... tres banderas en ese mapa. Gusto viajero icónico.'::text,'has pegado'::text,'has estado pegando'::text,'pegaste'::text,'No voy a mentir, tú ya has pegado tres banderas en ese mapa. Gusto viajero icónico.'::text),
(392315,43591,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je vais pas mentir, tu ... déjà trois drapeaux sur cette carte. Goût du voyage iconique.'::text,'as collé'::text,'es en train de coller'::text,'as collé'::text,'Je vais pas mentir, tu as collé déjà trois drapeaux sur cette carte. Goût du voyage iconique.'::text),
(392318,43591,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, sen o haritaya şimdiden üç bayrak ...; ikonik seyahat zevki.'::text,'yapıştırdın'::text,'yapıştırıyorsun'::text,'yapıştırdın'::text,'Yalan yok, sen o haritaya şimdiden üç bayrak yapıştırdın; ikonik seyahat zevki.'::text),
(392319,43591,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem hazudok, te már ... három zászlót arra a térképre. Ikonikus utazási ízlés.'::text,'feltűztél'::text,'tűzögetsz'::text,'feltűztél'::text,'Nem hazudok, te már feltűztél három zászlót arra a térképre. Ikonikus utazási ízlés.'::text),
(392376,43598,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Girl, angeblich ... sie bis nächsten Sommer Flaggen auf jeden Kontinent geklebt haben.'::text,'werden'::text,'werden'::text,'kleben'::text,'Girl, angeblich werden sie bis nächsten Sommer Flaggen auf jeden Kontinent geklebt haben.'::text),
(392380,43598,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, до наступного літа вони ... прапорці на кожен континент.'::text,'приклеять'::text,'приклеюватимуть'::text,'приклеюють'::text,'Подруго, кажуть, до наступного літа вони приклеять прапорці на кожен континент.'::text),
(392379,43598,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer para el próximo verano ellos ... banderas en todos los continentes.'::text,'habrán pegado'::text,'pegarán'::text,'pegan'::text,'Tía, al parecer para el próximo verano ellos habrán pegado banderas en todos los continentes.'::text),
(392378,43598,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment d''ici l''été prochain ils ... des drapeaux sur chaque continent.'::text,'auront collé'::text,'colleront'::text,'collent'::text,'Meuf, apparemment d''ici l''été prochain ils auront collé des drapeaux sur chaque continent.'::text),
(392381,43598,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, anlaşılan onlar gelecek yaza kadar her kıtaya bayrak ...'::text,'yapıştırmış olacaklar'::text,'yapıştıracaklar'::text,'yapıştırıyorlar'::text,'Kızım, anlaşılan onlar gelecek yaza kadar her kıtaya bayrak yapıştırmış olacaklar.'::text),
(392382,43598,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag ők jövő nyárra minden kontinensre ... zászlót.'::text,'feltűznek'::text,'fel fognak tűzni'::text,'tűznek'::text,'Csajszi, állítólag ők jövő nyárra minden kontinensre feltűznek zászlót.'::text),
(370605,41179,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Frau, ... Hände ihren Mund bedecken, kämpft gegen ihre Übelkeit.'::text,'deren'::text,'die'::text,'welche'::text,'Die Frau, deren Hände ihren Mund bedecken, kämpft gegen ihre Übelkeit.'::text),
(370609,41179,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жінка, ... руки закривають рот, бореться з нудотою.'::text,'чиї'::text,'яка'::text,'котра'::text,'Жінка, чиї руки закривають рот, бореться з нудотою.'::text),
(370608,41179,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La mujer ... manos le tapan la boca está luchando contra las náuseas.'::text,'cuyas'::text,'que'::text,'la cual'::text,'La mujer cuyas manos le tapan la boca está luchando contra las náuseas.'::text),
(370607,41179,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La femme ... les mains couvrent la bouche lutte contre sa nausée.'::text,'dont'::text,'qui'::text,'laquelle'::text,'La femme dont les mains couvrent la bouche lutte contre sa nausée.'::text),
(370610,41179,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... Elleri ağzını kapatan kadın bulantısıyla savaşıyor.'::text,''::text,NULL::text,NULL::text,'Elleri ağzını kapatan kadın bulantısıyla savaşıyor.'::text),
(370611,41179,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nő, ... keze eltakarja a száját, a hányingerrel küzd.'::text,'akinek a'::text,'aki'::text,'amely'::text,'A nő, akinek a keze eltakarja a száját, a hányingerrel küzd.'::text),
(370659,41185,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Perfekter Urlaub: Sie ... eine Stunde an Deck gestanden, bevor die Übelkeit endlich gewann.'::text,'hatte'::text,'hat'::text,'steht'::text,'Perfekter Urlaub: Sie hatte eine Stunde an Deck gestanden, bevor die Übelkeit endlich gewann.'::text),
(370663,41185,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ідеальна відпустка: вона ... на палубі годину, перш ніж нудота нарешті перемогла.'::text,'стояла'::text,'стоїть'::text,'стоїть'::text,'Ідеальна відпустка: вона стояла на палубі годину, перш ніж нудота нарешті перемогла.'::text),
(370662,41185,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vacaciones perfectas: ella ... en cubierta una hora antes de que las náuseas por fin ganaran.'::text,'había estado'::text,'ha estado'::text,'está'::text,'Vacaciones perfectas: ella había estado en cubierta una hora antes de que las náuseas por fin ganaran.'::text),
(370661,41185,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vacances parfaites : elle ... sur le pont depuis une heure avant que la nausée gagne enfin.'::text,'était restée'::text,'est restée'::text,'reste'::text,'Vacances parfaites : elle était restée sur le pont depuis une heure avant que la nausée gagne enfin.'::text),
(370664,41185,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kusursuz tatil: o, bulantı sonunda galip gelmeden önce bir saat güvertede ...'::text,'durmuştu'::text,'duruyor'::text,'duruyor'::text,'Kusursuz tatil: o, bulantı sonunda galip gelmeden önce bir saat güvertede durmuştu.'::text),
(370665,41185,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tökéletes nyaralás: ő egy órán át ... a fedélzeten, mielőtt a hányinger végül győzött.'::text,'állt'::text,'áll'::text,'áll'::text,'Tökéletes nyaralás: ő egy órán át állt a fedélzeten, mielőtt a hányinger végül győzött.'::text),
(329943,36661,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, angeblich ... sie heute schon in fünf falsche Gassen abgebogen.'::text,'ist'::text,'ist'::text,'bog'::text,'Bestie, angeblich ist sie heute schon in fünf falsche Gassen abgebogen.'::text),
(329947,36661,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, вона сьогодні вже ... у п''ять неправильних провулків.'::text,'звернула'::text,'звертала'::text,'звернула'::text,'Подруго, кажуть, вона сьогодні вже звернула у п''ять неправильних провулків.'::text),
(329946,36661,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, al parecer ella ya ... cinco callejones equivocados hoy.'::text,'ha tomado'::text,'ha estado tomando'::text,'tomó'::text,'Amiga, al parecer ella ya ha tomado cinco callejones equivocados hoy.'::text),
(329945,36661,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, apparemment elle ... déjà cinq mauvaises ruelles aujourd''hui.'::text,'a pris'::text,'n''arrête pas de prendre'::text,'a pris'::text,'Bestie, apparemment elle a pris déjà cinq mauvaises ruelles aujourd''hui.'::text),
(329948,36661,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, anlaşılan o bugün şimdiden beş yanlış sokağa ...'::text,'saptı'::text,'sapıyor'::text,'saptı'::text,'Kanka, anlaşılan o bugün şimdiden beş yanlış sokağa saptı.'::text),
(329949,36661,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag ő ma már öt rossz sikátorba ...'::text,'fordult be'::text,'fordult be'::text,'fordult be'::text,'Csajszi, állítólag ő ma már öt rossz sikátorba fordult be.'::text),
(395337,43927,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Nachbarn ... sich schon eine Stunde über den Zaun unterhalten, als die Katze hochsprang.'::text,'hatten'::text,'waren'::text,'haben'::text,'Die Nachbarn hatten sich schon eine Stunde über den Zaun unterhalten, als die Katze hochsprang.'::text),
(395341,43927,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сусіди ... розмову через паркан уже годину, коли вискочив кіт.'::text,'вели'::text,'вели'::text,'ведуть'::text,'Сусіди вели розмову через паркан уже годину, коли вискочив кіт.'::text),
(395340,43927,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los vecinos ... una charla por encima de la valla durante una hora cuando el gato saltó.'::text,'habían estado teniendo'::text,'estaban teniendo'::text,'han estado teniendo'::text,'Los vecinos habían estado teniendo una charla por encima de la valla durante una hora cuando el gato saltó.'::text),
(395339,43927,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les voisins ... depuis une heure par-dessus la clôture quand le chat a sauté.'::text,'discutaient'::text,'discutaient'::text,'discutent'::text,'Les voisins discutaient depuis une heure par-dessus la clôture quand le chat a sauté.'::text),
(395342,43927,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kedi yukarı sıçradığında komşular bir saattir çitin üzerinden ...'::text,'sohbet ediyorlardı'::text,'sohbet ediyorlardı'::text,'sohbet ediyorlar'::text,'Kedi yukarı sıçradığında komşular bir saattir çitin üzerinden sohbet ediyorlardı.'::text),
(395343,43927,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szomszédok már egy órája ... a kerítésen át, amikor a macska felugrott.'::text,'beszélgettek'::text,'beszélgettek'::text,'beszélgetnek'::text,'A szomszédok már egy órája beszélgettek a kerítésen át, amikor a macska felugrott.'::text),
(348069,38675,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Enten ... den ganzen Vormittag auf dem Graben.'::text,'schwimmen'::text,'schwimmen'::text,'schwimmen'::text,'Die Enten schwimmen den ganzen Vormittag auf dem Graben.'::text),
(348073,38675,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Качки ... в канаві весь ранок.'::text,'плавають'::text,'плавають'::text,'плавають'::text,'Качки плавають в канаві весь ранок.'::text),
(348072,38675,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los patos ... en la acequia toda la mañana.'::text,'llevan nadando'::text,'están nadando'::text,'nadan'::text,'Los patos llevan nadando en la acequia toda la mañana.'::text),
(348071,38675,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les canards ... sur le fossé toute la matinée.'::text,'nagent'::text,'nagent'::text,'nagent'::text,'Les canards nagent sur le fossé toute la matinée.'::text),
(348074,38675,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ördekler bütün sabah hendekte ...'::text,'yüzüyor'::text,'yüzüyor'::text,'yüzer'::text,'Ördekler bütün sabah hendekte yüzüyor.'::text),
(348075,38675,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kacsák egész délelőtt ... az árokban.'::text,'úsznak'::text,'úsznak'::text,'úsznak'::text,'A kacsák egész délelőtt úsznak az árokban.'::text),
(402978,44776,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, das Mädchen, ... zur Windmühle läuft, lebt ihr bestes Leben, ohne Witz.'::text,'das'::text,'welches'::text,'dessen'::text,'Bro, das Mädchen, das zur Windmühle läuft, lebt ihr bestes Leben, ohne Witz.'::text),
(402982,44776,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, дівчина, ... йде до вітряка, живе найкращим життям, без жартів.'::text,'яка'::text,'котра'::text,'чия'::text,'Бро, дівчина, яка йде до вітряка, живе найкращим життям, без жартів.'::text),
(402981,44776,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, la chica ... camina hacia el molino está viviendo su mejor vida, sin mentir.'::text,'que'::text,'la cual'::text,'cuya'::text,'Bro, la chica que camina hacia el molino está viviendo su mejor vida, sin mentir.'::text),
(402980,44776,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, la fille ... marche vers le moulin vit sa meilleure vie, sans mentir.'::text,'qui'::text,'laquelle'::text,'dont'::text,'Frérot, la fille qui marche vers le moulin vit sa meilleure vie, sans mentir.'::text),
(402983,44776,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, yel değirmenine doğru ... kız hayatının en güzel anını yaşıyor, yalan yok.'::text,'yürüyen'::text,'yürüyen'::text,'yürüyen'::text,'Kanka, yel değirmenine doğru yürüyen kız hayatının en güzel anını yaşıyor, yalan yok.'::text),
(402984,44776,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a csaj, ... a szélmalom felé sétál, éli a legjobb életét, komolyan.'::text,'aki'::text,'amely'::text,'akinek'::text,'Tesó, a csaj, aki a szélmalom felé sétál, éli a legjobb életét, komolyan.'::text),
(403014,44780,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... hinter ihr ist eine der berühmtesten Sehenswürdigkeiten in den Niederlanden.'::text,'Die Windmühle'::text,'Eine Windmühle'::text,'Windmühle'::text,'Die Windmühle hinter ihr ist eine der berühmtesten Sehenswürdigkeiten in den Niederlanden.'::text),
(403018,44780,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... позаду неї — одна з найвідоміших пам''яток Нідерландів.'::text,'Вітряк'::text,'Вітряк'::text,'Вітряк'::text,'Вітряк позаду неї — одна з найвідоміших пам''яток Нідерландів.'::text),
(403017,44780,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... detrás de ella es uno de los lugares más famosos de los Países Bajos.'::text,'El molino'::text,'Un molino'::text,'Molino'::text,'El molino detrás de ella es uno de los lugares más famosos de los Países Bajos.'::text),
(403016,44780,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... derrière elle est l''un des sites les plus célèbres des Pays-Bas.'::text,'Le moulin'::text,'Un moulin'::text,'Moulin'::text,'Le moulin derrière elle est l''un des sites les plus célèbres des Pays-Bas.'::text),
(403019,44780,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onun arkasındaki ..., Hollanda''nın en ünlü yerlerinden biri.'::text,'yel değirmeni'::text,'bir yel değirmeni'::text,'yel değirmeni'::text,'Onun arkasındaki yel değirmeni, Hollanda''nın en ünlü yerlerinden biri.'::text),
(403020,44780,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'..., amely mögötte áll, Hollandia egyik leghíresebb látnivalója.'::text,'A szélmalom'::text,'Egy szélmalom'::text,'Szélmalom'::text,'A szélmalom, amely mögötte áll, Hollandia egyik leghíresebb látnivalója.'::text),
(344010,38224,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie das Baby noch ein bisschen länger wiegen, ... es ein.'::text,'schläft'::text,'würde schlafen'::text,'schlief'::text,'Wenn sie das Baby noch ein bisschen länger wiegen, schläft es ein.'::text),
(344014,38224,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо вони ще трохи поколишуть малечу, вона ...'::text,'засне'::text,'заснула б'::text,'заснула'::text,'Якщо вони ще трохи поколишуть малечу, вона засне.'::text),
(344013,38224,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si ellos mecen al bebé un poco más, ...'::text,'se dormirá'::text,'se dormiría'::text,'se durmió'::text,'Si ellos mecen al bebé un poco más, se dormirá.'::text),
(344012,38224,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''ils bercent le bébé encore un peu, elle ...'::text,'s''endormira'::text,'s''endormirait'::text,'s''est endormie'::text,'S''ils bercent le bébé encore un peu, elle s''endormira.'::text),
(344015,38224,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onlar bebeği biraz daha kucaklarında sallarlarsa, ...'::text,'uyuyacak'::text,'uyurdu'::text,'uyudu'::text,'Onlar bebeği biraz daha kucaklarında sallarlarsa, uyuyacak.'::text),
(344016,38224,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha ők még egy kicsit ringatják a babát, ...'::text,'elalszik'::text,'elaludna'::text,'elaludt'::text,'Ha ők még egy kicsit ringatják a babát, elalszik.'::text),
(344037,38227,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... das Baby eine Stunde lang gewiegt, bevor sie es in die Babywiege legten.'::text,'hatten'::text,'haben'::text,'wiegen'::text,'Sie hatten das Baby eine Stunde lang gewiegt, bevor sie es in die Babywiege legten.'::text),
(344041,38227,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони ... малечу годину, перш ніж поклали її в колиску.'::text,'колисали'::text,'колишуть'::text,'колишуть'::text,'Вони колисали малечу годину, перш ніж поклали її в колиску.'::text),
(344040,38227,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ellos ... al bebé una hora antes de ponerla en el moisés.'::text,'habían estado meciendo'::text,'han estado meciendo'::text,'están meciendo'::text,'Ellos habían estado meciendo al bebé una hora antes de ponerla en el moisés.'::text),
(344039,38227,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils ... le bébé pendant une heure avant de la mettre dans le berceau.'::text,'avaient bercé'::text,'ont bercé'::text,'bercent'::text,'Ils avaient bercé le bébé pendant une heure avant de la mettre dans le berceau.'::text),
(344042,38227,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onlar bebeği beşiğe koymadan önce bir saat ...'::text,'sallamışlardı'::text,'sallıyorlar'::text,'sallıyorlar'::text,'Onlar bebeği beşiğe koymadan önce bir saat sallamışlardı.'::text),
(344043,38227,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ők egy órán át ... a babát, mielőtt a mózeskosárba tették.'::text,'ringatták'::text,'ringatják'::text,'ringatják'::text,'Ők egy órán át ringatták a babát, mielőtt a mózeskosárba tették.'::text),
(371298,41256,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als das Kind mit dem Ausschlag ankam, wusste die Frau, dass sie es tagelang pflegen ...'::text,'würde'::text,'wird'::text,'pflegt'::text,'Als das Kind mit dem Ausschlag ankam, wusste die Frau, dass sie es tagelang pflegen würde.'::text),
(371302,41256,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли дитина прийшла з висипом, жінка знала, що ... її кілька днів.'::text,'доглядатиме'::text,'доглядатиме'::text,'доглядає'::text,'Коли дитина прийшла з висипом, жінка знала, що доглядатиме її кілька днів.'::text),
(371301,41256,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando el niño llegó con el sarpullido, la mujer sabía que ... al niño durante días.'::text,'cuidaría'::text,'cuidará'::text,'cuida'::text,'Cuando el niño llegó con el sarpullido, la mujer sabía que cuidaría al niño durante días.'::text),
(371300,41256,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand l''enfant est arrivé avec l''éruption, la femme savait qu''elle ... l''enfant pendant des jours.'::text,'soignerait'::text,'soignera'::text,'soigne'::text,'Quand l''enfant est arrivé avec l''éruption, la femme savait qu''elle soignerait l''enfant pendant des jours.'::text),
(371303,41256,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çocuk döküntüyle geldiğinde kadın, günlerce çocuğa ... biliyordu.'::text,'bakacağını'::text,'bakacağını'::text,'baktığını'::text,'Çocuk döküntüyle geldiğinde kadın, günlerce çocuğa bakacağını biliyordu.'::text),
(371304,41256,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amikor a gyerek kiütéssel érkezett, a nő tudta, hogy napokig ... a gyereket.'::text,'ápolni fogja'::text,'ápolni fogja'::text,'ápolja'::text,'Amikor a gyerek kiütéssel érkezett, a nő tudta, hogy napokig ápolni fogja a gyereket.'::text),
(358770,39864,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein paar Körner ... schon auf dem Boden der Schüssel gelandet.'::text,'sind'::text,'landen'::text,'landen gerade'::text,'Ein paar Körner sind schon auf dem Boden der Schüssel gelandet.'::text),
(358774,39864,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кілька зернят уже ... на дно миски.'::text,'упали'::text,'падають'::text,'падають'::text,'Кілька зернят уже упали на дно миски.'::text),
(358773,39864,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Unos cuantos granos ya ... en el fondo del bol.'::text,'han caído'::text,'caen'::text,'están cayendo'::text,'Unos cuantos granos ya han caído en el fondo del bol.'::text),
(358772,39864,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quelques grains ... déjà au fond du bol.'::text,'ont atterri'::text,'atterrissent'::text,'sont en train d''atterrir'::text,'Quelques grains ont atterri déjà au fond du bol.'::text),
(358775,39864,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Birkaç tanecik şimdiden kasenin dibine ...'::text,'düştü'::text,'düşer'::text,'düşüyor'::text,'Birkaç tanecik şimdiden kasenin dibine düştü.'::text),
(358776,39864,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Néhány szem már ... a tál aljára.'::text,'leesett'::text,'esik'::text,'esik'::text,'Néhány szem már leesett a tál aljára.'::text),
(354117,39347,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hätte der Mann nicht gerufen, ... die Flamingos nicht so früh weggeflogen.'::text,'wären'::text,'werden'::text,'flogen'::text,'Hätte der Mann nicht gerufen, wären die Flamingos nicht so früh weggeflogen.'::text),
(354121,39347,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби чоловік не закричав, фламінго ... так рано.'::text,'не полетіли б'::text,'не полетять'::text,'не полетіли'::text,'Якби чоловік не закричав, фламінго не полетіли б так рано.'::text),
(354120,39347,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el hombre no hubiera gritado, los flamencos ... tan pronto.'::text,'no habrían salido volando'::text,'no saldrán volando'::text,'no salieron volando'::text,'Si el hombre no hubiera gritado, los flamencos no habrían salido volando tan pronto.'::text),
(354119,39347,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si l''homme n''avait pas crié, les flamants ... si tôt.'::text,'ne se seraient pas envolés'::text,'ne s''envoleront pas'::text,'ne se sont pas envolés'::text,'Si l''homme n''avait pas crié, les flamants ne se seraient pas envolés si tôt.'::text),
(354122,39347,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adam bağırmasaydı, flamingolar bu kadar erken ...'::text,'uçmazdı'::text,'uçmayacak'::text,'uçmadı'::text,'Adam bağırmasaydı, flamingolar bu kadar erken uçmazdı.'::text),
(354123,39347,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a férfi nem kiabált volna, a flamingók ... el ilyen korán.'::text,'nem repültek volna'::text,'nem fognak'::text,'nem repültek'::text,'Ha a férfi nem kiabált volna, a flamingók nem repültek volna el ilyen korán.'::text),
(335676,37298,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er wollte die Buchhandlung nicht verlassen, und ...'::text,'sein Freund auch nicht.'::text,'sein Freund auch.'::text,'sein Freund auch nicht.'::text,'Er wollte die Buchhandlung nicht verlassen, und sein Freund auch nicht.'::text),
(335680,37298,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він не хотів іти з книгарні, і ...'::text,'його друг теж ні.'::text,'його друг теж.'::text,'його друг теж ні.'::text,'Він не хотів іти з книгарні, і його друг теж ні.'::text),
(335679,37298,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él no quería irse de la librería, y ...'::text,'su amigo tampoco.'::text,'su amigo también.'::text,'su amigo tampoco.'::text,'Él no quería irse de la librería, y su amigo tampoco.'::text),
(335678,37298,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ne voulait pas quitter la librairie, et ...'::text,'son ami non plus.'::text,'son ami aussi.'::text,'son ami non plus.'::text,'Il ne voulait pas quitter la librairie, et son ami non plus.'::text),
(335681,37298,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, kitapçıdan ayrılmak istemedi ve ...'::text,'arkadaşı da istemedi.'::text,'arkadaşı da istedi.'::text,'arkadaşı da istemedi.'::text,'O, kitapçıdan ayrılmak istemedi ve arkadaşı da istemedi.'::text),
(335682,37298,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő nem akart kijönni a könyvesboltból, és ...'::text,'a barátja sem.'::text,'a barátja is.'::text,'a barátja sem.'::text,'Ő nem akart kijönni a könyvesboltból, és a barátja sem.'::text),
(394347,43817,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Starker Move: Du ... dem Chirurgen das Skalpell und hast uns dann einen Daumen hoch gegeben.'::text,'reichtest'::text,'reichtest gerade'::text,'hast gereicht'::text,'Starker Move: Du reichtest dem Chirurgen das Skalpell und hast uns dann einen Daumen hoch gegeben.'::text),
(394351,43817,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Круто: ти ... хірургові скальпель, а потім показала нам великий палець.'::text,'передала'::text,'передавала'::text,'передала'::text,'Круто: ти передала хірургові скальпель, а потім показала нам великий палець.'::text),
(394350,43817,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Buen movimiento: tú le ... el bisturí al cirujano y luego nos levantaste el pulgar.'::text,'pasaste'::text,'estabas pasando'::text,'has pasado'::text,'Buen movimiento: tú le pasaste el bisturí al cirujano y luego nos levantaste el pulgar.'::text),
(394349,43817,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Joli coup : tu ... le scalpel au chirurgien, puis tu nous as fait un pouce levé.'::text,'as passé'::text,'passais'::text,'as passé'::text,'Joli coup : tu as passé le scalpel au chirurgien, puis tu nous as fait un pouce levé.'::text),
(394352,43817,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Harika hareket: sen neşteri cerraha ..., sonra da bize başparmak kaldırdın.'::text,'verdin'::text,'veriyordun'::text,'verdin'::text,'Harika hareket: sen neşteri cerraha verdin, sonra da bize başparmak kaldırdın.'::text),
(394353,43817,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ügyes húzás: te ... a szikét a sebésznek, aztán feltartottad nekünk a hüvelykujjad.'::text,'odaadtad'::text,'éppen adtad'::text,'odaadtad'::text,'Ügyes húzás: te odaadtad a szikét a sebésznek, aztán feltartottad nekünk a hüvelykujjad.'::text),
(394437,43827,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du arbeitest mit ... eines Top-Chirurgen. Respekt.'::text,'der Sicherheit'::text,'einer Sicherheit'::text,'Sicherheit'::text,'Ehrlich, du arbeitest mit der Sicherheit eines Top-Chirurgen. Respekt.'::text),
(394441,43827,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти працюєш із ... топового хірурга. Респект.'::text,'впевненістю'::text,'впевненістю'::text,'впевненістю'::text,'Чесно, ти працюєш із впевненістю топового хірурга. Респект.'::text),
(394440,43827,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, tú trabajas con ... de un cirujano top. Respeto.'::text,'la seguridad'::text,'una seguridad'::text,'seguridad'::text,'Sinceramente, tú trabajas con la seguridad de un cirujano top. Respeto.'::text),
(394439,43827,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Honnêtement, tu travailles avec ... d''un grand chirurgien. Respect.'::text,'l''assurance'::text,'une assurance'::text,'assurance'::text,'Honnêtement, tu travailles avec l''assurance d''un grand chirurgien. Respect.'::text),
(394442,43827,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, sen bir üst düzey cerrahın ... çalışıyorsun. Saygılar.'::text,'özgüveniyle'::text,'bir özgüveniyle'::text,'özgüveniyle'::text,'Açıkçası, sen bir üst düzey cerrahın özgüveniyle çalışıyorsun. Saygılar.'::text),
(394443,43827,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, te egy topsebész ... dolgozol. Respekt.'::text,'magabiztosságával'::text,'egy magabiztosságával'::text,'magabiztosságával'::text,'Őszintén, te egy topsebész magabiztosságával dolgozol. Respekt.'::text),
(380091,42233,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, sie meinte, sie ... die Muffins rausholen, wenn sie goldbraun sind, ohne Witz.'::text,'würde'::text,'wird'::text,'holt'::text,'Bro, sie meinte, sie würde die Muffins rausholen, wenn sie goldbraun sind, ohne Witz.'::text),
(380095,42233,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вона сказала, що ... мафіни, коли вони стануть золотистими, без жартів.'::text,'дістане'::text,'дістане'::text,'дістає'::text,'Бро, вона сказала, що дістане мафіни, коли вони стануть золотистими, без жартів.'::text),
(380094,42233,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ella dijo que ... los muffins cuando se doraran, sin mentir.'::text,'sacaría'::text,'sacará'::text,'saca'::text,'Bro, ella dijo que sacaría los muffins cuando se doraran, sin mentir.'::text),
(380093,42233,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, elle a dit qu''elle ... les muffins quand ils seraient dorés, sans mentir.'::text,'sortirait'::text,'sortira'::text,'sort'::text,'Frérot, elle a dit qu''elle sortirait les muffins quand ils seraient dorés, sans mentir.'::text),
(380096,42233,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o, muffinleri altın rengine dönünce ... söyledi, yalan yok.'::text,'çıkaracağını'::text,'çıkaracağını'::text,'çıkardığını'::text,'Kanka, o, muffinleri altın rengine dönünce çıkaracağını söyledi, yalan yok.'::text),
(380097,42233,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ő azt mondta, hogy ... a muffinokat, amikor aranybarnák lesznek, komolyan.'::text,'kiveszi'::text,'ki fogja venni'::text,'kiveszi'::text,'Tesó, ő azt mondta, hogy kiveszi a muffinokat, amikor aranybarnák lesznek, komolyan.'::text),
(380163,42241,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Toller Plan: Hätte er den Truthahn eine Stunde später rausgeholt, ... er zu Holzkohle geworden.'::text,'wäre'::text,'wird'::text,'wurde'::text,'Toller Plan: Hätte er den Truthahn eine Stunde später rausgeholt, wäre er zu Holzkohle geworden.'::text),
(380167,42241,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чудовий план: якби він дістав індичку на годину пізніше, вона ... на вугілля.'::text,'перетворилася б'::text,'перетвориться'::text,'перетворилася'::text,'Чудовий план: якби він дістав індичку на годину пізніше, вона перетворилася б на вугілля.'::text),
(380166,42241,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gran plan: si él hubiera sacado el pavo una hora más tarde, ... en carbón.'::text,'se habría convertido'::text,'se convertirá'::text,'se convirtió'::text,'Gran plan: si él hubiera sacado el pavo una hora más tarde, se habría convertido en carbón.'::text),
(380165,42241,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Super plan : s''il avait sorti la dinde une heure plus tard, elle ... en charbon.'::text,'se serait transformée'::text,'se transformera'::text,'s''est transformée'::text,'Super plan : s''il avait sorti la dinde une heure plus tard, elle se serait transformée en charbon.'::text),
(380168,42241,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Harika plan: o hindiyi bir saat sonra çıkarsaydı, hindi kömüre ...'::text,'dönerdi'::text,'dönecek'::text,'döndü'::text,'Harika plan: o hindiyi bir saat sonra çıkarsaydı, hindi kömüre dönerdi.'::text),
(380169,42241,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Remek terv: ha ő egy órával később vette volna ki a pulykát, ... szénné.'::text,'vált volna'::text,'válik'::text,'vált'::text,'Remek terv: ha ő egy órával később vette volna ki a pulykát, vált volna szénné.'::text),
(354873,39431,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er den Wasserhahn nicht zudreht, ... das Wasser auch den Flur.'::text,'überflutet'::text,'würde überfluten'::text,'überflutete'::text,'Wenn er den Wasserhahn nicht zudreht, überflutet das Wasser auch den Flur.'::text),
(354877,39431,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо він не закрутить кран, вода ... і коридор.'::text,'затопить'::text,'затопила б'::text,'затопила'::text,'Якщо він не закрутить кран, вода затопить і коридор.'::text),
(354876,39431,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si él no cierra el grifo, el agua ... también el pasillo.'::text,'inundará'::text,'inundaría'::text,'inundó'::text,'Si él no cierra el grifo, el agua inundará también el pasillo.'::text),
(354875,39431,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il ne ferme pas le robinet, l''eau ... aussi le couloir.'::text,'inondera'::text,'inonderait'::text,'a inondé'::text,'S''il ne ferme pas le robinet, l''eau inondera aussi le couloir.'::text),
(354878,39431,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, musluğu kapatmazsa su koridoru da ...'::text,'basacak'::text,'basardı'::text,'bastı'::text,'O, musluğu kapatmazsa su koridoru da basacak.'::text),
(354879,39431,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha ő nem zárja el a csapot, a víz a folyosót is ...'::text,'elárasztja'::text,'elárasztaná'::text,'elárasztotta'::text,'Ha ő nem zárja el a csapot, a víz a folyosót is elárasztja.'::text),
(354909,39435,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, die Küche ... schon überflutet, als er reinrannte, und die Badewanne war als Nächstes dran, Alter.'::text,'war'::text,'ist'::text,'überflutet'::text,'Yo, die Küche war schon überflutet, als er reinrannte, und die Badewanne war als Nächstes dran, Alter.'::text),
(354913,39435,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, кухню вже ..., коли він забіг, а ванна була наступною, чувак.'::text,'затопило'::text,'затопило'::text,'затоплює'::text,'Йо, кухню вже затопило, коли він забіг, а ванна була наступною, чувак.'::text),
(354912,39435,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, la cocina ya ... cuando él entró corriendo, y la bañera era la siguiente, tío.'::text,'se había inundado'::text,'se ha inundado'::text,'se inunda'::text,'Oye, la cocina ya se había inundado cuando él entró corriendo, y la bañera era la siguiente, tío.'::text),
(354911,39435,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, la cuisine ... déjà inondée quand il est entré en courant, et la baignoire était la suivante, mec.'::text,'était'::text,'est'::text,'inonde'::text,'Yo, la cuisine était déjà inondée quand il est entré en courant, et la baignoire était la suivante, mec.'::text),
(354914,39435,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, o koşarak girdiğinde mutfağı çoktan su ..., sırada küvet vardı, kanka.'::text,'basmıştı'::text,'bastı'::text,'basıyor'::text,'Yo, o koşarak girdiğinde mutfağı çoktan su basmıştı, sırada küvet vardı, kanka.'::text),
(354915,39435,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, a konyhát már ... a víz, amikor ő beszaladt, és a kád volt a következő, tesó.'::text,'elárasztotta'::text,'elárasztotta'::text,'elárasztja'::text,'Figyu, a konyhát már elárasztotta a víz, amikor ő beszaladt, és a kád volt a következő, tesó.'::text),
(367626,40848,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, er ... Laufen gehasst, jetzt läuft er einen ganzen Marathon, ohne Witz.'::text,'hat früher'::text,'würde'::text,'war gewohnt'::text,'Bro, er hat früher Laufen gehasst, jetzt läuft er einen ganzen Marathon, ohne Witz.'::text),
(367630,40848,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, він ... бігати, а тепер біжить цілий марафон, без жартів.'::text,'колись ненавидів'::text,'ненавидів би'::text,'звик ненавидіти'::text,'Бро, він колись ненавидів бігати, а тепер біжить цілий марафон, без жартів.'::text),
(367629,40848,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, él ... odiar correr, ahora está corriendo un maratón entero, sin mentir.'::text,'solía'::text,'solía'::text,'estaba acostumbrado a'::text,'Bro, él solía odiar correr, ahora está corriendo un maratón entero, sin mentir.'::text),
(367628,40848,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, il ... la course, maintenant il fait un marathon entier, sans mentir.'::text,'détestait'::text,'détestait'::text,'avait l''habitude de détester'::text,'Frérot, il détestait la course, maintenant il fait un marathon entier, sans mentir.'::text),
(367631,40848,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o eskiden koşmaktan ..., şimdi koca bir maraton koşuyor, yalan yok.'::text,'nefret ederdi'::text,'nefret ederdi'::text,'nefret etmeye alışkındı'::text,'Kanka, o eskiden koşmaktan nefret ederdi, şimdi koca bir maraton koşuyor, yalan yok.'::text),
(367632,40848,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ő ... utálta a futást, most egy egész maratont fut, komolyan.'::text,'régen'::text,'régen'::text,'megszokta, hogy'::text,'Tesó, ő régen utálta a futást, most egy egész maratont fut, komolyan.'::text),
(367644,40850,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Stadtbudget von 2 Millionen Euro deckt ..., der in der Altstadt stattfindet.'::text,'den Marathon'::text,'einen Marathon'::text,'Marathon'::text,'Das Stadtbudget von 2 Millionen Euro deckt den Marathon, der in der Altstadt stattfindet.'::text),
(367648,40850,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Міський бюджет у 2 мільйони євро покриває ..., що проходить у старому місті.'::text,'марафон'::text,'марафон'::text,'марафон'::text,'Міський бюджет у 2 мільйони євро покриває марафон, що проходить у старому місті.'::text),
(367647,40850,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El presupuesto municipal de 2 millones de euros cubre ... celebrado en el casco antiguo.'::text,'el maratón'::text,'un maratón'::text,'maratón'::text,'El presupuesto municipal de 2 millones de euros cubre el maratón celebrado en el casco antiguo.'::text),
(367646,40850,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le budget municipal de 2 millions d''euros couvre ... organisé dans la vieille ville.'::text,'le marathon'::text,'un marathon'::text,'marathon'::text,'Le budget municipal de 2 millions d''euros couvre le marathon organisé dans la vieille ville.'::text),
(367649,40850,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'2 milyon avroluk şehir bütçesi, eski şehirde düzenlenen ... kapsıyor.'::text,'maratonu'::text,'bir maratonu'::text,'maratonu'::text,'2 milyon avroluk şehir bütçesi, eski şehirde düzenlenen maratonu kapsıyor.'::text),
(367650,40850,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A 2 millió eurós városi költségvetés fedezi ..., amelyet az óvárosban tartanak.'::text,'a maratont'::text,'egy maratont'::text,'maratont'::text,'A 2 millió eurós városi költségvetés fedezi a maratont, amelyet az óvárosban tartanak.'::text),
(369345,41039,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Diese Mischung ist natürlich viel zu dick, ...?'::text,'oder'::text,'nicht wahr'::text,'oder'::text,'Diese Mischung ist natürlich viel zu dick, oder?'::text),
(369349,41039,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ця суміш, звісно, занадто густа, ...?'::text,'так'::text,'правда'::text,'так'::text,'Ця суміш, звісно, занадто густа, так?'::text),
(369348,41039,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Esa mezcla está obviamente demasiado espesa, ¿...?'::text,'verdad'::text,'no'::text,'verdad'::text,'Esa mezcla está obviamente demasiado espesa, ¿verdad?'::text),
(369347,41039,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ce mélange est évidemment beaucoup trop épais, ... ?'::text,'non'::text,'hein'::text,'non'::text,'Ce mélange est évidemment beaucoup trop épais, non ?'::text),
(369350,41039,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O karışım tabii ki fazlasıyla koyu, ...?'::text,'değil mi'::text,'değil mi'::text,'değil mi'::text,'O karışım tabii ki fazlasıyla koyu, değil mi?'::text),
(369351,41039,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ez a keverék nyilván túl sűrű, ...?'::text,'ugye'::text,'nem'::text,'ugye'::text,'Ez a keverék nyilván túl sűrű, ugye?'::text),
(369426,41048,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tolle Arbeit: ... in der Pfanne ist genau so dick, wie er wollte.'::text,'Die Mischung'::text,'Eine Mischung'::text,'Mischung'::text,'Tolle Arbeit: Die Mischung in der Pfanne ist genau so dick, wie er wollte.'::text),
(369430,41048,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чудова робота: ... на пательні саме така густа, як він хотів.'::text,'суміш'::text,'суміш'::text,'суміш'::text,'Чудова робота: суміш на пательні саме така густа, як він хотів.'::text),
(369429,41048,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Buen trabajo: ... de la sartén está exactamente tan espesa como él quería.'::text,'la mezcla'::text,'una mezcla'::text,'mezcla'::text,'Buen trabajo: la mezcla de la sartén está exactamente tan espesa como él quería.'::text),
(369428,41048,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Beau travail : ... dans la poêle est exactement aussi épais qu''il le voulait.'::text,'le mélange'::text,'un mélange'::text,'mélange'::text,'Beau travail : le mélange dans la poêle est exactement aussi épais qu''il le voulait.'::text),
(369431,41048,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Harika iş: tavadaki ... tam da onun istediği kadar koyu.'::text,'karışım'::text,'bir karışım'::text,'karışım'::text,'Harika iş: tavadaki karışım tam da onun istediği kadar koyu.'::text),
(369432,41048,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szép munka: ... a serpenyőben pontosan olyan sűrű, amilyet ő akart.'::text,'a keverék'::text,'egy keverék'::text,'keverék'::text,'Szép munka: a keverék a serpenyőben pontosan olyan sűrű, amilyet ő akart.'::text),
(384213,42691,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Girl, angeblich hat die Frau in Schwarz, ... Schrei am lautesten war, das Spiel gewonnen.'::text,'deren'::text,'die'::text,'welche'::text,'Girl, angeblich hat die Frau in Schwarz, deren Schrei am lautesten war, das Spiel gewonnen.'::text),
(384217,42691,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, жінка в чорному, ... крик був найгучнішим, виграла гру.'::text,'чий'::text,'яка'::text,'котрий'::text,'Подруго, кажуть, жінка в чорному, чий крик був найгучнішим, виграла гру.'::text),
(384216,42691,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer la mujer de negro, ... grito fue el más fuerte, ganó el juego.'::text,'cuyo'::text,'que'::text,'el cual'::text,'Tía, al parecer la mujer de negro, cuyo grito fue el más fuerte, ganó el juego.'::text),
(384215,42691,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment la femme en noir, ... le cri était le plus fort, a gagné le jeu.'::text,'dont'::text,'qui'::text,'lequel'::text,'Meuf, apparemment la femme en noir, dont le cri était le plus fort, a gagné le jeu.'::text),
