(393030,43670,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag ő megígérte: „Én ... a leghosszabb csíkot a faluban.”'::text,'levágom'::text,'vágni fogom'::text,'vágom'::text,'Csajszi, állítólag ő megígérte: „Én levágom a leghosszabb csíkot a faluban.”'::text),
(393105,43679,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... zehn ganze Minuten lang geschält, bevor sie es wagte, von diesem Streifen aufzublicken! Unglaublich!'::text,'hatte'::text,'war'::text,'hat'::text,'Sie hatte zehn ganze Minuten lang geschält, bevor sie es wagte, von diesem Streifen aufzublicken! Unglaublich!'::text),
(393109,43679,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... цілих десять хвилин, перш ніж наважилася підвести очі від тієї смужки! Неймовірно!'::text,'чистила'::text,'чистила'::text,'чистить'::text,'Вона чистила цілих десять хвилин, перш ніж наважилася підвести очі від тієї смужки! Неймовірно!'::text),
(393108,43679,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ella ... durante diez minutos enteros antes de atreverse a levantar la vista de esa tira! ¡Increíble!'::text,'había estado pelando'::text,'estaba pelando'::text,'ha estado pelando'::text,'¡Ella había estado pelando durante diez minutos enteros antes de atreverse a levantar la vista de esa tira! ¡Increíble!'::text),
(393107,43679,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... pendant dix bonnes minutes avant d''oser lever les yeux de cette bande ! Incroyable !'::text,'avait épluché'::text,'épluchait'::text,'a épluché'::text,'Elle avait épluché pendant dix bonnes minutes avant d''oser lever les yeux de cette bande ! Incroyable !'::text),
(393110,43679,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, o şeritten başını kaldırmaya cesaret etmeden önce tam on dakika ...! İnanılmaz!'::text,'soymuştu'::text,'soyuyordu'::text,'soyuyor'::text,'O, o şeritten başını kaldırmaya cesaret etmeden önce tam on dakika soymuştu! İnanılmaz!'::text),
(393111,43679,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő tíz teljes percig ..., mielőtt fel mert nézni arról a csíkról! Hihetetlen!'::text,'hámozott'::text,'hámozott'::text,'hámoz'::text,'Ő tíz teljes percig hámozott, mielőtt fel mert nézni arról a csíkról! Hihetetlen!'::text),
(376338,41816,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um diese Zeit ... er das Medikament von diesem Rezept nehmen.'::text,'wird'::text,'wird'::text,'nimmt'::text,'Morgen um diese Zeit wird er das Medikament von diesem Rezept nehmen.'::text),
(376342,41816,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра в цей час він ... ліки за цим рецептом.'::text,'прийматиме'::text,'прийме'::text,'приймає'::text,'Завтра в цей час він прийматиме ліки за цим рецептом.'::text),
(376341,41816,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a esta hora él ... la medicina de esta receta.'::text,'estará tomando'::text,'tomará'::text,'toma'::text,'Mañana a esta hora él estará tomando la medicina de esta receta.'::text),
(376340,41816,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à cette heure-ci, il ... le médicament de cette ordonnance.'::text,'sera en train de prendre'::text,'prendra'::text,'prend'::text,'Demain à cette heure-ci, il sera en train de prendre le médicament de cette ordonnance.'::text),
(376343,41816,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatte o bu reçetedeki ilacı ...'::text,'alıyor olacak'::text,'alacak'::text,'alıyor'::text,'Yarın bu saatte o bu reçetedeki ilacı alıyor olacak.'::text),
(376344,41816,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap ilyenkor ő ... a gyógyszert erről a receptről.'::text,'szedni fogja'::text,'beveszi'::text,'szedi'::text,'Holnap ilyenkor ő szedni fogja a gyógyszert erről a receptről.'::text),
(361209,40135,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie steht in einem Haus, also ist sie eine Zimmerpflanze, ...?'::text,'oder'::text,'nicht wahr'::text,'ja'::text,'Sie steht in einem Haus, also ist sie eine Zimmerpflanze, oder?'::text),
(361213,40135,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона в будинку, отже, це кімнатна рослина, ...?'::text,'так'::text,'правда'::text,'так'::text,'Вона в будинку, отже, це кімнатна рослина, так?'::text),
(361212,40135,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella está en una casa, así que es una planta de interior, ¿...?'::text,'verdad'::text,'no'::text,'sí'::text,'Ella está en una casa, así que es una planta de interior, ¿verdad?'::text),
(361211,40135,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle est dans une maison, donc c''est une plante d''intérieur, ... ?'::text,'non'::text,'hein'::text,'oui'::text,'Elle est dans une maison, donc c''est une plante d''intérieur, non ?'::text),
(361214,40135,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O bir evde, yani ev bitkisi, ...?'::text,'değil mi'::text,'değil mi'::text,'öyle mi'::text,'O bir evde, yani ev bitkisi, değil mi?'::text),
(361215,40135,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az egy házban van, szóval szobanövény, ...?'::text,'ugye'::text,'nem'::text,'igaz'::text,'Az egy házban van, szóval szobanövény, ugye?'::text),
(361290,40144,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, er ... weniger Zimmerpflanzen kaufen sollen, es gibt keinen Platz, Bro.'::text,'hätte'::text,'muss'::text,'würde'::text,'Alter, er hätte weniger Zimmerpflanzen kaufen sollen, es gibt keinen Platz, Bro.'::text),
(361294,40144,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, він ... купити менше кімнатних рослин, тут немає місця, бро.'::text,'мав би'::text,'мабуть мусив'::text,'би'::text,'Чувак, він мав би купити менше кімнатних рослин, тут немає місця, бро.'::text),
(361293,40144,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, él ... comprado menos plantas de interior, no hay espacio, bro.'::text,'debería haber'::text,'debe de haber'::text,'habría'::text,'Tío, él debería haber comprado menos plantas de interior, no hay espacio, bro.'::text),
(361292,40144,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, il ... acheté moins de plantes d''intérieur, il n''y a pas de place, frérot.'::text,'aurait dû'::text,'a dû'::text,'aurait'::text,'Mec, il aurait dû acheté moins de plantes d''intérieur, il n''y a pas de place, frérot.'::text),
(361295,40144,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o daha az ev bitkisi ..., yer yok, kardeşim.'::text,'almalıydı'::text,'almış olmalı'::text,'alırdı'::text,'Kanka, o daha az ev bitkisi almalıydı, yer yok, kardeşim.'::text),
(361296,40144,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ő ... kevesebb szobanövényt, nincs hely, haver.'::text,'inkább vett volna'::text,'biztos vett'::text,'venne'::text,'Tesó, ő inkább vett volna kevesebb szobanövényt, nincs hely, haver.'::text),
(363468,40386,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... schreiend auf dem Rasen, als sein Mitspieler in ihn krachte!'::text,'kniete'::text,'kniete sich hin'::text,'hat gekniet'::text,'Er kniete schreiend auf dem Rasen, als sein Mitspieler in ihn krachte!'::text),
(363472,40386,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... на траві, кричачи, коли в нього врізався товариш по команді!'::text,'стояв на колінах'::text,'став на коліна'::text,'став на коліна'::text,'Він стояв на колінах на траві, кричачи, коли в нього врізався товариш по команді!'::text),
(363471,40386,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Él ... en el césped, gritando, cuando su compañero chocó contra él!'::text,'estaba arrodillado'::text,'se arrodilló'::text,'se ha arrodillado'::text,'¡Él estaba arrodillado en el césped, gritando, cuando su compañero chocó contra él!'::text),
(363470,40386,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... sur la pelouse en hurlant quand son coéquipier lui est rentré dedans !'::text,'était à genoux'::text,'s''est agenouillé'::text,'s''est agenouillé'::text,'Il était à genoux sur la pelouse en hurlant quand son coéquipier lui est rentré dedans !'::text),
(363473,40386,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Takım arkadaşı ona çarptığında o çimlerde bağırarak ...!'::text,'diz çökmüş duruyordu'::text,'diz çöktü'::text,'diz çöktü'::text,'Takım arkadaşı ona çarptığında o çimlerde bağırarak diz çökmüş duruyordu!'::text),
(363474,40386,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő ... a füvön, üvöltve, amikor a csapattársa nekirohant!'::text,'térdelt'::text,'letérdelt'::text,'letérdelt'::text,'Ő térdelt a füvön, üvöltve, amikor a csapattársa nekirohant!'::text),
(363504,40390,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Verteidiger wünscht sich, er ... den Ball gestoppt, bevor der Stürmer knien und feiern konnte.'::text,'hätte'::text,'stoppte'::text,'würde'::text,'Der Verteidiger wünscht sich, er hätte den Ball gestoppt, bevor der Stürmer knien und feiern konnte.'::text),
(363508,40390,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Захисникові б хотілося, щоб він ... м''яч, перш ніж нападник зміг стати на коліна й святкувати.'::text,'зупинив'::text,'зупинив'::text,'зупиняв'::text,'Захисникові б хотілося, щоб він зупинив м''яч, перш ніж нападник зміг стати на коліна й святкувати.'::text),
(363507,40390,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El defensa desearía que él ... el balón antes de que el delantero pudiera arrodillarse y celebrarlo.'::text,'hubiera parado'::text,'parara'::text,'pararía'::text,'El defensa desearía que él hubiera parado el balón antes de que el delantero pudiera arrodillarse y celebrarlo.'::text),
(363506,40390,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le défenseur aimerait ... le ballon avant que l''attaquant puisse s''agenouiller et célébrer.'::text,'avoir arrêté'::text,'arrêter'::text,'arrêter'::text,'Le défenseur aimerait avoir arrêté le ballon avant que l''attaquant puisse s''agenouiller et célébrer.'::text),
(363509,40390,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Defans oyuncusu, forvet diz çöküp kutlama yapmadan önce topu ... diliyor.'::text,'durdurmuş olmayı'::text,'durdurmayı'::text,'durdurmayı'::text,'Defans oyuncusu, forvet diz çöküp kutlama yapmadan önce topu durdurmuş olmayı diliyor.'::text),
(363510,40390,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A védő azt kívánja, bárcsak ... a labdát, mielőtt a csatár letérdelhetett és ünnepelhetett.'::text,'megállította volna'::text,'megállította'::text,'megállítaná'::text,'A védő azt kívánja, bárcsak megállította volna a labdát, mielőtt a csatár letérdelhetett és ünnepelhetett.'::text),
(371001,41223,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der große Mann schrie, dass sich das Viertel für immer an dieses Spiel erinnern ...!'::text,'würde'::text,'wird'::text,'ist'::text,'Der große Mann schrie, dass sich das Viertel für immer an dieses Spiel erinnern würde!'::text),
(371005,41223,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Великий чоловік вигукнув, що район ... цей матч назавжди!'::text,'пам''ятатиме'::text,'пам''ятатиме'::text,'є'::text,'Великий чоловік вигукнув, що район пам''ятатиме цей матч назавжди!'::text),
(371004,41223,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El hombre grande gritó que el barrio ... este partido para siempre!'::text,'recordaría'::text,'recordará'::text,'es'::text,'¡El hombre grande gritó que el barrio recordaría este partido para siempre!'::text),
(371003,41223,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le grand homme a crié que le quartier se ... de ce match pour toujours !'::text,'souviendrait'::text,'souviendra'::text,'est'::text,'Le grand homme a crié que le quartier se souviendrait de ce match pour toujours !'::text),
(371006,41223,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İri adam, mahallenin bu maçı sonsuza kadar ... bağırdı!'::text,'hatırlayacağını'::text,'hatırlayacağını'::text,NULL::text,'İri adam, mahallenin bu maçı sonsuza kadar hatırlayacağını bağırdı!'::text),
(371007,41223,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nagydarab férfi azt kiabálta, hogy a környék örökre ... erre a meccsre!'::text,'emlékezni fog'::text,'emlékezni fog'::text,NULL::text,'A nagydarab férfi azt kiabálta, hogy a környék örökre emlékezni fog erre a meccsre!'::text),
(371010,41224,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Niemand im Viertel ging in dieser Nacht früh ...; das Spiel war absolut episch!'::text,'ins Bett'::text,'in das Bett'::text,'in ein Bett'::text,'Niemand im Viertel ging in dieser Nacht früh ins Bett; das Spiel war absolut episch!'::text),
(371014,41224,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ніхто в районі не ліг ... рано тієї ночі; матч був абсолютно епічний!'::text,'спати'::text,'у ліжко'::text,'у ліжко'::text,'Ніхто в районі не ліг спати рано тієї ночі; матч був абсолютно епічний!'::text),
(371013,41224,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nadie del barrio se fue ... temprano esa noche; ¡el partido fue absolutamente épico!'::text,'a la cama'::text,'a la cama'::text,'a una cama'::text,'Nadie del barrio se fue a la cama temprano esa noche; ¡el partido fue absolutamente épico!'::text),
(371012,41224,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Personne dans le quartier n''est allé ... tôt ce soir-là ; le match était absolument épique !'::text,'au lit'::text,'au lit'::text,'dans un lit'::text,'Personne dans le quartier n''est allé au lit tôt ce soir-là ; le match était absolument épique !'::text),
(371015,41224,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O gece mahallede kimse erkenden ...; maç kesinlikle efsaneydi!'::text,'yatmadı'::text,'yatağa gitmedi'::text,'bir yatağa gitmedi'::text,'O gece mahallede kimse erkenden yatmadı; maç kesinlikle efsaneydi!'::text),
(371016,41224,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aznap este senki sem ment a környéken korán ...; a meccs abszolút epikus volt!'::text,'aludni'::text,'az ágyba'::text,'egy ágyba'::text,'Aznap este senki sem ment a környéken korán aludni; a meccs abszolút epikus volt!'::text),
(342048,38006,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du hast gesagt, du ... jedes Kabel in zehn Minuten anschließen, und ehrlich, du hast es geschafft.'::text,'würdest'::text,'wirst'::text,'schließt'::text,'Du hast gesagt, du würdest jedes Kabel in zehn Minuten anschließen, und ehrlich, du hast es geschafft.'::text),
(342052,38006,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти сказав, що ... кожен кабель за десять хвилин, і, чесно, ти це зробив.'::text,'підключиш'::text,'підключиш'::text,'підключаєш'::text,'Ти сказав, що підключиш кожен кабель за десять хвилин, і, чесно, ти це зробив.'::text),
(342051,38006,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tú dijiste que ... todos los cables en diez minutos, y la verdad, lo hiciste.'::text,'conectarías'::text,'conectarás'::text,'estás conectando'::text,'Tú dijiste que conectarías todos los cables en diez minutos, y la verdad, lo hiciste.'::text),
(342050,38006,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu as dit que tu ... chaque câble en dix minutes, et franchement, tu l''as fait.'::text,'brancherais'::text,'brancheras'::text,'branches'::text,'Tu as dit que tu brancherais chaque câble en dix minutes, et franchement, tu l''as fait.'::text),
(342053,38006,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sen her kabloyu on dakikada ... söyledin ve açıkçası, yaptın da.'::text,'bağlayacağını'::text,'bağlayacağını'::text,'bağladığını'::text,'Sen her kabloyu on dakikada bağlayacağını söyledin ve açıkçası, yaptın da.'::text),
(342054,38006,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Te azt mondtad, hogy tíz perc alatt ... minden kábelt, és őszintén, sikerült.'::text,'bekötöd'::text,'be fogod kötni'::text,'kötöd be'::text,'Te azt mondtad, hogy tíz perc alatt bekötöd minden kábelt, és őszintén, sikerült.'::text),
(342075,38009,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gerade ... er Kabel hinter dem Schreibtisch in einem dunklen Zimmer an. Perfekte Planung.'::text,'schließt'::text,'schließt'::text,'hat'::text,'Gerade schließt er Kabel hinter dem Schreibtisch in einem dunklen Zimmer an. Perfekte Planung.'::text),
(342079,38009,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Просто зараз він ... кабелі за столом у темній кімнаті. Бездоганне планування.'::text,'підключає'::text,'підключає'::text,'підключив'::text,'Просто зараз він підключає кабелі за столом у темній кімнаті. Бездоганне планування.'::text),
(342078,38009,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahora mismo él ... cables detrás del escritorio en una habitación a oscuras. Planificación impecable.'::text,'está conectando'::text,'conecta'::text,'ha conectado'::text,'Ahora mismo él está conectando cables detrás del escritorio en una habitación a oscuras. Planificación impecable.'::text),
(342077,38009,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment, il ... des câbles derrière le bureau dans une pièce sombre. Organisation parfaite.'::text,'branche'::text,'branche'::text,'a branché'::text,'En ce moment, il branche des câbles derrière le bureau dans une pièce sombre. Organisation parfaite.'::text),
(342080,38009,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda o karanlık bir odada masanın arkasında kablo ...; kusursuz planlama.'::text,'bağlıyor'::text,'bağlar'::text,'bağladı'::text,'Şu anda o karanlık bir odada masanın arkasında kablo bağlıyor; kusursuz planlama.'::text),
(342081,38009,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp most ő kábeleket ... az asztal mögött egy sötét szobában. Hibátlan tervezés.'::text,'köt be'::text,'köt be'::text,'kötött be'::text,'Épp most ő kábeleket köt be az asztal mögött egy sötét szobában. Hibátlan tervezés.'::text),
(402645,44739,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis der Klempner das Rohr schließt, ... das Wasser sein ganzes Hemd durchnässt haben.'::text,'wird'::text,'wird'::text,'durchnässt'::text,'Bis der Klempner das Rohr schließt, wird das Wasser sein ganzes Hemd durchnässt haben.'::text),
(402649,44739,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки сантехнік перекриє трубу, вода ... всю його сорочку.'::text,'намочить'::text,'намочить'::text,'мочить'::text,'Поки сантехнік перекриє трубу, вода намочить всю його сорочку.'::text),
(402648,44739,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando el fontanero cierre la tubería, el agua ... toda su camisa.'::text,'habrá mojado'::text,'mojará'::text,'moja'::text,'Para cuando el fontanero cierre la tubería, el agua habrá mojado toda su camisa.'::text),
(402647,44739,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le temps que le plombier ferme le tuyau, l''eau ... toute sa chemise.'::text,'aura mouillé'::text,'mouillera'::text,'mouille'::text,'Le temps que le plombier ferme le tuyau, l''eau aura mouillé toute sa chemise.'::text),
(402650,44739,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesisatçı boruyu kapatana kadar su bütün gömleğini ...'::text,'ıslatmış olacak'::text,'ıslatacak'::text,'ıslatıyor'::text,'Tesisatçı boruyu kapatana kadar su bütün gömleğini ıslatmış olacak.'::text),
(402651,44739,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a vízvezeték-szerelő elzárja a csövet, a víz ... az egész ingét.'::text,'eláztatja'::text,'el fogja áztatni'::text,'áztatja'::text,'Mire a vízvezeték-szerelő elzárja a csövet, a víz eláztatja az egész ingét.'::text),
(345720,38414,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während der Mann über den nassen Platz ..., flog ein Dutzend Tauben auf.'::text,'rannte'::text,'rannte'::text,'ist gerannt'::text,'Während der Mann über den nassen Platz rannte, flog ein Dutzend Tauben auf.'::text),
(345724,38414,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки чоловік ... мокрою площею, десяток голубів злетіли вгору.'::text,'мчав'::text,'промчав'::text,'промчав'::text,'Поки чоловік мчав мокрою площею, десяток голубів злетіли вгору.'::text),
(345723,38414,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mientras el hombre ... por la plaza mojada, una docena de palomas echó a volar.'::text,'corría'::text,'corrió'::text,'ha corrido'::text,'Mientras el hombre corría por la plaza mojada, una docena de palomas echó a volar.'::text),
(345722,38414,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant que l''homme ... la place mouillée, une douzaine de pigeons s''est envolée.'::text,'traversait en courant'::text,'a traversé en courant'::text,'a traversé en courant'::text,'Pendant que l''homme traversait en courant la place mouillée, une douzaine de pigeons s''est envolée.'::text),
(345725,38414,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adam ıslak meydanda ..., bir düzine güvercin havalandı.'::text,'koşarken'::text,'koştuğunda'::text,'koşmuşken'::text,'Adam ıslak meydanda koşarken, bir düzine güvercin havalandı.'::text),
(345726,38414,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Miközben a férfi ... a nedves téren, egy tucat galamb felrepült.'::text,'rohant át'::text,'átrohant'::text,'átrohant'::text,'Miközben a férfi rohant át a nedves téren, egy tucat galamb felrepült.'::text),
(338808,37646,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er blieb nicht stehen, um sich die Kathedrale anzusehen, und die Tauben ...; tolles Sightseeing.'::text,'auch nicht'::text,'auch'::text,'auch nicht'::text,'Er blieb nicht stehen, um sich die Kathedrale anzusehen, und die Tauben auch nicht; tolles Sightseeing.'::text),
(338812,37646,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він не зупинився, щоб подивитися на собор, і голуби ...; чудова екскурсія.'::text,'так само ні'::text,'так само'::text,'так само ні'::text,'Він не зупинився, щоб подивитися на собор, і голуби так само ні; чудова екскурсія.'::text),
(338811,37646,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él no se paró a mirar la catedral, y ... las palomas. Gran turismo.'::text,'tampoco'::text,'también'::text,'tampoco'::text,'Él no se paró a mirar la catedral, y tampoco las palomas. Gran turismo.'::text),
(338810,37646,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ne s''est pas arrêté pour regarder la cathédrale, et les pigeons ... ; super visite.'::text,'non plus'::text,'aussi'::text,'non plus'::text,'Il ne s''est pas arrêté pour regarder la cathédrale, et les pigeons non plus ; super visite.'::text),
(338813,37646,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O katedrale bakmak için durmadı, güvercinler de ...; harika gezi.'::text,'durmadı'::text,'durdu'::text,'durmadı'::text,'O katedrale bakmak için durmadı, güvercinler de durmadı; harika gezi.'::text),
(338814,37646,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő nem állt meg, hogy megnézze a katedrálist, és a galambok ...; remek városnézés.'::text,'sem'::text,'is'::text,'sem'::text,'Ő nem állt meg, hogy megnézze a katedrálist, és a galambok sem; remek városnézés.'::text),
(338817,37647,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum Abendessen ... er eine Kathedrale, einen See und einen Teller Dumplings gesehen haben. Echt anstrengend.'::text,'wird'::text,'wird'::text,'wird gerade'::text,'Bis zum Abendessen wird er eine Kathedrale, einen See und einen Teller Dumplings gesehen haben. Echt anstrengend.'::text),
(338821,37647,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До вечері він ... один собор, одне озеро й одну тарілку дамплінгів. Справді виснажливо.'::text,'побачить'::text,'побачить'::text,'бачитиме'::text,'До вечері він побачить один собор, одне озеро й одну тарілку дамплінгів. Справді виснажливо.'::text),
(338820,37647,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para la cena, él ... una catedral, un lago y un plato de dumplings. Agotador de verdad.'::text,'habrá visto'::text,'verá'::text,'estará viendo'::text,'Para la cena, él habrá visto una catedral, un lago y un plato de dumplings. Agotador de verdad.'::text),
(338819,37647,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici le dîner, il ... une cathédrale, un lac et une assiette de dumplings. Vraiment épuisant.'::text,'aura vu'::text,'verra'::text,'sera en train de voir'::text,'D''ici le dîner, il aura vu une cathédrale, un lac et une assiette de dumplings. Vraiment épuisant.'::text),
(338822,37647,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Akşam yemeğine kadar o bir katedral, bir göl ve bir tabak dumpling ...; gerçekten yorucu.'::text,'görmüş olacak'::text,'görecek'::text,'görüyor olacak'::text,'Akşam yemeğine kadar o bir katedral, bir göl ve bir tabak dumpling görmüş olacak; gerçekten yorucu.'::text),
(338823,37647,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vacsorára ő ... egy katedrálist, egy tavat és egy tányér dumplingot. Tényleg kimerítő.'::text,'már látott'::text,'látni fog'::text,'látni fog'::text,'Vacsorára ő már látott egy katedrálist, egy tavat és egy tányér dumplingot. Tényleg kimerítő.'::text),
(375258,41696,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die beiden Politiker ... sich gerade an, als der riesige Hammer niedersauste.'::text,'schrien'::text,'haben'::text,'schreien'::text,'Die beiden Politiker schrien sich gerade an, als der riesige Hammer niedersauste.'::text),
(375262,41696,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Двоє політиків ... один на одного, коли впав величезний молоток.'::text,'кричали'::text,'накричали'::text,'кричать'::text,'Двоє політиків кричали один на одного, коли впав величезний молоток.'::text),
(375261,41696,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los dos políticos se ... cuando cayó el enorme mazo.'::text,'estaban gritando'::text,'han gritado'::text,'gritan'::text,'Los dos políticos se estaban gritando cuando cayó el enorme mazo.'::text),
(375260,41696,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les deux politiciens se ... dessus quand l''énorme marteau est tombé.'::text,'criaient'::text,'sont crié'::text,'crient'::text,'Les deux politiciens se criaient dessus quand l''énorme marteau est tombé.'::text),
(375263,41696,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kocaman tokmak indiğinde iki politikacı birbirine ...'::text,'bağırıyordu'::text,'bağırdı'::text,'bağırır'::text,'Kocaman tokmak indiğinde iki politikacı birbirine bağırıyordu.'::text),
(375264,41696,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A két politikus éppen ... egymásra, amikor lecsapott a hatalmas kalapács.'::text,'kiabált'::text,'kiabált'::text,'kiabál'::text,'A két politikus éppen kiabált egymásra, amikor lecsapott a hatalmas kalapács.'::text),
(337818,37536,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du ... seit 6 Uhr morgens Wahlplakate, und deine Energie ist unfassbar.'::text,'klebst'::text,'klebst'::text,'klebst'::text,'Ehrlich, du klebst seit 6 Uhr morgens Wahlplakate, und deine Energie ist unfassbar.'::text),
(337822,37536,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти ... передвиборчі плакати з 6 ранку, і твоя енергія неймовірна.'::text,'клеїш'::text,'клеїш'::text,'клеїш'::text,'Чесно, ти клеїш передвиборчі плакати з 6 ранку, і твоя енергія неймовірна.'::text),
(337821,37536,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, tú ... carteles de campaña desde las 6 de la mañana, y tu energía es una locura.'::text,'llevas pegando'::text,'estás pegando'::text,'pegas'::text,'Sinceramente, tú llevas pegando carteles de campaña desde las 6 de la mañana, y tu energía es una locura.'::text),
(337820,37536,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Honnêtement, tu ... des affiches de campagne depuis 6 h du matin, et ton énergie est dingue.'::text,'colles'::text,'colles'::text,'colles'::text,'Honnêtement, tu colles des affiches de campagne depuis 6 h du matin, et ton énergie est dingue.'::text),
(337823,37536,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, sen sabah 6''dan beri seçim afişi ... ve enerjin inanılmaz.'::text,'yapıştırıyorsun'::text,'yapıştırıyorsun'::text,'yapıştırırsın'::text,'Açıkçası, sen sabah 6''dan beri seçim afişi yapıştırıyorsun ve enerjin inanılmaz.'::text),
(337824,37536,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, te reggel 6 óta ... a kampányplakátokat, és elképesztő az energiád.'::text,'ragasztod'::text,'ragasztod'::text,'ragasztod'::text,'Őszintén, te reggel 6 óta ragasztod a kampányplakátokat, és elképesztő az energiád.'::text),
(337899,37545,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Girl, ich hab gehört, dass das Wahlkampfteam bis zum Wahltag zehntausend Plakate ...'::text,'geklebt haben wird'::text,'kleben wird'::text,'klebt'::text,'Girl, ich hab gehört, dass das Wahlkampfteam bis zum Wahltag zehntausend Plakate geklebt haben wird.'::text),
(337903,37545,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, я чула, що до дня виборів команда кампанії ... десять тисяч плакатів.'::text,'наклеїть'::text,'клеїтиме'::text,'клеїть'::text,'Подруго, я чула, що до дня виборів команда кампанії наклеїть десять тисяч плакатів.'::text),
(337902,37545,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, yo oí que para el día de las elecciones el equipo de campaña ... diez mil carteles.'::text,'habrá pegado'::text,'pegará'::text,'pega'::text,'Tía, yo oí que para el día de las elecciones el equipo de campaña habrá pegado diez mil carteles.'::text),
(337901,37545,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, j''ai entendu que d''ici le jour de l''élection, l''équipe de campagne ... dix mille affiches.'::text,'aura collé'::text,'collera'::text,'colle'::text,'Meuf, j''ai entendu que d''ici le jour de l''élection, l''équipe de campagne aura collé dix mille affiches.'::text),
(337904,37545,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, ben duydum ki seçim gününe kadar kampanya ekibi on bin afiş ...'::text,'yapıştırmış olacak'::text,'yapıştıracak'::text,'yapıştırıyor'::text,'Kızım, ben duydum ki seçim gününe kadar kampanya ekibi on bin afiş yapıştırmış olacak.'::text),
(337905,37545,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, én úgy hallottam, hogy a választás napjára a kampánycsapat tízezer plakátot ...'::text,'kiragaszt'::text,'ki fog ragasztani'::text,'ragaszt'::text,'Csajszi, én úgy hallottam, hogy a választás napjára a kampánycsapat tízezer plakátot kiragaszt.'::text),
(374808,41646,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn Plastik in einem Fluss ..., treibt es da einfach jahrelang, ohne Witz, Mann.'::text,'landet'::text,'landete'::text,'landen wird'::text,'Wenn Plastik in einem Fluss landet, treibt es da einfach jahrelang, ohne Witz, Mann.'::text),
(374812,41646,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо пластик ... в річці, він просто плаває там роками, без жартів, чувак.'::text,'опиняється'::text,'опинився'::text,'опиниться'::text,'Якщо пластик опиняється в річці, він просто плаває там роками, без жартів, чувак.'::text),
(374811,41646,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el plástico ... en un río, simplemente flota ahí durante años, sin mentir, tío.'::text,'acaba'::text,'acabó'::text,'acabará'::text,'Si el plástico acaba en un río, simplemente flota ahí durante años, sin mentir, tío.'::text),
(374810,41646,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le plastique ... dans une rivière, il flotte juste là pendant des années, sans mentir, mec.'::text,'finit'::text,'a fini'::text,'finira'::text,'Si le plastique finit dans une rivière, il flotte juste là pendant des années, sans mentir, mec.'::text),
(374813,41646,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Plastik bir nehre ..., orada yıllarca öylece yüzer, yalan yok, kanka.'::text,'düşerse'::text,'düştüyse'::text,'düşecekse'::text,'Plastik bir nehre düşerse, orada yıllarca öylece yüzer, yalan yok, kanka.'::text),
(374814,41646,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a műanyag egy folyóban ..., évekig csak úszik ott, komolyan, tesó.'::text,'köt ki'::text,'kötött ki'::text,'fog kikötni'::text,'Ha a műanyag egy folyóban köt ki, évekig csak úszik ott, komolyan, tesó.'::text),
(374853,41651,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum Abend ... sie das ganze Plastik am Ufer gesammelt haben.'::text,'wird'::text,'wird'::text,'sammelt'::text,'Bis zum Abend wird sie das ganze Plastik am Ufer gesammelt haben.'::text),
(374857,41651,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До вечора вона ... весь пластик біля берега.'::text,'збере'::text,'збиратиме'::text,'збирає'::text,'До вечора вона збере весь пластик біля берега.'::text),
(374856,41651,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para la noche, ella ... todo el plástico cerca de la orilla.'::text,'habrá recogido'::text,'recogerá'::text,'recoge'::text,'Para la noche, ella habrá recogido todo el plástico cerca de la orilla.'::text),
(374855,41651,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici ce soir, elle ... tout le plastique près de la rive.'::text,'aura ramassé'::text,'ramassera'::text,'ramasse'::text,'D''ici ce soir, elle aura ramassé tout le plastique près de la rive.'::text),
(374858,41651,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Akşama kadar o, kıyıya yakın bütün plastiği ...'::text,'toplamış olacak'::text,'toplayacak'::text,'topluyor'::text,'Akşama kadar o, kıyıya yakın bütün plastiği toplamış olacak.'::text),
(374859,41651,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Estére ő ... az összes műanyagot a part mellett.'::text,'összeszedi'::text,'össze fogja szedni'::text,'szedi'::text,'Estére ő összeszedi az összes műanyagot a part mellett.'::text),
(397749,44195,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Straßenbahn ... gerade die Gleise hinunter, als die junge Frau von ihrer Stufe sprang.'::text,'rollte'::text,'rollte'::text,'ist gerollt'::text,'Die Straßenbahn rollte gerade die Gleise hinunter, als die junge Frau von ihrer Stufe sprang.'::text),
(397753,44195,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Трамвай ... коліями вниз, коли молода жінка зістрибнула з його сходинки.'::text,'котився'::text,'скотився'::text,'скотився'::text,'Трамвай котився коліями вниз, коли молода жінка зістрибнула з його сходинки.'::text),
(397752,44195,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El tranvía ... por la vía cuando la joven saltó de su escalón.'::text,'estaba bajando'::text,'bajó'::text,'ha bajado'::text,'El tranvía estaba bajando por la vía cuando la joven saltó de su escalón.'::text),
(397751,44195,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le tram ... sur les rails quand la jeune femme a sauté de sa marche.'::text,'descendait'::text,'est descendu'::text,'est descendu'::text,'Le tram descendait sur les rails quand la jeune femme a sauté de sa marche.'::text),
(397754,44195,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genç kadın basamağından atladığında tramvay raylardan aşağı ...'::text,'iniyordu'::text,'indi'::text,'indi'::text,'Genç kadın basamağından atladığında tramvay raylardan aşağı iniyordu.'::text),
(397755,44195,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A villamos éppen ... lefelé a síneken, amikor a fiatal nő leugrott a lépcsőjéről.'::text,'gurult'::text,'gurult'::text,'gurult'::text,'A villamos éppen gurult lefelé a síneken, amikor a fiatal nő leugrott a lépcsőjéről.'::text),
(396795,44089,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er hat die Fliesen angefasst, weil sie direkt da waren, und ...'::text,'ich auch.'::text,'ich auch.'::text,'ich auch.'::text,'Er hat die Fliesen angefasst, weil sie direkt da waren, und ich auch.'::text),
(396799,44089,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він торкнувся плиток, бо вони були прямо там, і ...'::text,'я теж.'::text,'я теж.'::text,'я теж.'::text,'Він торкнувся плиток, бо вони були прямо там, і я теж.'::text),
(396798,44089,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él tocó los azulejos porque estaban justo ahí, y ...'::text,'yo también.'::text,'yo también.'::text,'yo también.'::text,'Él tocó los azulejos porque estaban justo ahí, y yo también.'::text),
(396797,44089,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a touché les carreaux parce qu''ils étaient juste là, et ...'::text,'moi aussi.'::text,'moi aussi.'::text,'moi aussi.'::text,'Il a touché les carreaux parce qu''ils étaient juste là, et moi aussi.'::text),
(396800,44089,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, fayanslara dokundu çünkü tam oradaydılar ve ...'::text,'ben de.'::text,'ben de.'::text,'ben de.'::text,'O, fayanslara dokundu çünkü tam oradaydılar ve ben de.'::text),
(396801,44089,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő megérintette a csempéket, mert pont ott voltak, és ...'::text,'én is.'::text,'én is.'::text,'én is.'::text,'Ő megérintette a csempéket, mert pont ott voltak, és én is.'::text),
(396867,44097,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Im Allgemeinen kosten ..., die von Hand bemalt sind wie diese blauen, mehr als schlichte.'::text,'Fliesen'::text,'die Fliesen'::text,'eine Fliese'::text,'Im Allgemeinen kosten Fliesen, die von Hand bemalt sind wie diese blauen, mehr als schlichte.'::text),
(396871,44097,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Загалом ..., розписані вручну, як ці сині, коштують дорожче, ніж звичайні.'::text,'плитки'::text,'плитки'::text,'плитка'::text,'Загалом плитки, розписані вручну, як ці сині, коштують дорожче, ніж звичайні.'::text),
(396870,44097,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En general, ... pintados a mano, como estos azules, cuestan más que los lisos.'::text,'los azulejos'::text,'los azulejos'::text,'un azulejo'::text,'En general, los azulejos pintados a mano, como estos azules, cuestan más que los lisos.'::text),
(396869,44097,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En général, ... peints à la main, comme ces bleus, coûtent plus cher que les unis.'::text,'les carreaux'::text,'les carreaux'::text,'un carreau'::text,'En général, les carreaux peints à la main, comme ces bleus, coûtent plus cher que les unis.'::text),
(396872,44097,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genel olarak, bu mavi olanlar gibi elle boyanmış ... düz olanlardan daha pahalıdır.'::text,'fayanslar'::text,'fayanslar'::text,'bir fayans'::text,'Genel olarak, bu mavi olanlar gibi elle boyanmış fayanslar düz olanlardan daha pahalıdır.'::text),
(396873,44097,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Általában a kézzel festett ..., mint ezek a kékek, többe kerülnek, mint a sima darabok.'::text,'csempék'::text,'csempék'::text,'egy csempe'::text,'Általában a kézzel festett csempék, mint ezek a kékek, többe kerülnek, mint a sima darabok.'::text),
(367230,40804,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ok also, angeblich ... er die Postkarte schon abgeschickt, bevor seine Freunde überhaupt aufgewacht sind.'::text,'hatte'::text,'hat'::text,'schickt'::text,'Ok also, angeblich hatte er die Postkarte schon abgeschickt, bevor seine Freunde überhaupt aufgewacht sind.'::text),
(367234,40804,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ок, отже, кажуть, він ... листівку ще до того, як його друзі взагалі прокинулися.'::text,'відправив'::text,'відправив'::text,'відправляє'::text,'Ок, отже, кажуть, він відправив листівку ще до того, як його друзі взагалі прокинулися.'::text),
(367233,40804,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ok, pues al parecer él ... la postal antes de que sus amigos se despertaran.'::text,'había enviado'::text,'ha enviado'::text,'envía'::text,'Ok, pues al parecer él había enviado la postal antes de que sus amigos se despertaran.'::text),
(367232,40804,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ok donc apparemment il ... la carte postale avant même que ses amis se réveillent.'::text,'avait posté'::text,'a posté'::text,'poste'::text,'Ok donc apparemment il avait posté la carte postale avant même que ses amis se réveillent.'::text),
(367235,40804,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam yani, anlaşılan o, arkadaşları daha uyanmadan kartpostalı ...'::text,'postalamıştı'::text,'postaladı'::text,'postalıyor'::text,'Tamam yani, anlaşılan o, arkadaşları daha uyanmadan kartpostalı postalamıştı.'::text),
(367236,40804,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oké, szóval állítólag ő ... a képeslapot, mielőtt a barátai egyáltalán felébredtek.'::text,'feladta'::text,'feladta'::text,'feladja'::text,'Oké, szóval állítólag ő feladta a képeslapot, mielőtt a barátai egyáltalán felébredtek.'::text),
(367248,40806,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee, warum hat er die Postkarte nicht vom Café ... lassen? Irgendwie faule Idee.'::text,'abschicken'::text,'abschicken'::text,'abschicken'::text,'Nee, warum hat er die Postkarte nicht vom Café abschicken lassen? Irgendwie faule Idee.'::text),
(367252,40806,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Та ні, чому він не попросив кафе ... листівку за нього? Трохи лінива ідея.'::text,'відправити'::text,'відправити'::text,'відправлення'::text,'Та ні, чому він не попросив кафе відправити листівку за нього? Трохи лінива ідея.'::text),
(367251,40806,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué va, ¿por qué él no le pidió a la cafetería que ... la postal? Idea medio vaga.'::text,'enviara'::text,'enviara'::text,'enviando'::text,'Qué va, ¿por qué él no le pidió a la cafetería que enviara la postal? Idea medio vaga.'::text),
(367250,40806,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nan, pourquoi il n''a pas fait ... la carte postale par le café ? Idée un peu flemmarde.'::text,'envoyer'::text,'envoyer'::text,'envoyant'::text,'Nan, pourquoi il n''a pas fait envoyer la carte postale par le café ? Idée un peu flemmarde.'::text),
(367253,40806,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok ya, o neden kartpostalı kafeye ...? Biraz tembel fikir.'::text,'postalatmadı'::text,'postalatmadı'::text,'postalatmadı'::text,'Yok ya, o neden kartpostalı kafeye postalatmadı? Biraz tembel fikir.'::text),
(367254,40806,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Á, ő miért nem ... fel a képeslapot a kávézóval? Kicsit lusta ötlet.'::text,'adatta'::text,'adatta'::text,'adatta'::text,'Á, ő miért nem adatta fel a képeslapot a kávézóval? Kicsit lusta ötlet.'::text),
(371991,41333,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Bewohner nicht zu Hause ist, ... der Postbote das Paket bei einem Nachbarn.'::text,'lässt'::text,'würde lassen'::text,'ließ'::text,'Wenn der Bewohner nicht zu Hause ist, lässt der Postbote das Paket bei einem Nachbarn.'::text),
(371995,41333,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо мешканця немає вдома, листоноша ... посилку в сусіда.'::text,'залишить'::text,'залишив би'::text,'залишив'::text,'Якщо мешканця немає вдома, листоноша залишить посилку в сусіда.'::text),
(371994,41333,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el residente no está en casa, el cartero ... el paquete con un vecino.'::text,'dejará'::text,'dejaría'::text,'dejó'::text,'Si el residente no está en casa, el cartero dejará el paquete con un vecino.'::text),
(371993,41333,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si l''habitant n''est pas chez lui, le facteur ... le colis chez un voisin.'::text,'laissera'::text,'laisserait'::text,'a laissé'::text,'Si l''habitant n''est pas chez lui, le facteur laissera le colis chez un voisin.'::text),
(371996,41333,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ev sahibi evde değilse, postacı paketi bir komşuya ...'::text,'bırakacak'::text,'bırakırdı'::text,'bıraktı'::text,'Ev sahibi evde değilse, postacı paketi bir komşuya bırakacak.'::text),
(371997,41333,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a lakó nincs otthon, a postás ... a csomagot egy szomszédnál.'::text,'hagyja'::text,'hagyná'::text,'hagyta'::text,'Ha a lakó nincs otthon, a postás hagyja a csomagot egy szomszédnál.'::text),
(372081,41343,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katastrophe! Er ... seit zehn Minuten an die Tür, und das Paket ist immer noch in seinen Händen!'::text,'klopft'::text,'klopft'::text,'klopft'::text,'Katastrophe! Er klopft seit zehn Minuten an die Tür, und das Paket ist immer noch in seinen Händen!'::text),
(372085,41343,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Катастрофа! Він ... у двері вже десять хвилин, а посилка досі в нього в руках!'::text,'стукає'::text,'стукає'::text,'стукає'::text,'Катастрофа! Він стукає у двері вже десять хвилин, а посилка досі в нього в руках!'::text),
(372084,41343,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Desastre! ¡Él ... a la puerta diez minutos y el paquete sigue en sus manos!'::text,'lleva llamando'::text,'está llamando'::text,'llama'::text,'¡Desastre! ¡Él lleva llamando a la puerta diez minutos y el paquete sigue en sus manos!'::text),
(372083,41343,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Catastrophe ! Il ... à la porte depuis dix minutes, et le colis est toujours dans ses mains !'::text,'frappe'::text,'frappe'::text,'frappe'::text,'Catastrophe ! Il frappe à la porte depuis dix minutes, et le colis est toujours dans ses mains !'::text),
(372086,41343,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Felaket! O on dakikadır kapıyı ... ve paket hâlâ elinde!'::text,'çalıyor'::text,'çalıyor'::text,'çalar'::text,'Felaket! O on dakikadır kapıyı çalıyor ve paket hâlâ elinde!'::text),
(372087,41343,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katasztrófa! Ő tíz perce ... az ajtón, és a csomag még mindig a kezében van!'::text,'kopog'::text,'kopog'::text,'kopog'::text,'Katasztrófa! Ő tíz perce kopog az ajtón, és a csomag még mindig a kezében van!'::text),
(333642,37072,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Teig ... wiederholt mit einem schweren Gummihammer geschlagen, wie auf dem bemehlten Tisch beobachtet.'::text,'wurde'::text,'schlug'::text,'schlagend'::text,'Der Teig wurde wiederholt mit einem schweren Gummihammer geschlagen, wie auf dem bemehlten Tisch beobachtet.'::text),
(333646,37072,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Тісто ... раз у раз важким гумовим молотком, як було помічено на присипаному борошном столі.'::text,'відбивали'::text,'відбивало'::text,'відбиваючи'::text,'Тісто відбивали раз у раз важким гумовим молотком, як було помічено на присипаному борошном столі.'::text),
(333645,37072,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La masa ... repetidamente con un pesado mazo de goma, según se observó en la mesa enharinada.'::text,'fue golpeada'::text,'golpeó'::text,'golpeando'::text,'La masa fue golpeada repetidamente con un pesado mazo de goma, según se observó en la mesa enharinada.'::text),
(333644,37072,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La pâte ... à plusieurs reprises avec un lourd maillet en caoutchouc, comme observé sur la table farinée.'::text,'a été frappée'::text,'a frappé'::text,'frappant'::text,'La pâte a été frappée à plusieurs reprises avec un lourd maillet en caoutchouc, comme observé sur la table farinée.'::text),
(333647,37072,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Unlu masada gözlemlendiği gibi, hamur ağır bir lastik tokmakla defalarca ...'::text,'dövüldü'::text,'dövdü'::text,'dövme'::text,'Unlu masada gözlemlendiği gibi, hamur ağır bir lastik tokmakla defalarca dövüldü.'::text),
(333648,37072,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tésztát többször ... egy nehéz gumikalapáccsal, ahogy a lisztes asztalon megfigyelték.'::text,'megütötték'::text,'ütötte'::text,'ütve'::text,'A tésztát többször megütötték egy nehéz gumikalapáccsal, ahogy a lisztes asztalon megfigyelték.'::text),
(333696,37078,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Im Moment ... die Frau mit den Handflächen kräftig auf die Trommel.'::text,'schlägt'::text,'schlägt'::text,'hat geschlagen'::text,'Im Moment schlägt die Frau mit den Handflächen kräftig auf die Trommel.'::text),
(333700,37078,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зараз жінка щосили ... долонями по барабану.'::text,'б''є'::text,'б''є'::text,'вдарила'::text,'Зараз жінка щосили б''є долонями по барабану.'::text),
(333699,37078,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En este momento, la mujer ... el tambor con fuerza con las palmas.'::text,'está golpeando'::text,'golpea'::text,'ha golpeado'::text,'En este momento, la mujer está golpeando el tambor con fuerza con las palmas.'::text),
(333698,37078,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment, la femme ... fort sur le tambour avec ses paumes.'::text,'tape'::text,'tape'::text,'a tapé'::text,'En ce moment, la femme tape fort sur le tambour avec ses paumes.'::text),
(333701,37078,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda kadın avuçlarıyla davula sertçe ...'::text,'vuruyor'::text,'vurur'::text,'vurdu'::text,'Şu anda kadın avuçlarıyla davula sertçe vuruyor.'::text),
(333702,37078,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp most a nő erősen ... a dobot a tenyerével.'::text,'üti'::text,'üti'::text,'ütötte'::text,'Épp most a nő erősen üti a dobot a tenyerével.'::text),
(339861,37763,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie noch ein Glas so einschenkt, ... der Tisch noch fröhlicher.'::text,'wird'::text,'würde'::text,'wurde'::text,'Wenn sie noch ein Glas so einschenkt, wird der Tisch noch fröhlicher.'::text),
(339865,37763,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо вона наллє ще одну склянку так, за столом ... ще веселіше.'::text,'стане'::text,'стало б'::text,'стало'::text,'Якщо вона наллє ще одну склянку так, за столом стане ще веселіше.'::text),
(339864,37763,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si ella sirve un vaso más así, la mesa ... aún más alegre.'::text,'se pondrá'::text,'se pondría'::text,'se puso'::text,'Si ella sirve un vaso más así, la mesa se pondrá aún más alegre.'::text),
(339863,37763,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle verse un verre de plus comme ça, la tablée ... encore plus joyeuse.'::text,'deviendra'::text,'deviendrait'::text,'est devenue'::text,'Si elle verse un verre de plus comme ça, la tablée deviendra encore plus joyeuse.'::text),
(339866,37763,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O bir bardak daha böyle doldurursa, masa daha da neşeli ...'::text,'olacak'::text,'olurdu'::text,'oldu'::text,'O bir bardak daha böyle doldurursa, masa daha da neşeli olacak.'::text),
(339867,37763,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha ő még egy poharat így tölt, az asztal még vidámabb ...'::text,'lesz'::text,'lenne'::text,'lett'::text,'Ha ő még egy poharat így tölt, az asztal még vidámabb lesz.'::text),
(370227,41137,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als er die Kanne senkte, ... alle, die auf seinen Schnurrbart starrten, völlig verstummt!'::text,'waren'::text,'sind'::text,'werden'::text,'Als er die Kanne senkte, waren alle, die auf seinen Schnurrbart starrten, völlig verstummt!'::text),
(370231,41137,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли він опустив чайник, усі, хто витріщався на його вуса, ... зовсім!'::text,'замовкли'::text,'замовкли'::text,'замовкають'::text,'Коли він опустив чайник, усі, хто витріщався на його вуса, замовкли зовсім!'::text),
(370230,41137,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Para cuando él bajó la tetera, todos los que miraban su bigote ... completamente callados!'::text,'se habían quedado'::text,'se han quedado'::text,'se quedan'::text,'¡Para cuando él bajó la tetera, todos los que miraban su bigote se habían quedado completamente callados!'::text),
(370229,41137,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand il a baissé la théière, tous ceux qui fixaient sa moustache ... complètement silencieux !'::text,'étaient devenus'::text,'sont devenus'::text,'deviennent'::text,'Quand il a baissé la théière, tous ceux qui fixaient sa moustache étaient devenus complètement silencieux !'::text),
(370232,41137,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, demliği indirdiğinde, bıyığına bakan herkes tamamen ...!'::text,'susmuştu'::text,'sustu'::text,'susuyor'::text,'O, demliği indirdiğinde, bıyığına bakan herkes tamamen susmuştu!'::text),
(370233,41137,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire ő leengedte a kannát, mindenki, aki a bajuszát bámulta, teljesen ...!'::text,'elhallgatott'::text,'elhallgatott'::text,'elhallgat'::text,'Mire ő leengedte a kannát, mindenki, aki a bajuszát bámulta, teljesen elhallgatott!'::text),
(370281,41143,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt: Du ... diesen Guss schon jahrelang vor heute Abend geübt, und kein einziger Tropfen hat den Schnurrbart getroffen.'::text,'hattest'::text,'hast'::text,'warst'::text,'Respekt: Du hattest diesen Guss schon jahrelang vor heute Abend geübt, und kein einziger Tropfen hat den Schnurrbart getroffen.'::text),
(370285,41143,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Респект: ти ... це наливання роками до сьогоднішнього вечора, і жодна крапля не влучила у вуса.'::text,'тренував'::text,'тренуєш'::text,'тренував'::text,'Респект: ти тренував це наливання роками до сьогоднішнього вечора, і жодна крапля не влучила у вуса.'::text),
(370284,41143,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respeto: tú ... ese vertido durante años antes de esta noche, y ni una gota tocó el bigote.'::text,'habías estado practicando'::text,'has estado practicando'::text,'estabas practicando'::text,'Respeto: tú habías estado practicando ese vertido durante años antes de esta noche, y ni una gota tocó el bigote.'::text),
(370283,41143,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respect : tu ... ce versement pendant des années avant ce soir, et pas une goutte n''a touché la moustache.'::text,'avais pratiqué'::text,'as pratiqué'::text,'pratiquais'::text,'Respect : tu avais pratiqué ce versement pendant des années avant ce soir, et pas une goutte n''a touché la moustache.'::text),
(370286,41143,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saygılar: sen bu akşamdan önce yıllarca o dökmeyi ... ve tek bir damla bıyığa değmedi.'::text,'çalışmıştın'::text,'çalışıyorsun'::text,'çalışıyordun'::text,'Saygılar: sen bu akşamdan önce yıllarca o dökmeyi çalışmıştın ve tek bir damla bıyığa değmedi.'::text),
(370287,41143,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt: te évekig ... ezt a töltést a ma este előtt, és egyetlen csepp sem ment a bajuszra.'::text,'gyakoroltad'::text,'gyakorlod'::text,'gyakoroltad'::text,'Respekt: te évekig gyakoroltad ezt a töltést a ma este előtt, és egyetlen csepp sem ment a bajuszra.'::text),
(359562,39952,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, sie trägt ein Kopftuch direkt neben einem heißen Ofen, ihr ... ziemlich warm sein.'::text,'muss'::text,'kann nicht'::text,'darf nicht'::text,'Bro, sie trägt ein Kopftuch direkt neben einem heißen Ofen, ihr muss ziemlich warm sein.'::text),
(359566,39952,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вона в хустці прямо біля гарячої духовки, їй ... досить жарко.'::text,'мабуть'::text,'не може бути'::text,'не мусить бути'::text,'Бро, вона в хустці прямо біля гарячої духовки, їй мабуть досить жарко.'::text),
(359565,39952,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ella lleva un pañuelo justo al lado de un horno caliente, ... tener bastante calor.'::text,'debe de'::text,'no puede'::text,'no debe'::text,'Bro, ella lleva un pañuelo justo al lado de un horno caliente, debe de tener bastante calor.'::text),
(359564,39952,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, elle porte un foulard juste à côté d''un four chaud, elle ... avoir assez chaud.'::text,'doit'::text,'ne peut pas'::text,'ne doit pas'::text,'Frérot, elle porte un foulard juste à côté d''un four chaud, elle doit avoir assez chaud.'::text),
(359567,39952,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o sıcak bir fırının hemen yanında başörtüsü takıyor, epey sıcaklamış ...'::text,'olmalı'::text,'olamaz'::text,'olmamalı'::text,'Kanka, o sıcak bir fırının hemen yanında başörtüsü takıyor, epey sıcaklamış olmalı.'::text),
(359568,39952,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ő fejkendőt visel egy forró sütő mellett, ... elég melege van.'::text,'biztos'::text,'nem lehet'::text,'nem szabad'::text,'Tesó, ő fejkendőt visel egy forró sütő mellett, biztos elég melege van.'::text),
(359634,39960,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis 17 Uhr ... sie jeden einzelnen Keks gebacken haben, und das Kopftuch wird für immer danach riechen!'::text,'wird'::text,'wird'::text,'wird gerade'::text,'Bis 17 Uhr wird sie jeden einzelnen Keks gebacken haben, und das Kopftuch wird für immer danach riechen!'::text),
(359638,39960,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До 17:00 вона ... кожне печиво, і та хустка пахнутиме ним назавжди!'::text,'спече'::text,'спече'::text,'пектиме'::text,'До 17:00 вона спече кожне печиво, і та хустка пахнутиме ним назавжди!'::text),
(359637,39960,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Para las 5 de la tarde, ella ... cada galleta, y ese pañuelo olerá a ellas para siempre!'::text,'habrá horneado'::text,'horneará'::text,'estará horneando'::text,'¡Para las 5 de la tarde, ella habrá horneado cada galleta, y ese pañuelo olerá a ellas para siempre!'::text),
(359636,39960,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici 17 h, elle ... chaque cookie, et ce foulard en gardera l''odeur pour toujours !'::text,'aura cuit'::text,'cuira'::text,'sera en train de cuire'::text,'D''ici 17 h, elle aura cuit chaque cookie, et ce foulard en gardera l''odeur pour toujours !'::text),
(359639,39960,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saat 17''ye kadar o her bir kurabiyeyi ... ve o başörtüsü sonsuza dek kurabiye kokacak!'::text,'pişirmiş olacak'::text,'pişirecek'::text,'pişiriyor olacak'::text,'Saat 17''ye kadar o her bir kurabiyeyi pişirmiş olacak ve o başörtüsü sonsuza dek kurabiye kokacak!'::text),
(359640,39960,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Délután 5-re ő ... minden egyes kekszet, és az a fejkendő örökre keksz illatú lesz!'::text,'megsüti'::text,'meg fogja sütni'::text,'sütni fogja'::text,'Délután 5-re ő megsüti minden egyes kekszet, és az a fejkendő örökre keksz illatú lesz!'::text),
(378849,42095,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, bis 18 Uhr ... sie zwei Stunden am Stück in diesen heißen Ofen gegriffen haben, ohne Witz.'::text,'wird'::text,'wird'::text,'wird'::text,'Bro, bis 18 Uhr wird sie zwei Stunden am Stück in diesen heißen Ofen gegriffen haben, ohne Witz.'::text),
(378853,42095,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, до 18:00 вона ... до тієї гарячої духовки вже дві години поспіль, без жартів.'::text,'тягтиметься'::text,'тягтиметься'::text,'потягнеться'::text,'Бро, до 18:00 вона тягтиметься до тієї гарячої духовки вже дві години поспіль, без жартів.'::text),
(378852,42095,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, para las 6 de la tarde, ella ... dentro de ese horno caliente dos horas seguidas, sin mentir.'::text,'habrá estado metiendo la mano'::text,'estará metiendo la mano'::text,'meterá la mano'::text,'Bro, para las 6 de la tarde, ella habrá estado metiendo la mano dentro de ese horno caliente dos horas seguidas, sin mentir.'::text),
(378851,42095,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, à 18 h, ça fera deux heures d''affilée qu''elle ... dans ce four chaud, sans mentir.'::text,'plonge la main'::text,'plongera la main'::text,'plongera la main'::text,'Frérot, à 18 h, ça fera deux heures d''affilée qu''elle plonge la main dans ce four chaud, sans mentir.'::text),
(378854,42095,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, saat 18''e kadar o iki saattir aralıksız o sıcak fırına ...'::text,'uzanıyor olacak'::text,'uzanıyor olacak'::text,'uzanacak'::text,'Kanka, saat 18''e kadar o iki saattir aralıksız o sıcak fırına uzanıyor olacak.'::text),
(378855,42095,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, este 6-ra ő már két órája ... abba a forró sütőbe, komolyan.'::text,'nyúlkál'::text,'nyúlkálni fog'::text,'nyúl be'::text,'Tesó, este 6-ra ő már két órája nyúlkál abba a forró sütőbe, komolyan.'::text),
(387300,43034,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie sagte, sie ... ihre Unterschrift selbst geschrieben, weil es ihr eigener Name war.'::text,'habe'::text,'hat'::text,'schreibt'::text,'Sie sagte, sie habe ihre Unterschrift selbst geschrieben, weil es ihr eigener Name war.'::text),
(387304,43034,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона сказала, що ... свій підпис сама, бо це було її власне ім''я.'::text,'написала'::text,'написала'::text,'пише'::text,'Вона сказала, що написала свій підпис сама, бо це було її власне ім''я.'::text),
(387303,43034,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella dijo que ... su firma ella misma porque era su propio nombre.'::text,'había escrito'::text,'ha escrito'::text,'escribe'::text,'Ella dijo que había escrito su firma ella misma porque era su propio nombre.'::text),
(387302,43034,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a dit qu''elle ... sa signature elle-même parce que c''était son propre nom.'::text,'avait écrit'::text,'a écrit'::text,'écrit'::text,'Elle a dit qu''elle avait écrit sa signature elle-même parce que c''était son propre nom.'::text),
(387305,43034,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, imzasını kendisinin ... söyledi çünkü bu kendi adıydı.'::text,'attığını'::text,'attığını'::text,'attığını'::text,'O, imzasını kendisinin attığını söyledi çünkü bu kendi adıydı.'::text),
(387306,43034,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő azt mondta, hogy maga ... az aláírását, mert az a saját neve volt.'::text,'írta'::text,'írta'::text,'írja'::text,'Ő azt mondta, hogy maga írta az aláírását, mert az a saját neve volt.'::text),
(329061,36563,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie erzählte einem Passanten, dass sie das Wandbild in der Woche davor begonnen ..., ihre größte Leistung.'::text,'hatte'::text,'hat'::text,'beginnt'::text,'Sie erzählte einem Passanten, dass sie das Wandbild in der Woche davor begonnen hatte, ihre größte Leistung.'::text),
(329065,36563,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона сказала перехожому, що ... настінний розпис тижнем раніше, її найбільше досягнення.'::text,'почала'::text,'почала'::text,'починає'::text,'Вона сказала перехожому, що почала настінний розпис тижнем раніше, її найбільше досягнення.'::text),
(329064,36563,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella le dijo a un transeúnte que ... el mural la semana anterior, su mayor logro.'::text,'había empezado'::text,'ha empezado'::text,'empieza'::text,'Ella le dijo a un transeúnte que había empezado el mural la semana anterior, su mayor logro.'::text),
(329063,36563,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a dit à un passant qu''elle ... la fresque la semaine d''avant, sa plus grande réussite.'::text,'avait commencé'::text,'a commencé'::text,'commence'::text,'Elle a dit à un passant qu''elle avait commencé la fresque la semaine d''avant, sa plus grande réussite.'::text),
(329066,36563,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, bir yoldan geçene duvar resmine bir hafta önce ... söyledi; en büyük başarısı.'::text,'başladığını'::text,'başladığını'::text,'başladığını'::text,'O, bir yoldan geçene duvar resmine bir hafta önce başladığını söyledi; en büyük başarısı.'::text),
(329067,36563,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő elmondta egy járókelőnek, hogy az előző héten ... a falfestményt, a legnagyobb eredményét.'::text,'kezdte el'::text,'kezdte el'::text,'kezdi el'::text,'Ő elmondta egy járókelőnek, hogy az előző héten kezdte el a falfestményt, a legnagyobb eredményét.'::text),
(329106,36568,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, sie ... die ganze Woche an dieser Wand gemalt, also war das Wandbild eine riesige Leistung, echt.'::text,'hatte'::text,'hat'::text,'war'::text,'Bro, sie hatte die ganze Woche an dieser Wand gemalt, also war das Wandbild eine riesige Leistung, echt.'::text),
(329110,36568,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вона ... на тій стіні цілий тиждень, тож той розпис був величезним досягненням, чесно.'::text,'малювала'::text,'малює'::text,'малювала'::text,'Бро, вона малювала на тій стіні цілий тиждень, тож той розпис був величезним досягненням, чесно.'::text),
(329109,36568,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ella ... en esa pared toda la semana, así que ese mural fue un logro enorme, en serio.'::text,'había estado pintando'::text,'ha estado pintando'::text,'estaba pintando'::text,'Bro, ella había estado pintando en esa pared toda la semana, así que ese mural fue un logro enorme, en serio.'::text),
(329108,36568,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, elle ... sur ce mur toute la semaine, donc cette fresque était une énorme réussite, sérieux.'::text,'avait peint'::text,'a peint'::text,'peignait'::text,'Frérot, elle avait peint sur ce mur toute la semaine, donc cette fresque était une énorme réussite, sérieux.'::text),
(329111,36568,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o bütün hafta o duvarda resim ..., yani o duvar resmi dev bir başarıydı, cidden.'::text,'yapmıştı'::text,'yapıyor'::text,'yapıyordu'::text,'Kanka, o bütün hafta o duvarda resim yapmıştı, yani o duvar resmi dev bir başarıydı, cidden.'::text),
(329112,36568,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ő egész héten ... azon a falon, szóval az a falfestmény óriási eredmény volt, komolyan.'::text,'festett'::text,'fest'::text,'festett'::text,'Tesó, ő egész héten festett azon a falon, szóval az a falfestmény óriási eredmény volt, komolyan.'::text),
(372954,41440,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum Ende der Vorlesung ... der leidenschaftliche Professor die ganze Tafel mit Pfeilen vollgeschrieben haben.'::text,'wird'::text,'wird'::text,'schreibt'::text,'Bis zum Ende der Vorlesung wird der leidenschaftliche Professor die ganze Tafel mit Pfeilen vollgeschrieben haben.'::text),
(372958,41440,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До кінця лекції пристрасний професор ... всю дошку стрілками.'::text,'вкриє'::text,'вкриватиме'::text,'вкриває'::text,'До кінця лекції пристрасний професор вкриє всю дошку стрілками.'::text),
(372957,41440,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el final de la clase, el apasionado profesor ... toda la pizarra de flechas.'::text,'habrá llenado'::text,'llenará'::text,'llena'::text,'Para el final de la clase, el apasionado profesor habrá llenado toda la pizarra de flechas.'::text),
(372956,41440,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici la fin du cours, le professeur passionné ... tout le tableau de flèches.'::text,'aura couvert'::text,'couvrira'::text,'couvre'::text,'D''ici la fin du cours, le professeur passionné aura couvert tout le tableau de flèches.'::text),
(372959,41440,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dersin sonuna kadar tutkulu profesör bütün tahtayı oklarla ...'::text,'doldurmuş olacak'::text,'dolduracak'::text,'dolduruyor'::text,'Dersin sonuna kadar tutkulu profesör bütün tahtayı oklarla doldurmuş olacak.'::text),
(372960,41440,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az előadás végére a szenvedélyes professzor ... az egész táblát nyilakkal.'::text,'teleírja'::text,'tele fogja írni'::text,'írja tele'::text,'Az előadás végére a szenvedélyes professzor teleírja az egész táblát nyilakkal.'::text),
(382044,42450,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um diese Zeit ... das Paar die romantische Neuigkeit feiern, wie Paare es typischerweise tun.'::text,'wird'::text,'wird'::text,'feiern'::text,'Morgen um diese Zeit wird das Paar die romantische Neuigkeit feiern, wie Paare es typischerweise tun.'::text),
(382048,42450,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра в цей час пара ... романтичну новину, як зазвичай роблять пари.'::text,'святкуватиме'::text,'відсвяткує'::text,'святкують'::text,'Завтра в цей час пара святкуватиме романтичну новину, як зазвичай роблять пари.'::text),
(382047,42450,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a esta hora, la pareja ... la noticia romántica, como suelen hacer las parejas.'::text,'estará celebrando'::text,'celebrará'::text,'celebran'::text,'Mañana a esta hora, la pareja estará celebrando la noticia romántica, como suelen hacer las parejas.'::text),
(382046,42450,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à cette heure-ci, le couple ... la nouvelle romantique, comme le font généralement les couples.'::text,'sera en train de fêter'::text,'fêtera'::text,'fêtent'::text,'Demain à cette heure-ci, le couple sera en train de fêter la nouvelle romantique, comme le font généralement les couples.'::text),
(382049,42450,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatte çift, çiftlerin genelde yaptığı gibi romantik haberi ...'::text,'kutluyor olacak'::text,'kutlayacak'::text,'kutlarlar'::text,'Yarın bu saatte çift, çiftlerin genelde yaptığı gibi romantik haberi kutluyor olacak.'::text),
(382050,42450,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap ilyenkor a pár ... a romantikus hírt, ahogy a párok általában teszik.'::text,'ünnepelni fogja'::text,'megünnepli'::text,'ünneplik'::text,'Holnap ilyenkor a pár ünnepelni fogja a romantikus hírt, ahogy a párok általában teszik.'::text),
(382080,42454,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gerade ... die Menge, während sich das romantische Paar auf der Brücke umarmt.'::text,'klatscht'::text,'klatscht'::text,'hat geklatscht'::text,'Gerade klatscht die Menge, während sich das romantische Paar auf der Brücke umarmt.'::text),
(382084,42454,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Просто зараз натовп ..., поки романтична пара обіймається на мосту.'::text,'аплодує'::text,'аплодує'::text,'зааплодував'::text,'Просто зараз натовп аплодує, поки романтична пара обіймається на мосту.'::text),
(382083,42454,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahora mismo, la multitud ... mientras la pareja romántica se abraza en el puente.'::text,'está aplaudiendo'::text,'aplaude'::text,'ha aplaudido'::text,'Ahora mismo, la multitud está aplaudiendo mientras la pareja romántica se abraza en el puente.'::text),
(382082,42454,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment, la foule ... pendant que le couple romantique s''enlace sur le pont.'::text,'applaudit'::text,'applaudit'::text,'a applaudi'::text,'En ce moment, la foule applaudit pendant que le couple romantique s''enlace sur le pont.'::text),
(382085,42454,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda romantik çift köprüde sarılırken kalabalık ...'::text,'alkışlıyor'::text,'alkışlar'::text,'alkışladı'::text,'Şu anda romantik çift köprüde sarılırken kalabalık alkışlıyor.'::text),
(382086,42454,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp most a tömeg ..., miközben a romantikus pár ölelkezik a hídon.'::text,'tapsol'::text,'tapsol'::text,'tapsolt'::text,'Épp most a tömeg tapsol, miközben a romantikus pár ölelkezik a hídon.'::text),
(363351,40373,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, es ... in Strömen, als dieser Fremde dem alten Mann echte Freundlichkeit zeigte, ohne Witz.'::text,'goss'::text,'goss'::text,'hat gegossen'::text,'Bro, es goss in Strömen, als dieser Fremde dem alten Mann echte Freundlichkeit zeigte, ohne Witz.'::text),
(363355,40373,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, ... як з відра, коли той незнайомець проявив до старого справжню доброту, без жартів.'::text,'лило'::text,'лило'::text,'лило'::text,'Бро, лило як з відра, коли той незнайомець проявив до старого справжню доброту, без жартів.'::text),
(363354,40373,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ... a cántaros cuando ese desconocido mostró verdadera amabilidad al anciano, sin mentir.'::text,'estaba lloviendo'::text,'llovió'::text,'ha llovido'::text,'Bro, estaba lloviendo a cántaros cuando ese desconocido mostró verdadera amabilidad al anciano, sin mentir.'::text),
(363353,40373,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, il ... des cordes quand cet inconnu a montré une vraie gentillesse au vieil homme, sans mentir.'::text,'pleuvait'::text,'a plu'::text,'a plu'::text,'Frérot, il pleuvait des cordes quand cet inconnu a montré une vraie gentillesse au vieil homme, sans mentir.'::text),
(363356,40373,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o yabancı yaşlı adama gerçek bir iyilik gösterdiğinde bardaktan boşanırcasına yağmur ..., yalan yok.'::text,'yağıyordu'::text,'yağdı'::text,'yağdı'::text,'Kanka, o yabancı yaşlı adama gerçek bir iyilik gösterdiğinde bardaktan boşanırcasına yağmur yağıyordu, yalan yok.'::text),
(363357,40373,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ... az eső, amikor az az idegen igazi kedvességet mutatott az öregúrnak, komolyan.'::text,'zuhogott'::text,'zuhogott'::text,'zuhogott'::text,'Tesó, zuhogott az eső, amikor az az idegen igazi kedvességet mutatott az öregúrnak, komolyan.'::text),
(363414,40380,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... des Fremden mit dem gelben Regenschirm brachte den alten Mann zum Lächeln.'::text,'Die Freundlichkeit'::text,'Eine Freundlichkeit'::text,'Freundlichkeit'::text,'Die Freundlichkeit des Fremden mit dem gelben Regenschirm brachte den alten Mann zum Lächeln.'::text),
(363418,40380,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... незнайомця з жовтою парасолькою змусила старого усміхнутися.'::text,'Доброта'::text,'Доброта'::text,'Доброта'::text,'Доброта незнайомця з жовтою парасолькою змусила старого усміхнутися.'::text),
(363417,40380,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... del desconocido del paraguas amarillo hizo sonreír al anciano.'::text,'La amabilidad'::text,'Una amabilidad'::text,'Amabilidad'::text,'La amabilidad del desconocido del paraguas amarillo hizo sonreír al anciano.'::text),
(363416,40380,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... de l''inconnu au parapluie jaune a fait sourire le vieil homme.'::text,'La gentillesse'::text,'Une gentillesse'::text,'Gentillesse'::text,'La gentillesse de l''inconnu au parapluie jaune a fait sourire le vieil homme.'::text),
(363419,40380,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sarı şemsiyeli yabancının ... yaşlı adamı gülümsetti.'::text,'iyiliği'::text,'bir iyiliği'::text,'iyiliği'::text,'Sarı şemsiyeli yabancının iyiliği yaşlı adamı gülümsetti.'::text),
(363420,40380,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A sárga esernyős idegen ... megmosolyogtatta az öregurat.'::text,'kedvessége'::text,'egy kedvessége'::text,'kedvessége'::text,'A sárga esernyős idegen kedvessége megmosolyogtatta az öregurat.'::text),
(401304,44590,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Warte, ich hab gehört, er hat den Wagen bis hierher gezogen, ...?'::text,'oder'::text,'nicht wahr'::text,'oder'::text,'Warte, ich hab gehört, er hat den Wagen bis hierher gezogen, oder?'::text),
(401308,44590,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Стривай, я чула, що він дотягнув той віз аж сюди, ...?'::text,'так'::text,'правда'::text,'так'::text,'Стривай, я чула, що він дотягнув той віз аж сюди, так?'::text),
(401307,44590,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Espera, oí que él arrastró ese carro hasta aquí, ¿...?'::text,'verdad'::text,'no'::text,'verdad'::text,'Espera, oí que él arrastró ese carro hasta aquí, ¿verdad?'::text),
(401306,44590,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Attends, j''ai entendu qu''il a tiré ce chariot jusqu''ici, ... ?'::text,'non'::text,'hein'::text,'non'::text,'Attends, j''ai entendu qu''il a tiré ce chariot jusqu''ici, non ?'::text),
(401309,44590,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dur, duydum ki o, şu arabayı buraya kadar çekmiş, ...?'::text,'değil mi'::text,'değil mi'::text,'değil mi'::text,'Dur, duydum ki o, şu arabayı buraya kadar çekmiş, değil mi?'::text),
(401310,44590,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Várj, úgy hallottam, hogy ő idáig húzta azt a kocsit, ...?'::text,'ugye'::text,'nem'::text,'ugye'::text,'Várj, úgy hallottam, hogy ő idáig húzta azt a kocsit, ugye?'::text),
(347781,38643,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, angeblich ließ er seinen Freund mit dem Kescher ..., und die Enttäuschung war echt.'::text,'herlaufen'::text,'herlaufen'::text,'lief her'::text,'Bestie, angeblich ließ er seinen Freund mit dem Kescher herlaufen, und die Enttäuschung war echt.'::text),
(347785,38643,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, він змусив друга ... із сачком, і розчарування було справжнє.'::text,'прибігти'::text,'прибігти'::text,'прибіг'::text,'Подруго, кажуть, він змусив друга прибігти із сачком, і розчарування було справжнє.'::text),
(347784,38643,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, al parecer él hizo que su amigo ... con la red, y la decepción fue real.'::text,'viniera corriendo'::text,'viniera corriendo'::text,'vino corriendo'::text,'Amiga, al parecer él hizo que su amigo viniera corriendo con la red, y la decepción fue real.'::text),
(347783,38643,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, apparemment il a fait ... son ami avec l''épuisette, et la déception était réelle.'::text,'accourir'::text,'accourir'::text,'accourait'::text,'Bestie, apparemment il a fait accourir son ami avec l''épuisette, et la déception était réelle.'::text),
(347786,38643,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, anlaşılan o arkadaşını kepçeyle ..., ve hayal kırıklığı gerçekti.'::text,'koşturttu'::text,'koşturttu'::text,'koşturttu'::text,'Kanka, anlaşılan o arkadaşını kepçeyle koşturttu, ve hayal kırıklığı gerçekti.'::text),
(347787,38643,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag ő ... a barátját a merítőhálóval, és a csalódás valódi volt.'::text,'odafuttatta'::text,'odafuttatta'::text,'odafutott'::text,'Csajszi, állítólag ő odafuttatta a barátját a merítőhálóval, és a csalódás valódi volt.'::text),
(361011,40113,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... weiter an diesem Seil, mit dem ganzen Horizont hinter dir. Ehrlich, Respekt.'::text,'ziehst'::text,'ziehst'::text,'ziehst'::text,'Du ziehst weiter an diesem Seil, mit dem ganzen Horizont hinter dir. Ehrlich, Respekt.'::text),
(361015,40113,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти все ... ту мотузку, а позаду тебе весь горизонт. Чесно, респект.'::text,'тягнеш'::text,'тягнути'::text,'тягнеш'::text,'Ти все тягнеш ту мотузку, а позаду тебе весь горизонт. Чесно, респект.'::text),
(361014,40113,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tú sigues ... esa cuerda con todo el horizonte detrás de ti. De verdad, respeto.'::text,'tirando de'::text,'tirar de'::text,'tirar de'::text,'Tú sigues tirando de esa cuerda con todo el horizonte detrás de ti. De verdad, respeto.'::text),
(361013,40113,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu continues à ... cette corde avec tout l''horizon derrière toi. Franchement, respect.'::text,'tirer'::text,'tirer'::text,'tirer'::text,'Tu continues à tirer cette corde avec tout l''horizon derrière toi. Franchement, respect.'::text),
(361016,40113,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sen arkanda koca ufukla o ipi ... duruyorsun. Açıkçası, saygılar.'::text,'çekip'::text,'çekmek'::text,'çek'::text,'Sen arkanda koca ufukla o ipi çekip duruyorsun. Açıkçası, saygılar.'::text),
(361017,40113,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Te csak ... azt a kötelet, mögötted az egész horizonttal. Őszintén, respekt.'::text,'húzod'::text,'húzni'::text,'húzd'::text,'Te csak húzod azt a kötelet, mögötted az egész horizonttal. Őszintén, respekt.'::text),
(361020,40114,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nicht ideal: Das Team ... seit einer Stunde hier, und der Horizont sieht immer noch genau gleich aus.'::text,'steht'::text,'steht'::text,'steht'::text,'Nicht ideal: Das Team steht seit einer Stunde hier, und der Horizont sieht immer noch genau gleich aus.'::text),
(361024,40114,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не ідеально: команда ... тут уже годину, а горизонт досі виглядає так само.'::text,'стоїть'::text,'стоїть'::text,'стоїть'::text,'Не ідеально: команда стоїть тут уже годину, а горизонт досі виглядає так само.'::text),
(361023,40114,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No es lo ideal: el equipo ... aquí una hora y el horizonte sigue exactamente igual.'::text,'lleva'::text,'está'::text,'está'::text,'No es lo ideal: el equipo lleva aquí una hora y el horizonte sigue exactamente igual.'::text),
(361022,40114,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pas idéal : l''équipe ... ici depuis une heure et l''horizon a toujours exactement le même aspect.'::text,'se tient'::text,'se tient'::text,'se tient'::text,'Pas idéal : l''équipe se tient ici depuis une heure et l''horizon a toujours exactement le même aspect.'::text),
(361025,40114,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pek ideal değil: ekip bir saattir burada ... ve ufuk hâlâ tamamen aynı görünüyor.'::text,'duruyor'::text,'duruyor'::text,'durur'::text,'Pek ideal değil: ekip bir saattir burada duruyor ve ufuk hâlâ tamamen aynı görünüyor.'::text),
(361026,40114,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem ideális: a csapat egy órája ... itt, és a horizont még mindig pontosan ugyanúgy néz ki.'::text,'áll'::text,'áll'::text,'áll'::text,'Nem ideális: a csapat egy órája áll itt, és a horizont még mindig pontosan ugyanúgy néz ki.'::text),
(378741,42083,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Creme auf ihrem Ausschlag brennt, ...?'::text,'oder'::text,'nicht wahr'::text,'was'::text,'Die Creme auf ihrem Ausschlag brennt, oder?'::text),
(378745,42083,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Крем на її висипі пече, ...?'::text,'так'::text,'правда'::text,'пече'::text,'Крем на її висипі пече, так?'::text),
(378744,42083,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La crema en su sarpullido escuece, ¿...?'::text,'verdad'::text,'no'::text,'sí'::text,'La crema en su sarpullido escuece, ¿verdad?'::text),
(378743,42083,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La crème sur son éruption pique, ... ?'::text,'non'::text,'hein'::text,'si'::text,'La crème sur son éruption pique, non ?'::text),
(378746,42083,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızarıklığındaki krem yakıyor, ...?'::text,'değil mi'::text,'değil mi'::text,'öyle mi'::text,'Kızarıklığındaki krem yakıyor, değil mi?'::text),
(378747,42083,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A krém a kiütésén csíp, ...?'::text,'ugye'::text,'nem'::text,'igen'::text,'A krém a kiütésén csíp, ugye?'::text),
(378804,42090,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie wünschte, sie ... heute Morgen Handschuhe getragen; der Ausschlag ist nur ein kleines bisschen nervig.'::text,'hätte'::text,'trug'::text,'würde'::text,'Sie wünschte, sie hätte heute Morgen Handschuhe getragen; der Ausschlag ist nur ein kleines bisschen nervig.'::text),
(378808,42090,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Їй би хотілося, щоб вона зранку ... рукавички; висип лише трішки дратує.'::text,'вдягла'::text,'вдягала'::text,'вдягне'::text,'Їй би хотілося, щоб вона зранку вдягла рукавички; висип лише трішки дратує.'::text),
(378807,42090,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella desearía ... guantes esta mañana; el sarpullido solo es un poquito molesto.'::text,'haber llevado'::text,'llevar'::text,'llevar'::text,'Ella desearía haber llevado guantes esta mañana; el sarpullido solo es un poquito molesto.'::text),
(378806,42090,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle aimerait ... des gants ce matin ; l''éruption n''est que légèrement agaçante.'::text,'avoir mis'::text,'mettre'::text,'mettre'::text,'Elle aimerait avoir mis des gants ce matin ; l''éruption n''est que légèrement agaçante.'::text),
(378809,42090,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O bu sabah eldiven ... keşke diyor; kızarıklık sadece birazcık can sıkıcı.'::text,'takmış olsaydı'::text,'taksaydı'::text,'takacak olsa'::text,'O bu sabah eldiven takmış olsaydı keşke diyor; kızarıklık sadece birazcık can sıkıcı.'::text),
(378810,42090,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő azt kívánja, bárcsak ma reggel ... kesztyűt; a kiütés csak egy kicsit bosszantó.'::text,'vett volna fel'::text,'venne fel'::text,'venne fel'::text,'Ő azt kívánja, bárcsak ma reggel vett volna fel kesztyűt; a kiütés csak egy kicsit bosszantó.'::text),
(336747,37417,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... ihre Haare jeden Morgen vor der Arbeit zu einem ordentlichen Dutt.'::text,'dreht'::text,'ist gedreht'::text,'drehend'::text,'Sie dreht ihre Haare jeden Morgen vor der Arbeit zu einem ordentlichen Dutt.'::text),
(336751,37417,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... волосся в акуратну гульку щоранку перед роботою.'::text,'скручує'::text,'скручена'::text,'скручування'::text,'Вона скручує волосся в акуратну гульку щоранку перед роботою.'::text),
(336750,37417,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella se ... el pelo en un moño perfecto cada mañana antes del trabajo.'::text,'recoge'::text,'es recogida'::text,'recogiendo'::text,'Ella se recoge el pelo en un moño perfecto cada mañana antes del trabajo.'::text),
(336749,37417,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... ses cheveux en un chignon net chaque matin avant le travail.'::text,'attache'::text,'est attachée'::text,'attachant'::text,'Elle attache ses cheveux en un chignon net chaque matin avant le travail.'::text),
(336752,37417,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O her sabah işten önce saçını düzgün bir topuz ...'::text,'yapar'::text,'yapılır'::text,'yapma'::text,'O her sabah işten önce saçını düzgün bir topuz yapar.'::text),
(336753,37417,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő minden reggel munka előtt takaros kontyba ... a haját.'::text,'csavarja'::text,'csavarva van'::text,'csavarás'::text,'Ő minden reggel munka előtt takaros kontyba csavarja a haját.'::text),
(336765,37419,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Mitternacht ... sie das ganze Buch durchgelesen haben, und ihr Dutt überlebt absolut alles!'::text,'wird'::text,'wird'::text,'liest'::text,'Bis Mitternacht wird sie das ganze Buch durchgelesen haben, und ihr Dutt überlebt absolut alles!'::text),
(336769,37419,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До півночі вона ... всю книжку, а її гулька переживе абсолютно все!'::text,'дочитає'::text,'дочитає'::text,'дочитує'::text,'До півночі вона дочитає всю книжку, а її гулька переживе абсолютно все!'::text),
(336768,37419,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Para la medianoche ella ... todo el libro, y su moño sobrevivirá a absolutamente todo!'::text,'habrá terminado'::text,'terminará'::text,'termina'::text,'¡Para la medianoche ella habrá terminado todo el libro, y su moño sobrevivirá a absolutamente todo!'::text),
(336767,37419,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici minuit, elle ... tout le livre, et son chignon survivra à absolument tout !'::text,'aura fini'::text,'finira'::text,'finit'::text,'D''ici minuit, elle aura fini tout le livre, et son chignon survivra à absolument tout !'::text),
(336770,37419,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gece yarısına kadar o bütün kitabı ... ve topuzu kesinlikle her şeye dayanacak!'::text,'bitirmiş olacak'::text,'bitirecek'::text,'bitiriyor'::text,'Gece yarısına kadar o bütün kitabı bitirmiş olacak ve topuzu kesinlikle her şeye dayanacak!'::text),
(336771,37419,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Éjfélre ő ... az egész könyvet, és a konty abszolút mindent túlél!'::text,'kiolvassa'::text,'ki fogja olvasni'::text,'olvassa ki'::text,'Éjfélre ő kiolvassa az egész könyvet, és a konty abszolút mindent túlél!'::text),
(379200,42134,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eine Frau rebellierte auf ihrem Schreibtisch, und natürlich ...'::text,'alle anderen auch.'::text,'alle anderen auch.'::text,'alle anderen auch.'::text,'Eine Frau rebellierte auf ihrem Schreibtisch, und natürlich alle anderen auch.'::text),
(379204,42134,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Одна жінка збунтувалася на своєму столі, і, звісно, ...'::text,'усі інші теж.'::text,'усі інші теж.'::text,'усі інші теж.'::text,'Одна жінка збунтувалася на своєму столі, і, звісно, усі інші теж.'::text),
(379203,42134,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Una mujer se rebeló sobre su mesa y, por supuesto, ...'::text,'todos los demás también.'::text,'todos los demás también.'::text,'todos los demás también.'::text,'Una mujer se rebeló sobre su mesa y, por supuesto, todos los demás también.'::text),
(379202,42134,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Une femme s''est rebellée sur son bureau, et bien sûr ...'::text,'tous les autres aussi.'::text,'tous les autres aussi.'::text,'tous les autres aussi.'::text,'Une femme s''est rebellée sur son bureau, et bien sûr tous les autres aussi.'::text),
(379205,42134,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir kadın masasının üstünde isyan etti ve tabii ki ...'::text,'herkes de etti.'::text,'herkes de öyleydi.'::text,'herkes de ediyor.'::text,'Bir kadın masasının üstünde isyan etti ve tabii ki herkes de etti.'::text),
(379206,42134,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy nő fellázadt az asztalán, és persze ...'::text,'mindenki más is.'::text,'mindenki más is.'::text,'mindenki más is.'::text,'Egy nő fellázadt az asztalán, és persze mindenki más is.'::text),
(379272,42142,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Mitarbeiter ... viel früher rebellieren sollen; die Regeln waren seit Jahren unfair.'::text,'hätten'::text,'müssen'::text,'konnten nicht'::text,'Die Mitarbeiter hätten viel früher rebellieren sollen; die Regeln waren seit Jahren unfair.'::text),
(379276,42142,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Працівники ... збунтуватися набагато раніше; правила були несправедливими роками.'::text,'мали б'::text,'мабуть мусили'::text,'не могли'::text,'Працівники мали б збунтуватися набагато раніше; правила були несправедливими роками.'::text),
(379275,42142,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los trabajadores ... rebelado mucho antes; las normas llevaban años siendo injustas.'::text,'deberían haberse'::text,'deben de haberse'::text,'no pudieron haberse'::text,'Los trabajadores deberían haberse rebelado mucho antes; las normas llevaban años siendo injustas.'::text),
(379274,42142,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les employés ... se rebeller beaucoup plus tôt ; les règles étaient injustes depuis des années.'::text,'auraient dû'::text,'ont dû'::text,'n''ont pas pu'::text,'Les employés auraient dû se rebeller beaucoup plus tôt ; les règles étaient injustes depuis des années.'::text),
(379277,42142,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çalışanlar çok daha önce ...; kurallar yıllardır adaletsizdi.'::text,'isyan etmeliydi'::text,'isyan etmiş olmalı'::text,'isyan edemedi'::text,'Çalışanlar çok daha önce isyan etmeliydi; kurallar yıllardır adaletsizdi.'::text),
(379278,42142,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A dolgozóknak sokkal korábban ... fellázadniuk; a szabályok évek óta igazságtalanok voltak.'::text,'kellett volna'::text,'biztos kellett'::text,'nem lehetett'::text,'A dolgozóknak sokkal korábban kellett volna fellázadniuk; a szabályok évek óta igazságtalanok voltak.'::text),
(385752,42862,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Ärztin ... den ganzen Vormittag Zettel wie diesen an Patienten aus.'::text,'teilt'::text,'teilt'::text,'teilt'::text,'Die Ärztin teilt den ganzen Vormittag Zettel wie diesen an Patienten aus.'::text),
(385756,42862,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Лікарка ... пацієнтам аркуші паперу, як цей, увесь ранок.'::text,'роздає'::text,'роздає'::text,'роздає'::text,'Лікарка роздає пацієнтам аркуші паперу, як цей, увесь ранок.'::text),
(385755,42862,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La doctora ... hojas como esta a los pacientes toda la mañana.'::text,'lleva dando'::text,'está dando'::text,'da'::text,'La doctora lleva dando hojas como esta a los pacientes toda la mañana.'::text),
(385754,42862,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La médecin ... des feuilles comme celle-ci aux patients toute la matinée.'::text,'distribue'::text,'distribue'::text,'distribue'::text,'La médecin distribue des feuilles comme celle-ci aux patients toute la matinée.'::text),
(385757,42862,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Doktor bütün sabah hastalara bunun gibi kâğıtlar ...'::text,'veriyor'::text,'veriyor'::text,'verir'::text,'Doktor bütün sabah hastalara bunun gibi kâğıtlar veriyor.'::text),
(385758,42862,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az orvos egész délelőtt ... a betegeknek az ehhez hasonló papírlapokat.'::text,'adja'::text,'adja'::text,'adja'::text,'Az orvos egész délelőtt adja a betegeknek az ehhez hasonló papírlapokat.'::text),
(355431,39493,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... gerade Zeile für Zeile dem Rezept, als die Kamera dich lächelnd erwischt hat. Irgendwie ikonisch.'::text,'folgtest'::text,'folgtest'::text,'bist gefolgt'::text,'Du folgtest gerade Zeile für Zeile dem Rezept, als die Kamera dich lächelnd erwischt hat. Irgendwie ikonisch.'::text),
(355435,39493,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ... рецепту рядок за рядком, коли камера впіймала твою усмішку. Доволі культово.'::text,'дотримувалася'::text,'дотрималася'::text,'дотрималася'::text,'Ти дотримувалася рецепту рядок за рядком, коли камера впіймала твою усмішку. Доволі культово.'::text),
(355434,39493,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tú ... la receta línea por línea cuando la cámara te pilló sonriendo. Bastante icónico.'::text,'estabas siguiendo'::text,'seguiste'::text,'has seguido'::text,'Tú estabas siguiendo la receta línea por línea cuando la cámara te pilló sonriendo. Bastante icónico.'::text),
(355433,39493,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ... la recette ligne par ligne quand la caméra t''a surprise en train de sourire. Plutôt iconique.'::text,'suivais'::text,'as suivi'::text,'as suivi'::text,'Tu suivais la recette ligne par ligne quand la caméra t''a surprise en train de sourire. Plutôt iconique.'::text),
(355436,39493,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kamera seni gülümserken yakaladığında sen tarifi satır satır ...; epey ikonik.'::text,'takip ediyordun'::text,'takip ettin'::text,'takip ettin'::text,'Kamera seni gülümserken yakaladığında sen tarifi satır satır takip ediyordun; epey ikonik.'::text),
(355437,39493,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Te sorról sorra ... a receptet, amikor a kamera elkapott mosolyogva. Elég ikonikus.'::text,'követted'::text,'követted'::text,'követted'::text,'Te sorról sorra követted a receptet, amikor a kamera elkapott mosolyogva. Elég ikonikus.'::text),
(355503,39501,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zur Deadline wird sie alle 8 Schritte des handgeschriebenen Rezepts ...'::text,'befolgt haben'::text,'befolgen'::text,'befolgt'::text,'Bis zur Deadline wird sie alle 8 Schritte des handgeschriebenen Rezepts befolgt haben.'::text),
(355507,39501,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До дедлайну вона ... всіх 8 кроків рукописного рецепта.'::text,'дотримається'::text,'дотримуватиметься'::text,'дотримується'::text,'До дедлайну вона дотримається всіх 8 кроків рукописного рецепта.'::text),
(355506,39501,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para la fecha límite, ella ... los 8 pasos de la receta escrita a mano.'::text,'habrá seguido'::text,'seguirá'::text,'sigue'::text,'Para la fecha límite, ella habrá seguido los 8 pasos de la receta escrita a mano.'::text),
(355505,39501,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici la deadline, elle ... les 8 étapes de la recette écrite à la main.'::text,'aura suivi'::text,'suivra'::text,'suit'::text,'D''ici la deadline, elle aura suivi les 8 étapes de la recette écrite à la main.'::text),
(355508,39501,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son tarihe kadar o el yazısı tarifin 8 adımının hepsini ...'::text,'uygulamış olacak'::text,'uygulayacak'::text,'uyguluyor'::text,'Son tarihe kadar o el yazısı tarifin 8 adımının hepsini uygulamış olacak.'::text),
(355509,39501,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A határidőre ő ... a kézzel írt recept mind a 8 lépését.'::text,'követi'::text,'követni fogja'::text,'követi'::text,'A határidőre ő követi a kézzel írt recept mind a 8 lépését.'::text),
(379812,42202,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während ein Verwandter die Torte durch die Tür ..., kamen die anderen den Weg herauf.'::text,'trug'::text,'trug'::text,'hat getragen'::text,'Während ein Verwandter die Torte durch die Tür trug, kamen die anderen den Weg herauf.'::text),
(379816,42202,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки один родич ... торт у двері, інші підходили доріжкою.'::text,'ніс'::text,'приніс'::text,'приніс'::text,'Поки один родич ніс торт у двері, інші підходили доріжкою.'::text),
(379815,42202,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mientras un familiar ... la tarta por la puerta, los demás subían por el camino.'::text,'llevaba'::text,'llevó'::text,'ha llevado'::text,'Mientras un familiar llevaba la tarta por la puerta, los demás subían por el camino.'::text),
(379814,42202,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant qu''un proche ... le gâteau par la porte, les autres remontaient l''allée.'::text,'portait'::text,'a porté'::text,'a porté'::text,'Pendant qu''un proche portait le gâteau par la porte, les autres remontaient l''allée.'::text),
(379817,42202,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir akraba pastayı kapıdan içeri ..., diğerleri yoldan geliyordu.'::text,'taşırken'::text,'taşıdığında'::text,'taşımışken'::text,'Bir akraba pastayı kapıdan içeri taşırken, diğerleri yoldan geliyordu.'::text),
(379818,42202,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Miközben az egyik rokon ... a tortát az ajtón, a többiek feljöttek az úton.'::text,'vitte be'::text,'bevitte'::text,'bevitte'::text,'Miközben az egyik rokon vitte be a tortát az ajtón, a többiek feljöttek az úton.'::text),
(379893,42211,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, als die Torte reinkam, ... jeder Verwandte schon zweimal Umarmungen verteilt, echt.'::text,'hatte'::text,'hat'::text,'war'::text,'Bro, als die Torte reinkam, hatte jeder Verwandte schon zweimal Umarmungen verteilt, echt.'::text),
(379897,42211,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, поки занесли торт, кожен родич ... вже двічі обійнявся, чесно.'::text,''::text,NULL::text,'був'::text,'Бро, поки занесли торт, кожен родич вже двічі обійнявся, чесно.'::text),
(379896,42211,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, para cuando llegó la tarta, cada familiar ya ... abrazado dos veces, en serio.'::text,'había'::text,'ha'::text,'estaba'::text,'Bro, para cuando llegó la tarta, cada familiar ya había abrazado dos veces, en serio.'::text),
(379895,42211,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, quand le gâteau est arrivé, chaque proche ... déjà fait deux câlins, sérieux.'::text,'avait'::text,'a'::text,'était'::text,'Frérot, quand le gâteau est arrivé, chaque proche avait déjà fait deux câlins, sérieux.'::text),
(379898,42211,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, pasta geldiğinde her akraba çoktan iki kez ... sarılmıştı, cidden.'::text,''::text,NULL::text,NULL::text,'Kanka, pasta geldiğinde her akraba çoktan iki kez sarılmıştı, cidden.'::text),
(379899,42211,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, mire bejött a torta, minden rokon ... már kétszer ölelkezett, komolyan.'::text,''::text,NULL::text,'volt'::text,'Tesó, mire bejött a torta, minden rokon már kétszer ölelkezett, komolyan.'::text),
(371379,41265,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... den Eid abgelegt, und alles in diesem Land wird sich für immer ändern!'::text,'hat'::text,'hat'::text,'legt'::text,'Sie hat den Eid abgelegt, und alles in diesem Land wird sich für immer ändern!'::text),
(371383,41265,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... присягу, і все в цій країні назавжди зміниться!'::text,'склала'::text,'складала'::text,'складає'::text,'Вона склала присягу, і все в цій країні назавжди зміниться!'::text),
(371382,41265,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ella ... el juramento, y todo en este país cambiará para siempre!'::text,'ha prestado'::text,'ha estado prestando'::text,'presta'::text,'¡Ella ha prestado el juramento, y todo en este país cambiará para siempre!'::text),
(371381,41265,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... serment, et tout dans ce pays va changer pour toujours !'::text,'a prêté'::text,'est en train de prêter'::text,'prête'::text,'Elle a prêté serment, et tout dans ce pays va changer pour toujours !'::text),
(371384,41265,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, yemin ... ve bu ülkede her şey sonsuza dek değişecek!'::text,'etti'::text,'ediyordu'::text,'eder'::text,'O, yemin etti ve bu ülkede her şey sonsuza dek değişecek!'::text),
(371385,41265,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő ... az esküt, és ebben az országban minden örökre megváltozik!'::text,'letette'::text,'tette'::text,'leteszi'::text,'Ő letette az esküt, és ebben az országban minden örökre megváltozik!'::text),
(371433,41271,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Im Moment ... sie den Eid mit der Hand auf dem offenen Buch ab.'::text,'legt'::text,'legt'::text,'hat'::text,'Im Moment legt sie den Eid mit der Hand auf dem offenen Buch ab.'::text),
(371437,41271,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зараз вона ... присягу, поклавши руку на розгорнуту книгу.'::text,'складає'::text,'складає'::text,'склала'::text,'Зараз вона складає присягу, поклавши руку на розгорнуту книгу.'::text),
(371436,41271,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En este momento ella ... el juramento con la mano sobre el libro abierto.'::text,'está prestando'::text,'presta'::text,'ha prestado'::text,'En este momento ella está prestando el juramento con la mano sobre el libro abierto.'::text),
(371435,41271,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment, elle ... serment, la main sur le livre ouvert.'::text,'prête'::text,'prête'::text,'a prêté'::text,'En ce moment, elle prête serment, la main sur le livre ouvert.'::text),
(371438,41271,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda o elini açık kitabın üzerine koymuş yemin ...'::text,'ediyor'::text,'eder'::text,'etti'::text,'Şu anda o elini açık kitabın üzerine koymuş yemin ediyor.'::text),
(371439,41271,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp most ő ... az esküt, kezét a nyitott könyvön tartva.'::text,'teszi le'::text,'teszi le'::text,'letette'::text,'Épp most ő teszi le az esküt, kezét a nyitott könyvön tartva.'::text),
(394725,43859,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Girl, er hat mir erzählt, dass ihm der Schweiß schon in die Augen ..., als sie oben ankamen.'::text,'gelaufen war'::text,'gelaufen ist'::text,'läuft'::text,'Girl, er hat mir erzählt, dass ihm der Schweiß schon in die Augen gelaufen war, als sie oben ankamen.'::text),
(394729,43859,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, він мені сказав, що коли вони дісталися вершини, піт уже ... йому в очі.'::text,'стік'::text,'стік'::text,'стікає'::text,'Подруго, він мені сказав, що коли вони дісталися вершини, піт уже стік йому в очі.'::text),
(394728,43859,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, él me dijo que el sudor ya le ... en los ojos cuando llegaron a la cima.'::text,'había entrado'::text,'ha entrado'::text,'entra'::text,'Tía, él me dijo que el sudor ya le había entrado en los ojos cuando llegaron a la cima.'::text),
(394727,43859,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, il m''a dit que la sueur lui ... dans les yeux quand ils sont arrivés en haut.'::text,'avait coulé'::text,'a coulé'::text,'coule'::text,'Meuf, il m''a dit que la sueur lui avait coulé dans les yeux quand ils sont arrivés en haut.'::text),
(394730,43859,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, o bana zirveye vardıklarında terin gözlerine çoktan ... söyledi.'::text,'aktığını'::text,'aktığını'::text,'aktığını'::text,'Kızım, o bana zirveye vardıklarında terin gözlerine çoktan aktığını söyledi.'::text),
(394731,43859,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, ő azt mondta nekem, hogy mire felértek a csúcsra, a veríték már ... a szemébe.'::text,'befolyt'::text,'befolyt'::text,'folyik'::text,'Csajszi, ő azt mondta nekem, hogy mire felértek a csúcsra, a veríték már befolyt a szemébe.'::text),
(345315,38369,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Girl, er hat mir erzählt, dass er nächste Woche um diese Zeit in Marrakesch marokkanische Küche ...'::text,'probieren wird'::text,'probieren wird'::text,'probiert'::text,'Girl, er hat mir erzählt, dass er nächste Woche um diese Zeit in Marrakesch marokkanische Küche probieren wird.'::text),
(345319,38369,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, він мені сказав, що наступного тижня в цей час ... марокканську кухню в Марракеші.'::text,'куштуватиме'::text,'скуштує'::text,'куштує'::text,'Подруго, він мені сказав, що наступного тижня в цей час куштуватиме марокканську кухню в Марракеші.'::text),
