(345317,38369,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, il m''a dit que la semaine prochaine à cette heure-ci, il ... la cuisine marocaine à Marrakech.'::text,'sera en train de goûter'::text,'goûtera'::text,'goûte'::text,'Meuf, il m''a dit que la semaine prochaine à cette heure-ci, il sera en train de goûter la cuisine marocaine à Marrakech.'::text),
(345320,38369,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, o bana gelecek hafta bu saatlerde Marakeş''te Fas mutfağını ... söyledi.'::text,'tadıyor olacağını'::text,'tadacağını'::text,'tattığını'::text,'Kızım, o bana gelecek hafta bu saatlerde Marakeş''te Fas mutfağını tadıyor olacağını söyledi.'::text),
(345321,38369,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, ő azt mondta nekem, hogy jövő héten ilyenkor a marokkói konyhát ... Marrákesben.'::text,'fogja kóstolni'::text,'megkóstolja'::text,'kóstolja'::text,'Csajszi, ő azt mondta nekem, hogy jövő héten ilyenkor a marokkói konyhát fogja kóstolni Marrákesben.'::text),
(345405,38379,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Girl, ich hab gehört, dass er, als er die Dachterrasse erreichte, schon drei Küchen an einem Tag ...'::text,'probiert hatte'::text,'probiert hat'::text,'probierte'::text,'Girl, ich hab gehört, dass er, als er die Dachterrasse erreichte, schon drei Küchen an einem Tag probiert hatte.'::text),
(345409,38379,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, я чула, що поки він дістався даху, він уже ... три кухні за один день.'::text,'скуштував'::text,'скуштував'::text,'куштував'::text,'Подруго, я чула, що поки він дістався даху, він уже скуштував три кухні за один день.'::text),
(345408,38379,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, oí que para cuando él llegó a la azotea, ya ... tres cocinas en un día.'::text,'había probado'::text,'ha probado'::text,'estaba probando'::text,'Tía, oí que para cuando él llegó a la azotea, ya había probado tres cocinas en un día.'::text),
(345407,38379,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, j''ai entendu que quand il est arrivé sur le toit, il ... trois cuisines en une journée.'::text,'avait goûté'::text,'a goûté'::text,'goûtait'::text,'Meuf, j''ai entendu que quand il est arrivé sur le toit, il avait goûté trois cuisines en une journée.'::text),
(345410,38379,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, duydum ki o, terasa vardığında bir günde üç mutfak ...'::text,'denemişti'::text,'denedi'::text,'deniyordu'::text,'Kızım, duydum ki o, terasa vardığında bir günde üç mutfak denemişti.'::text),
(345411,38379,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, úgy hallottam, hogy mire ő felért a tetőteraszra, már három konyhát ... egy nap alatt.'::text,'kipróbált'::text,'kipróbált'::text,'próbált'::text,'Csajszi, úgy hallottam, hogy mire ő felért a tetőteraszra, már három konyhát kipróbált egy nap alatt.'::text)
) v(id, eid, lang, n_intro_text, n_correct_answer, n_distractor_1, n_distractor_2, n_full_sentence, o_intro_text, o_correct_answer, o_distractor_1, o_distractor_2, o_full_sentence)
